window.VOCAB = (window.VOCAB||[]).concat([{"w": "abase", "pos": "verb", "pron": "uh-BASE", "also": "abased (adj), abasement (noun)", "d1": "Degrade or humble; to lower in rank, status, or esteem", "sent": "After messing up at work, the man faced a thorough <b>abasement</b> from his boss; when he realized he had forgotten his own wedding anniversary, he further <b>abased</b> himself in front of his wife.", "related": "Defame (attack the reputation of), Belittle (put down, disparage) Memory Trick: Abasement means degradation or lowering of status—that is, abasement makes you feel like you should go hide in a basement.", "moreinfo": "", "hook": "a + base: bring someone down to a low \"base\" level, humble them.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "abeyance", "pos": "noun", "pron": "uh-BAY-enss", "also": "", "d1": "Temporary suspension, inactivity", "sent": "The baseball player’s contract negotiations are in <b>abeyance</b> while doctors try to determine whether his injuries will heal in time for the season.", "related": "Hiatus (break or gap in an activity), Dormant (inactive, resting), Deferment or Deferral (postponement)", "moreinfo": "Abeyance generally occurs in the expression “in abeyance.” Real estate is in abeyance when no one owns it or the owner is unknown.", "hook": "hold it in the \"bay,\" a holding bay: temporary suspension.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "abreast", "pos": "adj", "pron": "uh-BREST", "also": "", "d1": "Side-by-side. The more common “abreast of” means keeping up with, staying aware of, or remaining equal in progress with.", "sent": "As the professor walked <b>abreast</b> down the street with her mentor, she was amazed that the old man, long since retired, still kept <b>abreast</b> of all the latest developments in neurobiology.", "related": "Conversant with (familiar by use or study), well versed in (experienced, skilled)", "moreinfo": "You are conversant with a topic about which you know enough to have an intelligent conversation. Well versed is stronger, implying some expertise. Keeping abreast of a topic implies that you are continually updating your knowledge.", "hook": "a + breast: chests side by side; \"abreast of\" the news means keeping up alongside it.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "abscission", "pos": "noun", "pron": "ab-SIZZ-zhun", "also": "", "d1": "Cutting off; sudden termination; the separation of leaves, petals, or other parts from a plant or animal", "sent": "The <b>abscission</b> of leaves from the trees is normal in fall.\nAn inflamed appendix calls for an immediate surgical <b>abscission</b>.", "related": "Ablation (removal of growths, etc., by surgery or other mechanical means)", "moreinfo": "“Ab” means “away.” The “scissio” root in abscission means “cut” and is the same as in scissors, excise (cut out or censor), and incision (cut into).", "hook": "sounds like \"scissors\": a cutting-off, snipping away.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "abscond", "pos": "verb", "pron": "ab-SCOND", "also": "", "d1": "Depart suddenly and secretively", "sent": "A robber <b>absconds</b> with stolen goods. People who eat in a restaurant and run out without paying—or criminals who jump bail—could also be said to be <b>absconding</b>.", "related": "Decamp (to depart from camp, or to abscond)", "moreinfo": "“Ab” means “away” and the rest of abscond comes from a Latin word meaning “to put.”", "hook": "a thief absconds: sneaks off suddenly and secretly with the loot.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "abyss", "pos": "noun", "pron": "uh-BISS", "also": "", "d1": "A deep and vast space or cavity; anything profound or infinite", "sent": "Walking a tightrope over an active volcano, the acrobat was terrified of falling into the <b>abyss</b>.\nNow recovering, the patient remembered her experience with clinical depression as an <b>abyss</b> of hopelessness.", "related": "Chasm, Crevasse, Fissure, Gorge are all words for deep openings in the earth, and can be used metaphorically (a fissure in a personal relationship, the chasm between cultures, etc.).", "moreinfo": "The 1989 classic science fiction movie The Abyss is about a diving team that encounters an underwater alien species.", "hook": "a bottomless \"a-BISS\" pit: a deep, vast void.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "accede", "pos": "verb", "pron": "ack-SEED", "also": "accedence (noun)", "d1": "Agree, give consent; assume power (usually as “accede to”)", "sent": "While the Englishman was a strong believer in democracy, he had to <b>accede</b> that watching Prince Charles someday <b>accede</b> to the throne would indeed be exciting.", "related": "Assent also means agree or give in.", "moreinfo": "When Prince Charles accedes to the throne, he will be succeeding (taking power after) Queen Elizabeth.", "hook": "ac + cede (yield): yield and agree; accede to the throne.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "accretion", "pos": "noun", "pron": "uh-CREE-shun", "also": "accrue (verb)", "d1": "Gradual increase; an added part or addition", "sent": "He was pleased by the <b>accretion</b> of money in his portfolio.\nSome charitable funds keep the principal in their accounts untouched and use only the <b>accretion</b> for philanthropic purposes.", "related": "Augment (grow larger), Agglomerate (form into a mass or cluster, join together)", "moreinfo": "Bank accounts accrue interest. Good deeds, ideally, accrue rewards.", "hook": "like \"accrue\": a gradual build-up, bit added to bit.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "acerbic", "pos": "adj", "pron": "uh-SER-bick", "also": "", "d1": "Sour; harsh or severe", "sent": "Lemons are <b>acerbic</b>. Harsh comments are also <b>acerbic</b>, like putting lemon juice on a wound.", "related": "Caustic (capable of burning or corroding; extremely critical or sarcastic), Acrid (sharp or biting, pungent), Astringent (biting, severe; a skin cleaning fluid that clears pores)", "moreinfo": "An acerbic taste is sour and an acrid taste is unpleasantly bitter, but when used metaphorically, both words mean harsh, critical.", "hook": "acid + herb: a sour, sharp, biting tone.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "acidulous", "pos": "adj", "pron": "uh-SID-joo-luss", "also": "", "d1": "Slightly acid or sour; sharp or caustic", "sent": "Grapefruit juice is <b>acidulous</b>.\nI’m skipping Thanksgiving this year just to avoid my mother’s <b>acidulous</b> comments about what she thinks I ought to be doing with my life.", "related": "Acerbic (sour, harsh or severe)", "moreinfo": "In Latin, “acidus” meant sour, so “acidulus,” a diminutive version, meant “slightly sour.”", "hook": "\"acid-ulous\": slightly acidic, sour or sharp.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "acumen", "pos": "noun", "pron": "ACK-yoo-men", "also": "", "d1": "Keen, quick, accurate insight or judgment", "sent": "His political <b>acumen</b> allowed him to bargain behind the scenes and get bills passed despite being in the minority party.", "related": "Perspicacity (acuteness of perception)", "moreinfo": "Acumen comes from a Latin word for “needle”—hence the idea of being mentally “sharp.”", "hook": "a sharp \"a-CUE-men,\" your cue for insight: keen judgment.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "adulterate", "pos": "verb", "pron": "uh-DULL-ter-ayt", "also": "", "d1": "Make impure by adding inappropriate or inferior ingredients", "sent": "Some bars <b>adulterate</b> top-shelf liquor by pouring cheaper brands into the more expensive brands’ bottles.", "related": "Taint (contaminate, corrupt), Debase (reduce in quality or dignity)", "moreinfo": "Adulterate is indeed related to adultery (cheating on one’s spouse)—both come from a Latin word meaning “to defile.”", "hook": "add + alter: add inferior stuff and corrupt it (adulterated milk).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "adumbrate", "pos": "verb", "pron": "AD-um-brayt or uh-DUM-brayt", "also": "adumbration (noun)", "d1": "Give a rough outline of; foreshadow; reveal only partially; obscure", "sent": "When I took on the lead role in the movie, I agreed not to give away the plot, but I suppose I could give a brief <b>adumbration</b> of the premise.", "related": "", "moreinfo": "Adumbrate contains the root “umbra,” Latin for “shadow.” It may seem that “give an outline of” and “obscure” are opposites, but think of it this way—to adumbrate is to give a shadowy, vague picture of something, which could mean giving more information (if starting with nothing) or obscuring information (if starting with a clear picture) in order to reach that point.", "hook": "ad + umbra (shadow): sketch a shadowy outline, foreshadow faintly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "aerie", "pos": "noun", "pron": "AIR-ee or EYE-ree", "also": "", "d1": "Dwelling or fortress built on a high place; the nest of a bird of prey, such as an eagle or hawk, built on a mountain or cliff", "sent": "The billionaire smoked a cigar out his window and watched the riots in the streets below, safe in the <b>aerie</b> of his penthouse apartment.", "related": "Stronghold (a well fortified place, especially the central place of a controversial group, as in “Police raided the smugglers’ stronghold.”)", "moreinfo": "Aerie may also be spelled aery, eyrie, or eyry. It shares an origin with “airy,” coming from a Latin word pertaining to an open field.", "hook": "an \"airy\" nest up high: an eagle's cliff perch.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "albeit", "pos": "conjunction", "pron": "al-BEE-it", "also": "", "d1": "Although, even though", "sent": "The village leader was illiterate <b>albeit</b> highly intelligent.\nThe trip was exciting, <b>albeit</b> brief.", "related": "Notwithstanding (in spite of, although, all the same—“Notwithstanding the video of his crime, he was acquitted on a technicality”)", "moreinfo": "Albeit is a shortening of “although it be.”", "hook": "\"all be it\": although, even though.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "aloof", "pos": "adj", "pron": "uh-LOOF", "also": "", "d1": "Distant physically or emotionally; reserved; indifferent", "sent": "Perceiving her parents as cold and <b>aloof</b>, the child was naturally drawn to her warm, genial aunt.", "related": "Detached (impartial or aloof), Standoffish (cold, unfriendly)", "moreinfo": "A common stereotype is that dogs are affable, while cats are aloof.", "hook": "stands \"a-loof,\" aloft and apart: distant, reserved.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "amalgamate", "pos": "verb", "pron": "uh-MAL-guh-mayt", "also": "", "d1": "Blend, merge, or unite", "sent": "The <b>Amalgamated</b> Transit Union is so called because it contains many local unions of bus operators, subway operators, baggage handlers, etc.\nWhen turning her life story into a memoir, she <b>amalgamated</b> two important relatives into a single character, even <b>amalgamating</b> their names (Mary and Rose) into the character “Aunt Mary Rose.”", "related": "Agglomerate (collect into a mass), Aggregate (gather together), Commix (mix together), Conglomerate (anything made up of different kinds of materials; blended; to bring together), Consolidate (unite or combine, such as companies or debts)", "moreinfo": "", "hook": "dental amalgam blends metals: merge and unite.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "ameliorate", "pos": "verb", "pron": "uh-MEE-lee-or-ayt", "also": "", "d1": "Improve; make better or more bearable", "sent": "If you spill water on your computer keyboard, you can <b>ameliorate</b> the damage by leaving the keyboard upside down to try—it may still be ruined, but that’s still the best chance you’ve got of saving it.", "related": "Mitigate, Palliate, and Alleviate are near-synonyms, all of which could take the place of “ameliorate” in the sentence above.", "moreinfo": "Ameliorate occasionally appears as meliorate (an Old English version), meaning exactly the same thing.", "hook": "\"a-MEAL-iorate,\" a meal makes it better: improve.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "amortize", "pos": "verb", "pron": "AM-or-tize", "also": "", "d1": "Gradually pay off a debt, or gradually write off an asset", "sent": "A mortgage is a common form of <b>amortized</b> debt—spreading the payments out over as long as 30 years is not uncommon.\nOn his company balance sheet, Joe <b>amortized</b> the value of his patent, estimating that the patent’s value as an asset would decline steadily over the course of the year as competitors patented competing products.", "related": "", "moreinfo": "Amortize contains the root “mort,” meaning death. Amortization is when a financial obligation dies a long, slow death.", "hook": "a + mort (death): slowly kill off a debt.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "anachronism", "pos": "noun", "pron": "uh-NACK-roh-nizm", "also": "anachronistic (adj)", "d1": "Something that is not in its correct historical time; a mistake in chronology, such as by assigning a person or event to the wrong time period", "sent": "The Queen of England is a bit of an <b>anachronism</b>, with her old-fashioned pillbox hats.\nDid you catch the <b>anachronisms</b> in the latest action blockbuster set in ancient Greece? One of the characters was wearing a wristwatch with his toga!", "related": "", "moreinfo": "The prefix “ana“ means “against”, and “chron” means “time.” This is one word you can work out entirely with a knowledge of roots: anachronistic means “against time.”", "hook": "ana (against) + chronos (time): out of its time (a clock in ancient Rome).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "analgesia", "pos": "noun", "pron": "an-al-JEE-zee-uh", "also": "analgesic (noun, adj)", "d1": "Pain relief; inability to feel pain", "sent": "While natural-birth advocates decline <b>analgesia</b> in childbirth, many women are very eager to take advantage of modern anesthesia.\nA disease of the spinal cord can cause <b>analgesia</b>, which can be dangerous because the patient doesn’t know when he has injured himself.", "related": "Anodyne (pain relieving medicine or anything that relieves pain)", "moreinfo": "", "hook": "an (without) + algesia (pain): no pain, pain relief (analgesic).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "annul", "pos": "verb", "pron": "uh-NULL", "also": "annulment (noun)", "d1": "Make void or null, cancel, abolish (usually of laws or other established rules)", "sent": "Can we appreciate the art of a murderer? For many, the value of these paintings is <b>annulled</b> by the artist’s crimes.", "related": "Nullify, Void (synonyms); Abort (stop part way through, remain in an undeveloped state)", "moreinfo": "Most people associate “annul” with marriage—to get an annulment rather than a divorce, most states require that the marriage have been based on fraud, or that at least one person was not mentally competent to form a contract.", "hook": "an + null: make null, cancel.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "anodyne", "pos": "noun, adj", "pron": "ANN-uh-dine", "also": "", "d1": "Medicine that relieves pain (noun); soothing, relieving pain (adj)", "sent": "While aspirin is a nice analgesic, the construction worker argued that, for sore and tired muscles, nothing beat the <b>anodyne</b> effects of a six-pack of beer.", "related": "Analgesic (pain reliever)", "moreinfo": "In antiquated slang, a hangman’s noose was once (ironically) called an “anodyne necklace.”", "hook": "\"a-no-DYNE,\" no sting, no edge: soothing, inoffensive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "antedate", "pos": "verb", "pron": "ANN-teh-dayt", "also": "", "d1": "Be older than, precede in time; assign to an earlier date", "sent": "Dinosaurs <b>antedate</b> the first human beings by about 65 million years.\nJamal didn’t get around to writing the “Best Vocabulary Words of 2010” blog post until January 3rd, 2011, but he <b>antedated</b> the post for December 31st so at least the infrequent readers wouldn’t notice.", "related": "", "moreinfo": "Postdate (antonym—“I will write this check now, but I’m postdating it for two weeks from now because I don’t have the money in my account yet.”)", "hook": "ante (before) + date: come before in time.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "antithetical", "pos": "adj", "pron": "an-tih-THET-ick-ull", "also": "antithesis (noun)", "d1": "Directly opposed, opposite; involving antithesis (the rhetorical act of placing two phrases opposite one another for contrast, as in Love me or hate me)", "sent": "Partying all night, every night, is <b>antithetical</b> to one’s academic performance.", "related": "Deleterious (harmful, unhealthful), Counterproductive (defeating the purpose; preventing the intended goal), Inimical (unfavorable, harmful)", "moreinfo": "Antithesis can be properly understood as “anti” and “thesis”—that is, being against the “thesis” (main point) of something else. The philosopher Hegel posed a method of achieving truth by which a thesis and its antithesis are resolved at a higher level of understanding, called synthesis (in normal speech, synthesis means combination into a unified entity).", "hook": "holds the antithesis: directly opposite.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 1", "setNum": 1, "coll": "Advanced"}, {"w": "apostate", "pos": "noun, adj", "pron": "uh-PAH-stayt or uh-PAH-stit", "also": "apostasy (noun)", "d1": "Person who deserts a party, cause, religion, etc.", "sent": "Many people considered “freedom fighters” by some are considered <b>apostates</b> by others; some women’s rights leaders in very conservative nations receive death threats from religious leaders who consider them <b>apostate</b>.", "related": "Recreant (coward or deserter), Perfidy (faithlessness, treachery), Heretic (believer who disagrees with religious authorities; any nonconformist thinker), Quisling (person who betrays his country by aiding an invader), Infidel (unbeliever, person who does not accept a particular faith)", "moreinfo": "Don’t confuse apostate with apostle—the words are near-antonyms.", "hook": "\"a-POST-ate\": abandons his post or faith, a deserter.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "apostle", "pos": "noun", "pron": "uh-PAH-sull", "also": "", "d1": "Pioneer of a reform movement (originally, an early follower of Jesus)", "sent": "In the 1980’s, when low-fat diets were all the rage, Dr. Rubens became an <b>apostle</b> of the Mediterranean diet, high in healthy fats, and traveled the world proselytizing to groups of physicians and nutritionists.", "related": "Champion (person who fights for a cause), Expounder (person who presents an idea in detail), Paladin (leading champion of a cause; trusted military leader)", "moreinfo": "When capitalized, “Apostles” usually refers to the original 12 disciples of Jesus. In lowercase, an “apostle” could be any major Christian missionary, or a spreader of a non-religious doctrine. Don’t confuse apostle with apostate—the words are near-antonyms.", "hook": "an apostle pioneers a cause, an early champion of it.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "apposite", "pos": "adj", "pron": "APP-uh-zit or uh-PAH-zit", "also": "", "d1": "Highly appropriate, suitable, or relevant", "sent": "He searched his brain for an <b>apposite</b> word to describe wealthy Americans’ addiction to consumer goods, until he discovered the neologism “affluenza.”", "related": "Apt (appropriate, likely, disposed or prone, as in “Those who are apt to steal will receive an apt punishment”), Condign (appropriate, esp. as a punishment fits a crime)", "moreinfo": "", "hook": "think \"apt\": highly fitting and relevant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "apprise", "pos": "verb", "pron": "uh-PRIZE", "also": "", "d1": "Inform, give notice to", "sent": "I can’t believe you failed to <b>apprise</b> me that my child was biting the other children in his preschool class! If I had known, I could’ve addressed this issue before all the other parents threatened to sue!", "related": "", "moreinfo": "If you know Spanish or French, this word might remind you of the verb aprender or apprendre for good reason—both mean “to learn.” Don’t confuse apprise with appraise, which means “to evaluate or assess the value of,” as in “to have jewelry appraised before selling it at auction.”", "hook": "\"ap-PRISE\": prize you with the news, inform you.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "approbation", "pos": "noun", "pron": "app-roh-BAY-shun", "also": "", "d1": "Praise or approval, especially formal approval", "sent": "In her speech for class president, she won the <b>approbation</b> of her peers by promising not only to save the prom, but to raise enough money to make it free for everyone.", "related": "Imprimatur (approval, a mark of approval, or especially a formal body’s approval to publish a work) Memory Trick: Approbation begins with the same five letters as its near-synonym approval.", "moreinfo": "", "hook": "\"approve-ation\": formal approval and praise.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "appropriate", "pos": "verb", "pron": "uh-PROH-pree-ayt", "also": "", "d1": "Set aside or authorize (such as money) for a particular purpose; take for one’s own use", "sent": "The School Board <b>appropriated</b> money for new textbooks.\nIn putting together the perfect outfit for “Career Day” at her high school, Mackenzie <b>appropriated</b> her mother’s stethoscope and her little brother’s stuffed pig, making it clear to everyone that she wanted to be a veterinarian.", "related": "Arrogate (claim or take presumptuously or without right)", "moreinfo": "The last syllable of the more common adjective “appropriate” is pronounced “it”; the last syllable of the verb appropriate is pronounced “ate.”", "hook": "\"a-PROPRI-ate\": take for your own, or set funds aside for a purpose.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "arbiter", "pos": "noun", "pron": "AR-bit-er", "also": "arbitrate (verb)", "d1": "Judge, umpire, person empowered to decide matters at hand", "sent": "Professional mediators arbitrate disputes.\nThe principal said, “As the final <b>arbiter</b> of what is and is not appropriate in the classroom, I demand that you take down that poster of the rapper Ice-T and his scantily-clad wife Coco.”", "related": "Adjudicator (judge or arbitrator, esp. a judge of a competition)", "moreinfo": "An arbitrator is officially appointed to settle a dispute; an arbiter is more someone whose opinion is valued, as in the expression “arbiter of good taste.”", "hook": "an arbiter arbitrates: the judge who decides.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "ardent", "pos": "adj", "pron": "AR-dent", "also": "ardor (noun)", "d1": "Very passionate, devoted, or enthusiastic", "sent": "He was an <b>ardent</b> heavy metal lover and became offended anytime someone referred to Poison as a “hair band.”\nThey were so in love that not even meeting each other’s awful relatives could dampen their ardor.", "related": "Fervent, Fervid, and Perfervid all mean “passionate, fiery, deeply enthusiastic” and come from a common root relating to heat.", "moreinfo": "Don’t confuse ardor with arduous, which means very difficult. Ardor comes from a Latin word meaning “to burn”, which we can think of here in the sense of “burning with passion.”", "hook": "burning with ardor: passionate and devoted.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "arrogate", "pos": "verb", "pron": "AIR-oh-gayt", "also": "", "d1": "Claim or take presumptuously or without the right to do so", "sent": "In order to build the oil pipeline, the government <b>arrogated</b> the land of many small farmers who are still fighting for compensation.\nThe bride’s mother <b>arrogated</b> the right to decide on the venue, the food, and even the wedding dress!", "related": "The verb Appropriate has two meanings: set aside or authorize for a particular purpose; take for one’s own use. The second meaning is a synonym for arrogate. Memory Trick: To arrogate is to arrogantly take what doesn’t belong to you.", "moreinfo": "", "hook": "arrogant + ate: arrogantly claim what is not yours.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "ascribe", "pos": "verb", "pron": "uh-SCRIBE", "also": "", "d1": "Assign or credit to a certain cause or source", "sent": "He <b>ascribed</b> his good grades to diligent studying.\nThe young boy <b>ascribed</b> to his imaginary friend all the powers he wished he had himself—being able to fly, having dozens of friends, and never having to eat his broccoli.", "related": "Impute (attribute or ascribe)", "moreinfo": "Ascribe contains the root “scribe,” meaning “write.”", "hook": "a + scribe (write): write it down to a cause, attribute it.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "aseptic", "pos": "adj", "pron": "uh-SEP-tick or ay-SEP-tick", "also": "septic (adj), sepsis (noun)", "d1": "Free from germs; lacking vitality, warmth, or emotion", "sent": "It is very important to perform surgery in an <b>aseptic</b> environment, lest a patient contract sepsis (a systemic infection) and die.\nNot only did Marlene dump Tom via email, but the email was so <b>aseptic</b> she might as well have been sending an interoffice memo. “That was ice cold,” said Tom.", "related": "", "moreinfo": "A septic tank is a place under a house where sewage is stored. Since putting “a-“ before a word means “without,” it makes sense that, if septic means “infected or putrefying,” then aseptic would be the opposite.", "hook": "a (without) + septic (germs): germ-free; also cold and feelingless.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "asperity", "pos": "noun", "pron": "uh-SPARE-ih-tee", "also": "", "d1": "Rigor, severity; harshness or sharpness of tone; roughness of surface", "sent": "Used to a more lax school environment, the freshman at military school was shocked by the <b>asperity</b> of punishments meted out for even the most minor offenses, as well as the <b>asperity</b> with which his drill sergeant bossed him around.\nThe <b>asperity</b> of her cheap, scratchy sweater made her wish she could afford cashmere.", "related": "", "moreinfo": "Asperity describes a wide variety of unpleasant things: hardship, people speaking to us in an unnecessarily harsh way, or physical roughness.", "hook": "rough as asphalt: harshness and severity.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "aspersions", "pos": "noun", "pron": "uh-SPER-zhunz", "also": "asperse (verb)", "d1": "Damaging remarks, defamation, slander", "sent": "He could no longer work with his duplicitous business partner, who acted friendly to his face but then spewed <b>aspersions</b> about him behind his back.\nIf you asperse me one more time, I will sue you for libel!", "related": "Slander, Traduce, and Defame all mean “to speak maliciously and falsely of”", "moreinfo": "Aspersions is often used in the phrase “to cast aspersions,” which has the sense of throwing or tossing insults or malicious lies about someone. One additional (rare) meaning of aspersion is “to sprinkle, such as for baptism.” So, it’s not a long leap to imagine spattering or sprinkling someone with insults.", "hook": "\"cast aspersions\": sprinkle slander on someone.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "assail", "pos": "verb", "pron": "uh-SAIL", "also": "assailant (noun)", "d1": "Attack violently, assault", "sent": "One strategy for winning in boxing is to simply <b>assail</b> your opponent with so many blows that he becomes disoriented.\nThe debate team <b>assailed</b> the opposition with more evidence than they could respond to.", "related": "Batter (beat persistently or hard)", "moreinfo": "Assail simply means attack, so it can be used metaphorically the same way you would use attack, such as in “assailing one’s homework with great energy.”", "hook": "assail = assault: attack violently.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "assiduous", "pos": "adj", "pron": "uh-SID-joo-uss", "also": "", "d1": "Persevering, diligent, constant", "sent": "Through <b>assiduous</b> effort over a substantial period of time, anyone can develop a prodigious vocabulary.", "related": "Sedulous, Tenacious", "moreinfo": "Assiduous contains a variant of the root “sed,” meaning “to sit” (as in sedated or sediment). Think of assiduous as “sitting” in your chair until you finish your work.", "hook": "\"a-SID-uous,\" sits and does it: diligent and persevering.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "attenuate", "pos": "verb", "pron": "uh-TEN-yoo-ayt", "also": "", "d1": "Weaken or thin out", "sent": "When you pull a piece of bubblegum so it becomes long and thin, you are <b>attenuating</b> it.\nSadly, the day care center was so understaffed that the carers’ efforts were <b>attenuated</b>, and many of the children barely received any attention at all.", "related": "", "moreinfo": "When you attenuate something, it becomes tenuous, which means thin or weak (a tenuous argument).", "hook": "a + tenuous (thin): make thin, weaken.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "attuned", "pos": "adj", "pron": "uh-TOON’d", "also": "", "d1": "In harmony; in sympathetic relationship", "sent": "Research shows that new mothers are keenly <b>attuned</b> to their babies’ cries; even those who were formerly heavy sleepers often find that they now wake up immediately when their babies need attention.\nIn the sixth week of Melanie’s foreign study program, she finally <b>attuned</b> herself to life on a French farm.", "related": "", "moreinfo": "Attuned is almost always followed by “to.”", "hook": "\"a-TUNED\": in tune and harmony with.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "augury", "pos": "noun", "pron": "AWG-yer-ee", "also": "augur (noun)", "d1": "Telling the future, such as through supernatural means", "sent": "Value investors such as Warren Buffet (who attempt to buy shares in undervalued companies by analyzing the businesses themselves) consider others’ attempts to “time the market” as mere <b>augury</b>, equivalent to trying to predict rain by reading tea leaves.", "related": "Prognosticate and Presage also mean to tell the future.", "moreinfo": "An augur or auspex in ancient Rome interpreted omens (sometimes by reading bird entrails) to help guide the making of public decisions.", "hook": "an augur reads the omens: a foretelling of the future.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "august", "pos": "adj", "pron": "AW-gust", "also": "", "d1": "Venerable, majestic; inspiring admiration", "sent": "“I welcome you to this <b>august</b> institution, where Presidents and Nobel Prize winners have received the fruits of erudition,” said the university president (rather bombastically) to the new crop of first-year students.", "related": "Eminent (prominent, distinguished, of high rank), Venerable (worthy of deep respect, hallowed, dignified), Olympian (majestic, superior, lofty)", "moreinfo": "Emperor Octavian, or Gaius Julius Caesar Octavianus (an heir to Julius Caesar) was given the name Caesar Augustus upon taking the throne in 27 B.C.", "hook": "majestic as a Roman Augustus: venerable and grand.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "avarice", "pos": "noun", "pron": "AV-er-iss", "also": "", "d1": "Insatiable greed; a miserly desire to hoard wealth", "sent": "It is hard to fathom the sheer <b>avarice</b> of a company that would fraudulently overcharge a struggling school system for new computers.", "related": "Cupidity (avarice or other excessive desire), Covetousness (greed), Rapacity or Rapaciousness (greedy or grasping; living on prey)", "moreinfo": "", "hook": "\"a vast vice\" of hoarding: insatiable greed.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "axiom", "pos": "noun", "pron": "ACK-see-um", "also": "axiomatic (adj)", "d1": "Self-evident truth requiring no proof; universally or generally accepted principle", "sent": "Given the last decade of research into the brain—as well as our own experience trying to function while deprived of sleep or food—we must take as <b>axiomatic</b> that the brain is influenced by the body.", "related": "Maxim (short statement of general truth, proverb), Postulate (self-evident proposition, such as in math)", "moreinfo": "When we say something is axiomatic, we mean that it must be true, in the way that 2+2 must equal 4, or all squares must have four sides.", "hook": "a math axiom needs no proof: a self-evident truth.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "balloon", "pos": "verb", "pron": "buh-LOON", "also": "", "d1": "Swell or puff out; increase rapidly", "sent": "During the dot-com bubble, the university’s investments <b>ballooned</b> to three times their former value.", "related": "Distend (swell, expand), Turgid or Tumid (swollen, inflated; or, metaphorically “inflated,” such as in overblown, pompous speech)", "moreinfo": "In finance, a balloon payment is a single payment at the end of a loan or mortgage term that is much larger than the other payments.", "hook": "a balloon swells fast: increase rapidly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "banal", "pos": "adj", "pron": "buh-NAL", "also": "", "d1": "Lacking freshness and originality; cliché", "sent": "The drama professor despaired at reading another <b>banal</b> play from his uninspired students. “Oh look,” he said sarcastically, “yet another young person has decided to write a play about a young person breaking free of society’s constraints. Can you see me yawning?”", "related": "Hackneyed, Inane, Insipid and Trite all mean “lacking freshness and originality, shallow”", "moreinfo": "Banal comes from the Old French “ban,” a word for compulsory feudal service—that is, something common to everyone. It’s not hard to see how the meaning of “common” could change to “old, stale, and boring” over time.", "hook": "\"ba-NAL,\" bland: dull and unoriginal.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "bane", "pos": "noun", "pron": "BAYN", "also": "baneful (adj)", "d1": "Something that ruins or spoils", "sent": "Mosquitoes are the <b>bane</b> of my existence! They just love me, and by “love” I mean ruin my summer!\nThe closure of the hospital could not have been more <b>baneful</b> to the already strained community.", "related": "The opposite of bane is boon, a benefit or blessing. The words are often used together to ask a question, as in “The new regulations: bane or boon?”", "moreinfo": "Bane can also mean poison, usually as part of more specific names, like wolfsbane or fleabane. Don’t confuse baneful (destructive, ruinous) with baleful, which means threatening.", "hook": "the villain Bane ruins him: a cause of ruin.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "baying", "pos": "adj", "pron": "BAY-ing", "also": "bay (verb)", "d1": "Howling in a deep way, like a dog or wolf", "sent": "The lonely dog bayed all night.\nThe mob bayed for the so-called traitors to be put to death.", "related": "", "moreinfo": "Bay comes from an Old French word meant to actually sound like the baying of an animal. In a related expression, when a person is “at bay” or “brought to bay,” that means that the person is in a captured position, powerless and unable to flee.", "hook": "hounds baying at the moon: deep, drawn-out howling.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 2", "setNum": 2, "coll": "Advanced"}, {"w": "beneficent", "pos": "adj", "pron": "ben-EFF-iss-ent", "also": "", "d1": "Doing good", "sent": "The billionaire had been a mean and stingy fellow, but after his death, his <b>beneficent</b> widow gave all his money to charity, even accompanying the donations with handwritten notes thanking the charities for all the good work they did.", "related": "Benevolent (expressing goodwill, helping others or charity), Eleemosynary (charitable)", "moreinfo": "The Latin root “bene” means “good,” and “fic” means “making or producing.” The antonym of beneficent is maleficent (“mal” means “bad”).", "hook": "bene (good) + ficent (doing): doing good.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bent", "pos": "noun", "pron": "BENT", "also": "", "d1": "Personal inclination or tendency", "sent": "He had a pedantic <b>bent</b>—he was just naturally inclined to correct people’s grammar and otherwise act like an imperious schoolmaster.\nEven a vow of silence couldn’t dampen the nun’s garrulous <b>bent</b>—even her prayers were verbose!", "related": "Predilection (preference or inclination), Propensity (natural tendency or inclination)", "moreinfo": "In the expression “to the top of one’s bent,” the word bent has the meaning of “the limits of one’s endurance,” as in “Although he didn’t win, he ran the marathon to the top of his bent.”", "hook": "your \"bent\" is the way you lean: an inclination.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "besiege", "pos": "verb", "pron": "buh-SEED’j", "also": "", "d1": "Attack, overwhelm, crowd in on or surround", "sent": "The regiment was <b>besieged</b> by attackers on all sides and finally surrendered.\nI cannot go out this weekend—I am <b>besieged</b> by homework!", "related": "Harry (harass or annoy), Hound (harass or pursue relentlessly, as if with hunting dogs), Beleaguer (surround, as with difficulties or attackers)", "moreinfo": "Besiege is equivalent to the expression “lay siege to” (although that expression is used more in the military sense and less in the metaphorical sense).", "hook": "be + siege: surround and overwhelm.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bevy", "pos": "noun", "pron": "BEV-ee", "also": "", "d1": "Group of birds or other animals that stay close together; any large group", "sent": "The bar owner cringed when a <b>bevy</b> of women in plastic tiaras came in—“Another drunken bachelorette party,” he sighed.", "related": "Covey (a group of birds, or any group), Brood (group of offspring born or hatched at the same time, esp. birds)", "moreinfo": "Bevy is most commonly associated with birds, and often used to describe groups of people who stick together like a flock of birds—it usually implies a not-very-serious opinion about the group in question.", "hook": "\"a bevy of beauties\": a large, close group.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bifurcate", "pos": "verb, adj", "pron": "BYE-fur-cayt", "also": "", "d1": "To fork into two branches or divide into two halves", "sent": "The medical student carefully <b>bifurcated</b> the cadaver brain, separating it precisely into right and left hemispheres.\nThe <b>bifurcate</b> tree stood tall, its two massive branches reaching for the sky.", "related": "Cleave (split or cut, as in a “meat cleaver”)", "moreinfo": "In math, a midpoint bifurcates a line segment. Bifurcate comes from the Latin “furca,” which also gives us “fork.”", "hook": "bi (two) + furca (fork): split into two forks.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bilk", "pos": "verb", "pron": "BILK", "also": "", "d1": "Cheat or defraud", "sent": "The con artist <b>bilked</b> many elderly people out of their savings, promising to cure illnesses from diabetes to cancer with only 36 monthly payments of $99.99—for which the victims received nothing but useless placebo pills.", "related": "Hoodwink, Swindle, Con, and Fleece are all verbs for cheating others. Fleece is perhaps more severe, having the connotation of taking everything from the victim, the way one sheers all of the fleece from a sheep.", "moreinfo": "Bilk can also be a noun for the person who cheats others (“I hope that bilk goes to jail!”) More obscurely, bilk can mean to escape from, frustrate, or thwart. The word comes from the card game cribbage, where it means to play a card that keeps an opponent from scoring.", "hook": "\"bilk = milk them dry\": cheat and defraud.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "blight", "pos": "noun, verb", "pron": "BLITE", "also": "", "d1": "Disease that kills plants rapidly, or any cause of decay or destruction (noun); ruin or cause to wither (verb)", "sent": "Many potato farmers have fallen into poverty as a result of <b>blight</b> killing their crops.\nGang violence is a <b>blight</b> on our school system, causing innocent students to fear even attending classes.\nViolence has <b>blighted</b> our town.", "related": "Scourge (punishment, disease, or disaster; a whip or lash), Bane (something that spoils or ruins, as in “Allergies are the bane of my life.”)", "moreinfo": "Blight is often used to describe unidentified plant diseases that mysteriously cause all the plants to wither—as such, it makes a good metaphor, as in “urban blight,” when everything decays and goes wrong at once.", "hook": "potato blight: a disease or ruin that withers everything.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "blithe", "pos": "adj", "pron": "BLITHE", "also": "", "d1": "Joyous, merry; excessively carefree (so as to ignore more important concerns)", "sent": "Delighted about making the cheerleading team, she <b>blithely</b> skipped across the street without looking, and just narrowly avoided being hit by a bus.", "related": "Jovial (joyous, merry)", "moreinfo": "Blithe can be positive or negative—it’s nice to be merry, but not so merry that we thoughtlessly trample over other people, disobey the rules, etc.", "hook": "a \"blithe spirit\": carefree and merry, sometimes heedlessly so.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bombastic", "pos": "adj", "pron": "bom-BAST-ick", "also": "bombast (noun)", "d1": "(Of speech or writing) far too showy or dramatic than is appropriate; pretentious", "sent": "Professor Knutsen’s friends joked that he became quite <b>bombastic</b> after a few drinks, once asking a woman in a bar, “Is your daddy an aesthete? Because you are the epitome of ineffable pulchritude.” She replied, “I’m not impressed by your bombast.”", "related": "Declamatory (pompous, merely oratorical), Magniloquent and Grandiloquent (speaking in a lofty, grandiose style)", "moreinfo": "The origin of bombastic is related to the idea of being inflated, a metaphor that also comes into play with the related words turgid and tumid, synonyms that can mean literally inflated like a balloon, or using language much too fancy for the sentiment or occasion.", "hook": "full of bombast, like a bomb going off: pompous and overblown.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bonhomie", "pos": "noun", "pron": "bah-num-EE or BAH-num-ee", "also": "", "d1": "Friendliness, open and simple good heartedness", "sent": "By the end of the summer, the campers were overflowing with <b>bonhomie</b>, vowing to remain Facebook friends forever.", "related": "Amity (friendship, peaceful agreement)", "moreinfo": "Bonhomie is from French—bon homme means “good man.” In English, bonhomie is pronounced “bon-uh-MEE” or “BON-uh-mee” (somewhat ironically, there is no “homey” in bonhomie).", "hook": "French \"bon homme,\" good fellow: warm friendliness.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "brandish", "pos": "verb", "pron": "BRAN-dish", "also": "", "d1": "Shake, wave, or flourish, as a weapon", "sent": "The Renaissance Fair ended badly, with one drunken fellow <b>brandishing</b> a sword and refusing to leave the ladies’ dressing tent.", "related": "", "moreinfo": "Brandish comes from the Germanic “brand,” or sword.", "hook": "brand (sword) + ish: wave a weapon about.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "brook", "pos": "verb", "pron": "BROOK (rhymes with look)", "also": "", "d1": "Suffer or tolerate", "sent": "“You will do your homework every night before you go anywhere, you will do your chores, and you will be home by 9 p.m. I will <b>brook</b> no disobeying of these rules, young man!”", "related": "Condone (overlook or tacitly approve), Countenance (as a noun: face or facial expression; as a verb: approve or tolerate)", "moreinfo": "Of course, a brook is also a small, freshwater stream. The two “brooks” come from different origins entirely; brook as a verb comes from a Latin root meaning “enjoy.”", "hook": "\"brook no nonsense\": tolerate (usually in the negative).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "bucolic", "pos": "adj", "pron": "byoo-CALL-ick", "also": "", "d1": "Pertaining to shepherds; suggesting a peaceful and pleasant view of rural life", "sent": "The play was set in a <b>bucolic</b> wonderland—while getting some shepherd’s robes for the lead actor was no problem, the stagehands had a hard time bringing in a flock of sheep.", "related": "Pastoral, Idyllic, Georgic, and Arcadian are all words relating to a positive view of rural life and songs or poems on that theme", "moreinfo": "Bucolic comes from a Greek word for “ox.”", "hook": "a peaceful pasture scene: idyllic rural life.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "burnish", "pos": "verb", "pron": "BUR-nish", "also": "", "d1": "Polish, make smooth and lustrous", "sent": "Mr. Hoffenstotter replaced all of the rustic wood doorknobs with newer models made of <b>burnished</b> steel. “So shiny,” said his delighted wife.", "related": "Gilded means covered with a thin layer of gold (and thus looking like solid gold, but actually only superficially so) and is used as a metaphor for things that look better than they really are.", "moreinfo": "Burnish can also be used as a noun, meaning “luster or shine,” as in “the beautiful burnish of her hair” or “the burnish of an Ivy League university.”", "hook": "\"burn + polish\": rub to a shine.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "calumny", "pos": "noun", "pron": "CAL-um-nee", "also": "calumnious (adj)", "d1": "Malicious lie intended to hurt someone’s reputation; the act of telling such lies", "sent": "I’ve had enough of your calumnious accusations! Admit that you made up all those wicked things about me, or I will see you in court when I sue you for slander!", "related": "Slander is a synonym. Libel is the written version of slander. Traduce, Vilify, and Defame are verbs meaning “to slander, to damage a person’s reputation with lies.”", "moreinfo": "", "hook": "\"call-you-many\" lies: malicious slander.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "canard", "pos": "noun", "pron": "cuh-NARD", "also": "", "d1": "Rumor, a false or baseless story", "sent": "The idea that we only use 10% of our brains is a tired, old <b>canard</b>; actually, even the dumbest people use all of their brains.", "related": "", "moreinfo": "Canard is simply the French word for “duck.” The use of “duck” to mean, essentially, “urban legend” may come from an old French expression “to half-sell a duck.” Sounds pretty sketchy! Just like a canard.", "hook": "French for a duck, a quacking rumor: a false story.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "cardinal", "pos": "adj", "pron": "CAR-din-ull", "also": "", "d1": "Chief, most important", "sent": "The <b>cardinal</b> rule of Fight Club is that you don’t talk about Fight Club.", "related": "Principal (first, highest in rank)", "moreinfo": "Cardinal can also mean an official in the Catholic church, a bright red bird, or a deep red color. Cardinal comes from a Latin word for “hinge”—as in, a thing which other things “hinge” or depend on.", "hook": "the cardinal rule, a cardinal number: chief, most important.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "catholic", "pos": "adj", "pron": "CATH-ull-ick", "also": "", "d1": "Universal, broad-minded", "sent": "Some precursors to the Constitution (such as documents governing the colonies) enumerated the rights of male property holders only. The U.S. Constitution took a more <b>catholic</b> approach, declaring that “All men are created equal.” Today, policy writers would probably take <b>catholicism</b> a step further and write “All people.”", "related": "Liberal (aside from the use of Liberal in American politics, Liberal means “favorable to reform; favorable to maximum possible individual freedom; free from prejudice, tolerant, open-minded”)", "moreinfo": "The Catholic Church, of course, goes by that name because it intends (as do many religions) to be universal.", "hook": "\"catholic tastes\": universal and broad-minded.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "chicanery", "pos": "noun", "pron": "shick-AYN-er-ee", "also": "", "d1": "Trickery, deception by knowingly false arguments", "sent": "The defense lawyer’s strategy for getting her client acquitted by knowingly misinterpreting words in an obscure precedent was nothing but <b>chicanery</b>.\nNice try, passing off last week’s homework as this week’s by changing the date at the top. I’ve had enough of your <b>chicanery</b>, young man!", "related": "Quibbling (the use of ambiguous, petty, or irrelevant arguments, especially to evade the real issue), Sophistry (deliberately tricky argumentation)", "moreinfo": "Chicanery is from French, hence the pronunciation: shi-KAY-nuh-ry.", "hook": "\"chic trickery\": clever deception.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "circumscribe", "pos": "verb", "pron": "SER-cuhm-scribe", "also": "", "d1": "Strictly limit a role, range of activity, or area; in math, to be constructed around so as to touch as many points as possible", "sent": "Suki’s parents <b>circumscribed</b> her after-school activities; she was permitted only to study and to join organizations directly related to academic subjects.\nA square <b>circumscribed</b> in a circle has all four of its vertices on the circle’s circumference.\nOur land is <b>circumscribed</b> by hedges and fences.", "related": "", "moreinfo": "“Circum” is the Latin root for “around,” and “scribe” for “write.” The “scribe/script” root also occurs in proscribe (prohibit) and conscript (draft into military service).", "hook": "circum (around) + scribe (draw): draw a limiting circle around.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "circumspect", "pos": "adj", "pron": "SER-cuhm-spect", "also": "", "d1": "Cautious, prudent; careful to consider the circumstances and consequences", "sent": "Luann immediately forked over an initiation fee to become a vitamin distributor, but her more <b>circumspect</b> brother had a list of at least twenty questions he wanted answered before he would consider joining.", "related": "Staid (restrained, prim, settled)", "moreinfo": "The root “circum” means “around” and “spect” means “see”—thus, circumspect people “look around” before acting, much as in the idiom “look before you leap.”", "hook": "circum (around) + spect (look): look all around first, cautious.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "clamber", "pos": "verb", "pron": "CLAM-ber", "also": "", "d1": "Climb awkwardly or with difficulty, scramble", "sent": "The hiker had spent the last hour plodding lethargically up the side of the mountain, but when she caught sight of the summit, she excitedly began to <b>clamber</b> up even the steepest inclines.", "related": "", "moreinfo": "Clamber comes from the same root as climb. Don’t confuse it with clamor, which means “noisy shouting or protest.”", "hook": "climb + scramble: climb awkwardly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "cloying", "pos": "adj", "pron": "CLOY-ing", "also": "", "d1": "Disgustingly or distastefully sweet", "sent": "I do like visiting our grandmother, but I can’t stand those <b>cloying</b> movies she watches—last time it was some heart-tugging story where an orphan saves a suffering pony.\nI do like cake, but I find that honey-covered angel food cake positively <b>cloying</b>.", "related": "Treacly and Saccharine are synonyms. Maudlin means “overly tearful and sentimental,” and might also possibly describe the orphan/pony movie described above.", "moreinfo": "", "hook": "too much icing: sickeningly sweet.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "coagulate", "pos": "verb", "pron": "coh-AGG-yoo-layt", "also": "", "d1": "Cause a liquid to become solid or semisolid", "sent": "Hemophilia is a medical condition in which the blood doesn’t <b>coagulate</b>, meaning that a hemophiliac can easily bleed to death from a small wound.\nWhen making jam, use pectin to get the fruit to <b>coagulate</b>.", "related": "Curdle also means “go from liquid to solid” but tends to be used to describe milk spoiling, or metaphorically, as in “Her scream made my blood curdle.” Clot has the same definition as well, and often describes blood (a blood clot in an artery can cause a heart attack). Some desserts involve clotted cream.", "moreinfo": "", "hook": "blood coagulates: clots into a solid.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "coda", "pos": "noun", "pron": "COH-duh", "also": "", "d1": "Final part of a musical composition; an ending, esp. one that sums up what has come before", "sent": "“You play this middle section twice, then move to the <b>coda</b>,” the music teacher explained to the child. “The <b>coda</b> always comes last.”\nDropping my purse in a mud puddle right outside my own front door was a fine <b>coda</b> to a horrible evening.", "related": "Recapitulation (summary or the act of summing up), Précis (summary or abstract)", "moreinfo": "Coda comes from the Latin “cauda,” meaning “tail.” (A caudate animal has a tail and an acaudate animal lacks one.)", "hook": "a musical coda caps the song: the ending.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 3", "setNum": 3, "coll": "Advanced"}, {"w": "coffer", "pos": "noun", "pron": "COFF-er", "also": "", "d1": "Chest for storing valuables; financial resources, a treasury", "sent": "The dishonest employee called it “dipping into the company <b>coffers</b>,” but the arresting officer called it “embezzlement.”\nRather than rent a safety-deposit box, I keep my priceless antique coins in a <b>coffer</b> here at home.", "related": "A strongbox is also a chest for storing valuables.", "moreinfo": "Coffer comes from the same root as “coffin,” another type of box. When used metaphorically, coffers is generally used in the plural.", "hook": "a coffer of coins: a treasury, funds.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "collude", "pos": "verb", "pron": "cuh-LOOD", "also": "collusion (noun)", "d1": "Conspire; cooperate for illegal or fraudulent purposes", "sent": "After two competing software companies doubled their prices on the same day, leaving consumers no lower-priced alternative, the federal government investigated the companies for collusion.", "related": "Cabal (a conspiratorial group)", "moreinfo": "", "hook": "co + collude: conspire together secretly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "compendium", "pos": "noun", "pron": "cuhm-PEN-dee-um", "also": "compendious (adj)", "d1": "Concise but complete summary; a list or collection", "sent": "I could hardly bring my whole collection of poetry books on vacation, so instead, I brought a lightweight poetry <b>compendium</b> containing a few selections each from thirty or so poets thought to represent various styles and eras.\nThis movie review is unusually compendious—although a scant 500 words, it tells every single thing that happens in the entire film.", "related": "Digest (a periodical containing shortened versions of works published elsewhere), Recapitulation (summary or the act of summing up), Précis (summary or abstract)", "moreinfo": "", "hook": "a compendium compresses it all: a concise complete summary.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "complaisant", "pos": "adj", "pron": "cuhm-PLAY-sent", "also": "", "d1": "Eager to please; cheerfully complying", "sent": "Coming from a more uptight corporate background, Chris found the soup kitchen volunteers remarkably <b>complaisant</b>—when he asked the greeters to sweep the floor and the cooks to wash dishes, everyone happily moved to their new positions.", "related": "", "moreinfo": "Don’t confuse complaisant with complacent, which means “smug, self-satisfied.”", "hook": "eager to please (plaisir): cheerfully compliant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "confound", "pos": "verb", "pron": "cuhn-FOUND", "also": "", "d1": "Confuse, frustrate; mix up or make worse", "sent": "He was positively <b>confounded</b> by a map that seemed to show “East Bethlehem” as being to the west of “West Bethlehem.”\nHe was already a little flummoxed in regards to differential equations, but reading an incorrectly-edited Wikipedia page on the topic only <b>confounded</b> the problem.", "related": "Baffled, Flummoxed, and Nonplussed are all words for “confused.”", "moreinfo": "", "hook": "con + found: confuse and mix up.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "connote", "pos": "verb", "pron": "cuh-NOTE", "also": "connotation (adj)", "d1": "Suggest or imply in addition to the precise, literal meaning", "sent": "The word “titanic” simply means large or majestic, but because of the word’s association with the sunken ship, “titanic” has a negative <b>connotation</b> to many people.", "related": "Evoke (call forth, esp. of feelings or imagination)", "moreinfo": "A denotation is the literal meaning of a word; a connotation is the feeling that accompanies that word.", "hook": "con + note: imply beyond the literal meaning.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "contraries", "pos": "noun", "pron": "CAHN-trare-eez", "also": "", "d1": "Things that are opposing; either of two opposite things", "sent": "The Machiavellian among us would say that ethics and expedience are <b>contraries</b>—at some point, one must win out over the other.", "related": "Counterpoint (a contrasting element)", "moreinfo": "The expression to the contrary means “to the opposite effect of the thing we were just talking about, as in “Although you say the plan will please everyone, to the contrary, our biggest client has already informed us that they will find a new supplier if we proceed.”", "hook": "contrary things: opposites.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "contrite", "pos": "adj", "pron": "cuhn-TRITE", "also": "", "d1": "Remorseful; feeling sorry for one’s offenses or sins", "sent": "He would have punished his son more severely for breaking his car’s windshield in a “rock throwing contest,” but the boy seemed truly <b>contrite</b>.", "related": "Penitent is a synonym. Atone means “to make amends for.”", "moreinfo": "Interestingly, contrite comes from a Latin root meaning “to grind.” Perhaps hating to admit we’re wrong is truly universal.", "hook": "deeply \"con-TRITE\": remorseful and sorry.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "contumacious", "pos": "adj", "pron": "cahn-tuh-MAY-shuss", "also": "", "d1": "Rebellious; stubbornly disobedient", "sent": "The psychologist’s book “Dealing With Your <b>Contumacious</b> Teenager” would have sold many more copies to parents of rude and rebellious youth if only people knew what “<b>contumacious</b>” meant.", "related": "Obstreperous, Recalcitrant, and Refractory are synonyms", "moreinfo": "Contumacious and contumely are not as closely related as they sound: contumely means “contemptuous treatment or a humiliating insult.”", "hook": "full of contempt: rebelliously disobedient.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "convoke", "pos": "verb", "pron": "cuhn-VOHK", "also": "", "d1": "Call together, as to a meeting", "sent": "The dean has <b>convoked</b> this gathering to discuss the Honor Code.", "related": "Convene is a synonym", "moreinfo": "The root “voc/vok” in convoke means “to call” and also appears in words such as vocal, invoke, and vocation.", "hook": "con (together) + voke (call): call a meeting together.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "cosset", "pos": "verb", "pron": "CAH-set", "also": "", "d1": "Treat as a pet, pamper", "sent": "The <b>cosseted</b> toddler was lovingly wrapped up in his snow gear, so much so that he could barely even move his arms enough to make his first snowball.", "related": "Coddle (treat tenderly or indulgently)", "moreinfo": "As a noun, a cosset is a pet lamb or any pet. The root in cosset actually comes from a word meaning “to kiss.”", "hook": "coddle like a pet: pamper.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "coterie", "pos": "noun", "pron": "COH-ter-ee", "also": "", "d1": "Close or exclusive group, clique", "sent": "The pop star never traveled anywhere without a <b>coterie</b> of assistants and managers.", "related": "Cabal (conspiracy, group of people who plot), Entourage (group of attendants)", "moreinfo": "In French, a coterie was a group of tenant farmers.", "hook": "a cozy clique: an exclusive little group.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "cupidity", "pos": "noun", "pron": "kyoo-PID-it-ee", "also": "", "d1": "Greed, great or excessive desire", "sent": "The doctor’s medical license was revoked after it was discovered that, out of sheer <b>cupidity</b>, he had diagnosed people with illnesses they didn’t have and pocketed insurance money for performing procedures they didn’t need.", "related": "Avarice (insatiable greed), Covetousness (greed), Rapacity or Rapaciousness (greedy or grasping; living on prey)", "moreinfo": "", "hook": "Cupid's arrow, but aimed at money: greed.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "curmudgeon", "pos": "noun", "pron": "cur-MUD-jun", "also": "", "d1": "Bad-tempered, difficult person; grouch", "sent": "The college students’ party was hampered by constant complaints from a <b>curmudgeonly</b> neighbor who insisted that making noise after 8pm was unreasonable, and called the police over a single beer can on his lawn.", "related": "Crotchety (grouchy, picky, given to odd notions), Cantankerous (disagreeable, contentious), Crank (an unbalanced person who is fanatical about a private, generally petty cause)", "moreinfo": "Curmudgeon, like crotchety, is almost always used to describe old men (a fact that is perhaps unfair to old men).", "hook": "a grumpy old curmudgeon: a bad-tempered grouch.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "declaim", "pos": "verb", "pron": "dih-CLAIM", "also": "", "d1": "Speak in an impassioned, pompous, or oratorical manner; give a formal speech", "sent": "After a drink or two, Gabe will <b>declaim</b> all night about campaign finance reform—you won’t be able get a word in edgewise in between all his grandstanding and “expertise.”", "related": "Grandstand (perform showily as if to impress an audience)", "moreinfo": "Don’t confuse with disclaim, which simply means “deny, repudiate.”", "hook": "de + claim (shout out): give a pompous formal speech.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "declivity", "pos": "noun", "pron": "dih-CLIV-it-ee", "also": "", "d1": "Downward slope", "sent": "Not just any <b>declivity</b> can serve as a wheelchair ramp—I’m pretty sure this thing is too steep to pass regulations.", "related": "Declination (downward slope, deterioration, deviation from the norm, refusal)", "moreinfo": "The opposite of declivity is acclivity, an upward slope.", "hook": "de (down) + clivity (slope): a downhill slope.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "delimit", "pos": "verb", "pron": "dih-LIM-it", "also": "", "d1": "Fix, mark, or define the boundaries of", "sent": "The role of an executive coach is <b>delimited</b> by our code of conduct—we may not counsel people for psychological conditions, for instance.", "related": "Demarcate (mark the boundaries of, separate)", "moreinfo": "Delimit is one of those words where the “de” doesn’t seem to be doing much—the definition is pretty close to that of limit.", "hook": "de + limit: mark the boundaries.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "demagogue", "pos": "noun", "pron": "DEM-uh-gah’g", "also": "", "d1": "A leader who lies and gains power by arousing the passions and especially prejudices of the people", "sent": "Political <b>demagogues</b> lie and twist the facts, depending more on their natural charisma and ability to determine exactly what their audience wants to hear than any actual understanding or perspicacity.", "related": "A Propagandist or Provocateur influences the public in ways that are probably more emotional than logical.", "moreinfo": "The Greek root “demos,” for “people,” also appears in democracy, demographics, and demotic (populist, pertaining to the people).", "hook": "demos (people) + agogue (leader): a leader who whips up prejudice.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "demur", "pos": "verb", "pron": "dih-MUR", "also": "", "d1": "Show reluctance or object, especially for moral reasons", "sent": "When asked to name her favorite professor in the department, she <b>demurred</b>—she was pretty sure that, if she said anything, it would come back to haunt her.", "related": "Balk (refuse to proceed or to do something)", "moreinfo": "", "hook": "\"de-MUR,\" murmur a reluctant no: object or hesitate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "desultory", "pos": "adj", "pron": "DESS-ull-tor-ee", "also": "", "d1": "Lacking consistency or order, disconnected, sporadic; going off topic", "sent": "Lulu said she’d been studying for the GRE for a year, but she had been doing so in only the most <b>desultory</b> way—a few vocab words here and there, then nothing for a month, and practice tests whenever she felt like it, which was rarely.\nDon’t mind my daughter—there’s no need to let a toddler’s <b>desultory</b> remarks pull an adult conversation off track.", "related": "", "moreinfo": "Desultory comes from the Latin “desultor,” a circus rider who jumps from one horse to another.", "hook": "a leaper jumping about (Latin desultor): aimless and disconnected.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "diaphanous", "pos": "adj", "pron": "die-AFF-uh-nuss", "also": "", "d1": "Very sheer, fine, translucent", "sent": "The wedding dress was a confection of <b>diaphanous</b> silk, made of at least ten layers of the thin fabric, each layer of which was so fine you could see through it.", "related": "Gossamer (a fine, filmy cobweb, or a fine, light fabric)", "moreinfo": "Diaphanous generally describes fabric or the (beautiful, translucent) wings of certain insects.", "hook": "dia (through) + phan (show): sheer, see-through.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "dichotomy", "pos": "noun", "pron": "die-COT-uh-mee", "also": "", "d1": "Division into two parts or into two contradictory groups", "sent": "There is a <b>dichotomy</b> in the sciences between theoretical or “pure” sciences such as physics and chemistry, and the life sciences, which often deal more with classifying than with theorizing.", "related": "Binary (consisting of or involving two), Duality (a dual state, existence in two parts, as in “Descartes posited a duality between mind and body”)", "moreinfo": "Dichotomy comes from the Greek “dicha” (apart) and “tomos” (cutting).", "hook": "di (two) + tomy (cut): a split into two opposed parts.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "dictum", "pos": "noun", "pron": "DICT-um", "also": "", "d1": "Formal or authoritative pronouncement; saying or proverb", "sent": "“A stitch in time saves nine” is an old <b>dictum</b> meaning that it’s easier to solve a problem before it gets too big.\nThe king’s <b>dictum</b> stated that each feudal lord must provide a certain number of soldiers within three weeks’ time.", "related": "Maxim, Apothegm, and Adage are all words for a proverb, saying, or truism", "moreinfo": "The root “dict” comes from “dicere” (to say) and also appears in dictator, dictionary, indict (connect to a crime), malediction (curse), benediction (blessing), and many others.", "hook": "dict (say): an authoritative saying.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "diffident", "pos": "adj", "pron": "DIFF-id-ent", "also": "diffidence (noun)", "d1": "Lacking confidence, shy", "sent": "Natasha was so <b>diffident</b> that she never believed her comments could be worth anything in class, even when she knew the answer.", "related": "Timorous (fearful, timid), Self-Effacing (modest, downplaying one’s own presence or accomplishments)", "moreinfo": "Diffident contains the root “fid,” for “trust,” also appearing in fidelity, fiduciary, and infidel. The connection is that a diffident person may be mistrustful of others, and thus shy.", "hook": "not confident: shy and self-doubting.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "diffuse", "pos": "verb, adj", "pron": "diff-YOOZ (v), diff-YOOSS (adj)", "also": "", "d1": "Spread widely, disseminate (verb); dispersed, widely spread out, or wordy and going off-topic (adj)", "sent": "The spy attempted to root out the dissenters at the gala, but he was only able to detect a <b>diffuse</b> sense of discontent all around the room.\nIt will be very difficult to <b>diffuse</b> the power among the people when transitioning from autocracy to democracy.", "related": "", "moreinfo": "A diffuser is a device that spreads air freshener or other scent by being plugged into an outlet. Don’t confuse diffuse with defuse, to calm or put an end to (to “defuse a fight”).", "hook": "dif + fuse (pour): spread or pour out widely; or wordy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 4", "setNum": 4, "coll": "Advanced"}, {"w": "dilate", "pos": "verb", "pron": "DIE-layt", "also": "", "d1": "To become wider or make wider, cause to expand; to speak or write at length, elaborate upon", "sent": "The doctor gave her eye drops to make her pupils <b>dilate</b>.\nThese dinners at Professor Hwang’s house usually run rather late—after the meal, he’ll typically <b>dilate</b> on his latest research for at least an hour.", "related": "Expatiate (to expand or elaborate on a topic, to explain in detail)", "moreinfo": "Dilate is used frequently in medicine—being a certain number of centimeters dilated is an important part of childbirth.", "hook": "pupils dilate: widen; or \"dilate on\" a topic means elaborate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dilatory", "pos": "adj", "pron": "DILL-uh-tor-ee", "also": "", "d1": "Slow, late; procrastinating or stalling for time", "sent": "Jack was supposed to start his presentation ten minutes ago and he isn’t even here? I’m not surprised—he’s a <b>dilatory</b> fellow.", "related": "Tardy (late), Temporize (stall for time)", "moreinfo": "", "hook": "\"dila-tardy\": slow, stalling, procrastinating.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dilettante", "pos": "noun", "pron": "DILL-uh-tahnt", "also": "", "d1": "Person who takes up an art or activity for amusement only or in a superficial way", "sent": "The “arts center” in the rich neighborhood was populated by <b>dilettantes</b>—a sculpture here, a bit of music appreciation there, two weeks of painting class until they got bored and quit.", "related": "Dabbler is a synonym, although somewhat less negative (like hobbyist). As in, “Are you a poet?” “I wouldn’t call myself a poet—I just dabble in poetry.”", "moreinfo": "Dilettante comes from the Latin “delectare,” meaning “to delight” and also found in delectable and delicious.", "hook": "a dilettante dabbles: a superficial amateur.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dirge", "pos": "noun", "pron": "DERJ", "also": "", "d1": "A funeral or mourning song or poem", "sent": "It was supposed to be a wedding march, but when the organist started playing, the reluctant bride thought the song sounded more like a <b>dirge</b> for her former, carefree life.", "related": "Lament (express sorrow, mourn), Requiem (musical service or hymn for the dead), Threnody (poem or song of mourning), Elegy (song or poem of sorrow, esp. for a deceased person)", "moreinfo": "Dirge is simply a version of the first word (“Direct, O Lord, my God...”) from a Latin prayer cycle said in the Roman Catholic Church for a deceased person.", "hook": "a funeral dirge: a mournful song.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "discomfiting", "pos": "adj", "pron": "diss-CUHM-fit-ing", "also": "", "d1": "Disconcerting, confusing, frustrating", "sent": "His fiancee’s family said they were comfortable with the fact that he was of a different religion, but he found their constant probing about his beliefs quite <b>discomfiting</b>./ He hates telemarketers so much that he likes to discomfit them by asking them personal questions and suggesting he call them at their homes instead.", "related": "Abash (destroy the confidence of, make ashamed, disconcert), Disquiet (disturb or cause anxiety to, as in “The anonymous phone message disquieted him.”)", "moreinfo": "Discomfit originally meant “defeat in battle” but today is closer to disconcert—possibly, over the years, people confused discomfit and discomfort, causing the shift in meaning.", "hook": "dis + comfort: unsettling, disconcerting.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "discordant", "pos": "adj", "pron": "diss-CORD-uhnt", "also": "discord (noun)", "d1": "Harsh or inharmonious in sound; disagreeing, incongruous", "sent": "In a graduation ceremony full of hopeful and congratulatory speeches, the salutatorian’s address about the terrible economy struck a <b>discordant</b> note.", "related": "Dissonance (harsh, inharmonious sound; cacophony; disagreement)", "moreinfo": "The opposite of discord is accord. Just as discord can be either about sound or ideas, accord can mean agreement or harmony, as in the sound of a (well-played) accordion.", "hook": "dis + chord: clashing, out of harmony.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "discrete", "pos": "adj", "pron": "diss-CREET", "also": "", "d1": "Separate, distinct, detached, existing as individual parts", "sent": "Be sure to use quotation marks and citations as appropriate in your paper in order to keep your ideas <b>discrete</b> from those of the experts you are quoting.\nThe advertising agency pitched us not on one campaign, but on three <b>discrete</b> ideas.", "related": "", "moreinfo": "Don’t confuse discrete with discreet, which means “secretive, undercover.”", "hook": "discrete, not discreet: separate, distinct parts.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "disparage", "pos": "verb", "pron": "diss-PAIR-edge", "also": "", "d1": "Belittle, put down; bring shame upon, discredit", "sent": "An Ad Hominem attack is a logical fallacy in which the arguer <b>disparages</b> his opponent rather than addressing the opponent’s ideas.\nYour shoplifting arrest has <b>disparaged</b> this family!", "related": "Denigrate (belittle, attack the reputation of)", "moreinfo": "The root “par” means “equal” and appears in peer and parity, meaning “equivalence or equality,” as well as disparate, meaning “distinct, different.”", "hook": "dis + parage: belittle and put down.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "disparate", "pos": "adj", "pron": "DISS-puh-rit or diss-PAIR-it", "also": "", "d1": "Distinct, different", "sent": "He chose the college for two <b>disparate</b> reasons: the strength of the computer science program, and the excellence of the hip-hop dance squad.", "related": "Divergent (different, deviating), Incommensurable (not comparable, totally disproportionate)", "moreinfo": "The root “par” means “equal” and appears in peer and parity, meaning “equivalence or equality,” as well as disparage, meaning “belittle.”", "hook": "\"dis-PAIR-ate,\" won't pair up: distinctly different.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dissemble", "pos": "verb", "pron": "diss-EM-bull", "also": "", "d1": "Mislead, conceal the truth, put on a false appearance of", "sent": "Roxanne was used to <b>dissembling</b> in job interviews; when asked about the gap on her resume from 1999–2003, she would say, “Oh, I was out of the workforce fulfilling some obligations”—a somewhat misleading way to describe a prison stint.\nHe won so much money at pool halls by <b>dissembling</b> inexperience, pretending at first that he had no idea how to even hold a pool cue; once bets were placed, he handily defeated his opponents.", "related": "Disingenuous (not genuine), Prevaricating (misleading or lying)", "moreinfo": "", "hook": "dis + resemble: put on a false face, hide the truth.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dissolution", "pos": "noun", "pron": "diss-uh-LOO-shun", "also": "dissolute (adj)", "d1": "Dissolving, the state of having been dissolved; breaking bonds or breaking up of a group of people; death, disintegration; sinking into extreme hedonism, vice, and degradation", "sent": "Raoul went from garden-variety hedonism to utter <b>dissolution</b>—his three-day drug benders cost him his job and may land him in jail.\nFollowing the <b>dissolution</b> of the corporation and the liquidation of our assets, each investor will receive a cash payment proportional to his or her shareholding in the company.", "related": "Licentiousness (excessive freedom, extreme hedonism), Profligacy (reckless extravagance, shameless behavior)", "moreinfo": "", "hook": "things dissolve and break up; also debauched living.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "distaff", "pos": "adj, noun", "pron": "DISS-taff", "also": "", "d1": "Female, esp. relating to the maternal side of the family; women or women’s work; a staff that holds wool or flax for spinning", "sent": "In completing your medical history, please try to remember which illnesses occurred on the <b>distaff</b> side of your family.\nMedical studies using all male study groups may produce results that cannot be replicated in <b>distaff</b> subjects.", "related": "", "moreinfo": "If using a word related to spinning wool to mean “women” seems offensive, some would agree, although the word is generally not offensive when discussing science and medicine; the NY Times has recently referred to “distaff subjects” in a medical study.", "hook": "the \"distaff side\": the female, maternal side.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "distend", "pos": "verb", "pron": "diss-TEND", "also": "distended (adj)", "d1": "Swell, expand, stretch, bloat", "sent": "The emergency room doctor constantly saw people who came in with <b>distended</b> bellies, sure that they had appendicitis; usually, it was just gas.", "related": "Balloon (swell or puff out), Turgid or Tumid (swollen, inflated; or, metaphorically “inflated,” such as in overblown, pompous speech)", "moreinfo": "", "hook": "dis + tend (stretch): swell and bloat.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dither", "pos": "verb, noun", "pron": "DIH-ther", "also": "", "d1": "Act indecisively (verb); a state of fear or trembling excitement", "sent": "“Stop <b>dithering</b>,” said the mother to her daughter. “Pick which sweater you want so I can pay for it and we can get out of here.”\nThe haunted house brought the children to a <b>dither</b> from which it was difficult for their parents to calm them down.", "related": "Vacillate and Equivocate also mean “act irresolutely,” or in common parlance, “flip- flop” in making a decision.", "moreinfo": "Dither may be related to dodder, meaning to shake or tremble, usually used in the sense of “a doddering old man.”", "hook": "dodder and waver: act indecisively.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "diurnal", "pos": "adj", "pron": "die-ER-null", "also": "", "d1": "Occurring every day; happening in the daytime (rather than at night)", "sent": "While many Americans rarely have a sit-down family meal, in many other cultures, dining as a family is a <b>diurnal</b> affair.\nWall Street is a <b>diurnal</b> neighborhood—hectic in the day, but quiet once people pile on the rush hour trains to go home.", "related": "Quotidian (daily; everyday, ordinary)", "moreinfo": "", "hook": "by day (vs nocturnal): daily, daytime.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "doctrinaire", "pos": "noun, adj", "pron": "doc-trin-AIR", "also": "", "d1": "Person who applies doctrine in an impractical or rigid and close-minded way (noun); merely theoretical, impractical, or fanatical about other people accepting one’s ideas (adj)", "sent": "The old science professor was so <b>doctrinaire</b> that he refused to even consider any evidence that flew in the face of his own research, and thereby failed to recognize when his graduate students made an exciting new discovery.\nDon’t be a <b>doctrinaire</b>—try actually considering the views of those you disagree with!", "related": "Dogmatic (close-minded, expressing one’s own opinions as though they were facts)", "moreinfo": "Doctrinaire is based on the word doctrine, meaning “official beliefs.” While doctrine can be good or bad, doctrinaire is always bad and denotes someone who has taken belief in a doctrine much too far.", "hook": "pushes doctrine rigidly: dogmatic and impractical.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "doff", "pos": "verb", "pron": "DOFF", "also": "", "d1": "Take off (such as clothes), put aside; remove one’s hat as a gesture", "sent": "Before the spring break revelers could consider <b>doffing</b> their clothes, they saw the sign: “No skinny dipping.”\nIn my grandfather’s day, it was considered polite to <b>doff</b> your hat when a lady entered the room; to us today, lifting your hat a few inches off your head and then putting it right back seems to some like a silly way to show respect.", "related": "", "moreinfo": "The opposite of doff is don, to put on. Interestingly, don came into being as a contraction of “do on.”", "hook": "\"do off\" (opposite of don): take off a hat or clothes.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dovetail", "pos": "verb", "pron": "DOVE-tail", "also": "", "d1": "Join or fit together", "sent": "When the neuroscientist married an exercise physiologist, neither thought they’d end up working together, but when Dr. Marion Ansel received a grant to study how exercise improves brain function and Dr. Jim Ansel was assigned to her team, the two found that their careers <b>dovetailed</b> nicely.", "related": "Converge (move towards one another or towards a point; unite)", "moreinfo": "In carpentry, a “dovetail joint” fits together in a precise way and resembles the shape of a dove’s tail.", "hook": "dovetail joints interlock: fit neatly together.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "droll", "pos": "adj", "pron": "DROHL", "also": "", "d1": "Funny in an odd way", "sent": "The play was a <b>droll</b> production—not laugh-out-loud hilarious, but funny especially because it was so strange. Who’s ever seen a fairy be mistaken for a block of cheese?", "related": "Waggish (merry, roguish), Risible (laughable, related to laughing), Jocular, Jocund, or Jocose (jesting, jolly)", "moreinfo": "Droll comes from a Middle Dutch word for imp, a mischievous demon.", "hook": "dryly funny: amusing in an odd way.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dupe", "pos": "noun, verb", "pron": "DOOP", "also": "", "d1": "Person who is easily fooled or used (noun); to fool or exploit (verb)", "sent": "The dashing rogue used flattery and lies to <b>dupe</b> several old ladies out of their money. “I feel like a total <b>dupe</b>,” said Hazel Rosenbaum, 87. “I thought he and I were going to get married, but he really just wanted my Social Security checks.”", "related": "Hoodwink, Bilk, Swindle, Con, and Fleece are all verbs for cheating others. Fleece is perhaps more severe, having the connotation of taking everything from the victim, the way one sheers all of the fleece from a sheep.", "moreinfo": "Dupe comes from Old French duppe, a bird known for being very stupid. Dupe can also be a short version of “duplicate,” although this meaning is somewhat informal and less likely on the GRE.", "hook": "a dupe gets duped: a fool who is tricked.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "duplicity", "pos": "noun", "pron": "doo-PLISS-it-ee", "also": "duplicitious (adj)", "d1": "Deceit, double-dealing, acting in two different ways for the purpose of deception", "sent": "The campaign worker’s <b>duplicity</b> finally came to light when it was discovered that, despite rising to a trusted position within the local Workers Party, he was actually a registered National Party member and was feeding information back to his cronies.", "related": "Dissembling (misleading, concealing the truth, acting hypocritically), Prevaricating (misleading or lying), Disingenuous (not genuine)", "moreinfo": "Duplicity was a 2009 film starring Julia Roberts. It was about spies.", "hook": "\"dupli\"=double dealing: two-faced deceit.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "dyspeptic", "pos": "adj", "pron": "diss-PEP-tick", "also": "", "d1": "Grumpy, pessimistic, irritable; suffering from dyspepsia (indigestion)", "sent": "The <b>dyspeptic</b> professor was so angered by a question from a student who hadn’t done the homework that he actually stomped out of class.", "related": "Curmudgeon (bad-tempered, difficult person), Crotchety (grouchy, picky, given to odd notions), Cantankerous (disagreeable, contentious), Crank (an unbalanced person who is fanatical about a private, generally petty cause)", "moreinfo": "Dyspeptic describes a physical condition but is often used metaphorically; indigestion does tend to make a person feel irritable. Similarly, myopia describes the physical condition of nearsightedness, but is often used metaphorically to mean “given to unwisely short-term thinking.”", "hook": "dys (bad) + peptic (digestion): grumpy, like bad indigestion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "ebullient", "pos": "adj", "pron": "ebb-OOL-yent", "also": "", "d1": "Very enthusiastic, lively, excited; bubbling as though being boiled", "sent": "The children were so <b>ebullient</b> upon their arrival at Disneyworld that their parents, while happy to see them so excited, wished that there were a way to forcibly restrain them in case they took off running towards the rides.", "related": "Exuberant (extremely, uninhibitedly enthusiastic or joyful; overflowing)", "moreinfo": "Ebullient comes from a Latin word for “boiling,” which comes from a word for “bubble.” An ebulliometer determines the boiling point of liquids.", "hook": "bubbling over as if boiling: bubbly and enthusiastic.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "echelon", "pos": "noun", "pron": "ESH-uh-lahn", "also": "", "d1": "A level, rank or grade; the people at that level", "sent": "Obtaining a job on Wall Street doesn’t guarantee access to the upper <b>echelon</b> of executives, where multi-million dollar bonuses are the norm.\nI’m not sure I’m cut out to analyze poetry; I find it hard to dig beyond the most accessible <b>echelon</b> of meaning.", "related": "Stratum (a layer, esp. one of a number of parallel layers, such as in sedimentary rock or the Earth’s atmosphere; plural is strata, as in “Of all the strata of society, the middle class is the stratum hit hardest by the recession.”)", "moreinfo": "The original meaning of echelon is a formation of troops or war vehicles so as to resemble steps; similarly, birds flying in such a pattern are flying in echelon.", "hook": "the \"upper echelon\": a rank or level.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "edify", "pos": "verb", "pron": "ED-ih-fy", "also": "edifying (adj)", "d1": "Uplift, enlighten, instruct or improve in a spiritual or moral way", "sent": "Look, Son, I’m glad that you’re reading, but I really wish you would read something more <b>edifying</b> than that magazine that gives tips for winning at violent video games.", "related": "", "moreinfo": "Edifying isn’t actually etymologically related to edible, but it’s a good memory trick to think of something edifying as “food for the soul.”", "hook": "edi (build): build someone up morally, enlighten.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 5", "setNum": 5, "coll": "Advanced"}, {"w": "effigy", "pos": "noun", "pron": "EFF-ih-jee", "also": "", "d1": "Representation or image of a person, esp. a crude facsimile used to mock a hated person", "sent": "The dictator was disturbed to look out the palace window and see himself being burned in <b>effigy</b>. “That paper mache dummy doesn’t even look like me!” he said.", "related": "", "moreinfo": "A scarecrow is a common type of effigy, intended to scare birds away and keep them from eating crops. Effigies are often large or life-sized. The expression “burned in effigy” is sometimes used as hyperbole, as in “After the university president announced a major tuition hike, I thought the students were going to burn him in effigy.”", "hook": "burned in effigy: a crude mock image of a hated person.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "effrontery", "pos": "noun", "pron": "eff-RUN-ter-ee", "also": "", "d1": "Shameless boldness", "sent": "Mr. Jackson thought his daughter’s boyfriend guilty of the worst <b>effrontery</b> when he asked for her hand in marriage—and, as soon as Mr. Jackson gave his blessing, followed up by asking for a job at Mr. Jackson’s company.", "related": "Audacious (very bold or brave, often in a rude or reckless way; extremely original), Insolent (bold in a rude way), Brazen (shameless, contemptuously bold)", "moreinfo": "The “front” in effrontery means brow or forehead; the word comes from the idea of “putting forth one’s forehead,” in a sense similar to the use of “barefaced” in the expression “barefaced liar.”", "hook": "ef + front: shameless, in-your-face nerve.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "egress", "pos": "verb, noun", "pron": "EE-gress", "also": "", "d1": "An exit or the action of exiting", "sent": "It is against the fire code to put those boxes there—you can’t block a primary or secondary <b>egress</b> from the building.", "related": "Outlet can mean an exit or vent, or a means or expression or publication. “You can’t grill in the house—there’s no outlet for smoke! You obviously need an outlet for your frustrated desire to be a chef.”", "moreinfo": "Egress shares a root with grade, meaning “move or step.” Just as you exit fifth grade to enter sixth grade, or as the land grades into the sea, egress involves a shift in position. The opposite of egress is ingress, meaning “entering.”", "hook": "e (out) + gress (go): an exit (opposite of ingress).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "elegy", "pos": "noun", "pron": "ELL-uh-jee", "also": "", "d1": "Song or poem of sorrow, esp. for a deceased person", "sent": "While composing an <b>elegy</b> is certainly old fashioned, the poet felt that it was a fitting way for her to honor her father at his funeral.", "related": "Dirge (a funeral or mourning song or poem), Lament (express sorrow, mourn), Requiem (musical service or hymn for the dead), Threnody (poem or song of mourning)", "moreinfo": "", "hook": "an elegy mourns the dead: a sorrowful poem.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "emaciate", "pos": "verb", "pron": "im-MAY-shee-ayt or im-MAY-see-ayt", "also": "emaciated (adj)", "d1": "Make abnormally thin, cause to physically waste away", "sent": "After fifty days floating on a raft at sea, he was quite <b>emaciated</b>—his family was elated that he was alive, but shocked to see a formerly 165-pound man looking skeletal at just 125 pounds.", "related": "Atrophy (wasting away, degeneration, decline, esp. of a body part or organ, as in “Her leg muscles had atophied while her leg was in a cast.”)", "moreinfo": "The word emaciated frequently appears in the news in discussions of whether fashion models are too thin.", "hook": "makes you meager: waste away to skin and bone.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "encomium", "pos": "noun", "pron": "en-COH-mee-um", "also": "", "d1": "Warm, glowing praise, esp. a formal expression of praise", "sent": "Just after all the <b>encomium</b> at his retirement party, he received a gold watch.\nThe first draft of your dissertation is little but <b>encomium</b> of the works of Christopher Marlowe, whereas I’m afraid that doctoral-level work requires a more nuanced and critical view.", "related": "Laudation (praise, tribute), Eulogy (a speech of praise or written work of praise, esp. a speech given at a funeral), Panegyric (formal, lofty, or elaborate praise), Paean (song of praise, triumph, or thanks)", "moreinfo": "", "hook": "en + comium (praise): glowing formal praise.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "endemic", "pos": "adj", "pron": "en-DEMM-ick", "also": "", "d1": "Native, local; natural, specific to, or confined to a particular place", "sent": "Certain diseases—especially those that require a precise mix of environmental conditions and local plant and animal life to thrive—remain <b>endemic</b> to particular regions.", "related": "The antonym of endemic is pandemic, “widespread, universal,” also generally of a disease or something bad.", "moreinfo": "Endemic contains the Greek “en” (in) and “demos” (people). Don’t confuse endemic with epidemic, which means “rapidly spreading” and is a near-synonym with pandemic.", "hook": "en (in) + demos (people): native to a place.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "engender", "pos": "verb", "pron": "en-JEN-der", "also": "", "d1": "Produce, give rise to, cause to exist; procreate", "sent": "The television demagogue was blamed for <b>engendering</b> hate and divisiveness.\nHaving four wives helped the magnate <b>engender</b> 15 children.", "related": "Beget (cause or produce; make children, esp. as a male parent, as in “John Adams, father of John Quincy Adams, was the first President to beget another President.”)", "moreinfo": "Engender shares a root with generate, genus, gender, genocide and many others—“gen” can mean “birth, produce, race.”", "hook": "en + gender (produce): give rise to, generate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "epicure", "pos": "noun", "pron": "EPP-ick-yoor", "also": "epicurean (adj)", "d1": "Person with cultivated, refined tastes, esp. in food and wine", "sent": "A true <b>epicure</b>, he served only the finest wines, and bragged about how the pancetta was imported from Italy and the Stilton cheese from the English countryside.", "related": "Connoisseur (expert, especially in the fine arts; person of educated, refined tastes), Discriminating (judicious, discerning, having good insight)", "moreinfo": "The Epicureans were Greek philosophers who did indeed hold that human pleasure was the highest good, although they believed that a simple life was key to that pleasure. Don’t confuse modern epicures with hedonists, or those devoted to pleasure—one way to think of the difference is that, if your parents are epicures, you probably grew up eating very well, but if your parents are hedonists, you probably don’t want to know about it.", "hook": "an epicure savors fine food and wine: a refined gourmet.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "equanimity", "pos": "noun", "pron": "eck-wuh-NIM-it-ee or ee-kwuh-NIM-it-ee", "also": "equanimous (adj)", "d1": "Composure, evenness of mind; mental or emotional stability, esp. under stress", "sent": "As she had worked for many years in mental hospitals, her <b>equanimity</b> was unparalleled— you could throw a chair or a bowl of spaghetti at her and she would just say, “Settle down, now.”", "related": "Sangfroid (calmness, self-possession, esp. under strain), Aplomb (self-possession, poise, total confidence even under stress), Imperturbable (not able to be upset or agitated, calm)", "moreinfo": "Don’t confuse equitable and equity with equanimity and equanimous; the first set is about equality, the second set about being even-tempered.", "hook": "equal + animus (mind): even-minded calm under stress.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "equivocate", "pos": "verb", "pron": "eck-WIV-uh-cayt", "also": "", "d1": "Use unclear language to deceive or avoid committing to a position", "sent": "Not wanting to lose supporters, the politician <b>equivocated</b> on the issue, tossing out buzzwords related to each side while also claiming more study was needed.", "related": "Ambivalent (uncertain; unable to decide, or wanting to do two contradictory things at once), Vacillate and Waffle (waver, be indecisive), Dither (act irresolutely), Hedge (avoid commitment by leaving provisions for withdrawal or changing one’s mind; protect a bet by also betting on the other side), Palter (talk insincerely; bargain or haggle), Tergiversate (repeatedly change one’s opinions, equivocate)", "moreinfo": "The Latin origin of equivocate is obvious—think of it as being “equally vocal” for two or more positions.", "hook": "equi (equal) + voc (voice): talk two ways to dodge, waffle.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "ersatz", "pos": "adj", "pron": "ER-zats or er-ZATS", "also": "", "d1": "Artificial, synthetic; being an inferior substitute", "sent": "I hate this health food restaurant! I do not want to eat some <b>ersatz</b> meatballs made of textured vegetable protein!", "related": "Apocryphal, Faux, Bogus and Specious are all words for “fake or dubious.” Factitious can mean “made by humans” or “artificial, sham.”", "moreinfo": "Ersatz comes from German. Ersatzbrot, or “replacement bread” (made of the lowest quality ingredients sometimes mixed with sawdust) and Ersatzkaffee (a substitute made from grain) were served by the Germans to POWs during World War II.", "hook": "ersatz coffee (German for substitute): a fake, inferior stand-in.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "erstwhile", "pos": "adj, adv", "pron": "ERST-while", "also": "", "d1": "Former, previous (adj); in the past, formerly (adv)", "sent": "A novelist and <b>erstwhile</b> insurance salesman, he told us his story of the long road to literary success, before he was able to quit his day job.", "related": "Bygone (past, former), Quondam (former, sometime)", "moreinfo": "Erstwhile is related to the Old English ere, which means “before.”", "hook": "erst (formerly) + while: former, in the past.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "ethos", "pos": "noun", "pron": "EETH-ohss or EETH-ahss", "also": "", "d1": "The character, personality, or moral values specific to a person, group, time period, etc.", "sent": "At the prep school, the young man happily settled into an <b>ethos</b> of hard work and rigorous athletic competition.", "related": "Disposition (a person’s general or natural mood; tendency), Tenor (general drift, course, or purpose, as in “the rebellious tenor of the rally”), Penchant and Predilection (“tendency, preference,” as in a penchant for fast cars, a predilection to get angry easily)", "moreinfo": "Ethos is a Greek word meaning “custom or character,” much as it does today.", "hook": "a group's ethos: its character and values (ethics).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "euphemism", "pos": "noun", "pron": "YOO-fuh-mizm", "also": "", "d1": "Substitution of a mild, inoffensive, or indirect expression for one that is considered offensive or too direct", "sent": "Many <b>euphemisms</b> surround death and disease; rather than “Joe died of cancer,” many people feel better saying “Joe’s suffering is finally over.”\nWhen potty training their children, some parents use hilarious <b>euphemisms</b> for body parts.", "related": "", "moreinfo": "The antonym of euphemism is dysphemism, an unnecessarily bad name for something. The internet division of the publishing company dysphemistically referred to the print magazine as the “dead tree edition.”", "hook": "eu (good) + phem (speak): a mild word for a harsh one.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "euphony", "pos": "noun", "pron": "YOO-fun-nee", "also": "", "d1": "Pleasing or sweet sound, especially as formed by a harmonious use of words", "sent": "Poetry in translation can keep its meaning, but often loses the <b>euphony</b> the poet worked so laboriously to create.", "related": "Dulcet (melodious, agreeable to the ear), Mellifluous (richly and smoothly flowing, as “a mellifluous voice”)", "moreinfo": "Euphony is simply a combination of two roots: “eu” for “good” and “phon” for “sound” (as in telephone, phonics, etc.) A euphonium is an instrument similar to a small tuba.", "hook": "eu (good) + phony (sound): a pleasing, sweet sound.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "exigent", "pos": "adj", "pron": "ECK-sih-jent", "also": "", "d1": "Requiring immediate attention, action, or aid; excessively demanding", "sent": "My boss said she would take me out to lunch and “mentor” me, but that idea always gets tossed aside in favor of more <b>exigent</b> matters.", "related": "Dire (causing suffering or fear; ominous; urgent or desperate, as in “a dire emergency requiring immediate response”)", "moreinfo": "Don’t confuse exigent with expedient, which means either “suitable, proper” or “opportune; effective, often at the expense of ethics or other considerations,” as in “In the face of an exigent problem, the boss risked a serious lawsuit by doing what was expedient instead of what was right.”", "hook": "an exigency is urgent: demanding immediate action.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "exonerate", "pos": "verb", "pron": "egg-ZAH-ner-ayt", "also": "", "d1": "Clear from blame or accusation; free from a responsibility", "sent": "When the defendant was <b>exonerated</b> after a long trial, his family wept for joy.", "related": "Exculpate and Vindicate also mean “free from blame.”", "moreinfo": "Exonerate shares a root with onerous and onus, meaning “burden or obligation.” Since “ex” means “out,” exonerate can be thought of as removing a burden (generally, that of guilt).", "hook": "ex (out) + onus (burden): lift the burden of blame, clear.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "expedient", "pos": "adj", "pron": "eck-SPEE-dee-unt", "also": "", "d1": "Suitable, proper; effective, often at the expense of ethics or other considerations", "sent": "“I need this report by 2pm, and I don’t care what you have to do to make that happen,” said the boss. “I expect you to deal with it <b>expediently</b>.”\nWhen invited to a wedding you cannot attend, it is <b>expedient</b> to send a gift.", "related": "Opportune (suitable, convenient, occurring at an appropriate time)", "moreinfo": "Don’t confuse expedient with exigent, “requiring immediate attention, action, or aid.”", "hook": "convenient but maybe unethical: a practical shortcut.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "expurgate", "pos": "verb", "pron": "ECK-sper-gayt", "also": "", "d1": "Censor; remove objectionable or offensive parts", "sent": "When the girl discovered that her ninth-grade class had been reading an <b>expurgated</b> version of Romeo and Juliet, she immediately checked the original out from the library so she could read all the “forbidden” parts.", "related": "Bowdlerize (expurgate, abridge, or distort), Expunge (strike, eliminate, mark for deletion)", "moreinfo": "Expurgate shares a root with purge, purgation, and purify.", "hook": "ex (out) + purge: censor out the offensive parts.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "extemporaneous", "pos": "adj", "pron": "eck-stem-por-AY-nee-uss", "also": "", "d1": "Done without preparation (esp. of a speech), or with some preparation but no notes; improvised, done on the spur of the moment", "sent": "The way the Public Affairs Forum works is that the moderator will announce a topic, and then anyone who wishes may speak <b>extemporaneously</b> on that topic for a few minutes—as you can imagine, our members are very well-read.\nLost in the jungle, the hikers fashioned an <b>extemporaneous</b> shelter from palm leaves.", "related": "Impromptu (done with no or little preparation, esp. of musical or other performance), Ad-lib (improvise; something improvised)", "moreinfo": "Extempore is a variant with the same meaning. “Off-the-cuff” is an expression that means extemporaneous.", "hook": "ex tempore, out of the moment: improvised, unprepared.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "faction", "pos": "noun", "pron": "FACT-shun", "also": "", "d1": "Group or clique within a larger organization; party strife and dissension", "sent": "The opposition movement was once large enough to have a chance at succeeding, but it has since broken into numerous, squabbling <b>factions</b>, each too small to have much impact.\nThe caucus began in a spirit of unity but now, sadly, is marked by <b>faction</b> and petty squabbles.", "related": "Partisan (partial to a particular party, group, etc., esp. in a biased, emotional way), Cabal (a conspiratorial group)", "moreinfo": "Faction contains the root “fact,” meaning “make or do,” also appearing in factory and factitious (made up).", "hook": "a faction factions off: a clique within a group.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "fallow", "pos": "adj", "pron": "FAL-oh", "also": "", "d1": "Left unplanted (of land); not in use", "sent": "Crop yields were increased substantially when the villagers discovered that leaving a portion of their fields lie <b>fallow</b> allowed that unused part of the land to become renewed with minerals.\nIt is terribly important that we make college affordable for underprivileged students, lest great minds lie <b>fallow</b>, and the world never benefit from their genius.", "related": "Another GRE word related to farming is arable, which means “able to be farmed, fertile,” as in “arable land.”", "moreinfo": "Fallow can mean “light yellowish-brown.” Although this seems like a color that an untended field might turn, this meaning of the word comes from a different origin.", "hook": "fields lie fallow: unplanted, unused.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "fastidious", "pos": "adj", "pron": "fass-TIH-dee-uss", "also": "", "d1": "Excessively particular, difficult to please; painstaking, meticulous, requiring excessive attention to detail", "sent": "Steve was a <b>fastidious</b> housekeeper, fluffing his couch pillows at least twice a day and never allowing the tiniest speck of dust to settle on any exposed surface.", "related": "Meticulous (taking extreme care with details; fussy), Exacting (severe in making demands; requiring precise attention)", "moreinfo": "Fastidious comes from a Latin word for disgust. Fastidious people are easily disgusted by regular people’s housekeeping, manners, work standards, etc.", "hook": "\"fast + tidy\": fussy, meticulous, hard to please.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "fatuous", "pos": "adj", "pron": "FAT-choo-uss", "also": "", "d1": "Foolish, silly, esp. in a smug or complacent manner", "sent": "Sadly, every philosophy class seems to have one person who responds to every discussion, from metaphysics to ethics, with the <b>fatuous</b> question, “But what if we don’t really exist?”", "related": "Inane (lacking sense, silly; empty), Waggish (merry, roguish), Risible (laughable, related to laughing), Jocular, Jocund, or Jocose (jesting, jolly), Droll (funny in an odd way)", "moreinfo": "Don’t confuse fatuous with facetious, meaning “joking, humorous, esp. inappropriately.” Facetious people can be smartly sarcastic; fatuous people are dull and dim-witted. Fatuous comes from a word for gaping—as in, having one’s mouth hang open like a very stupid person.", "hook": "fat-headed: smugly foolish.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 6", "setNum": 6, "coll": "Advanced"}, {"w": "fawn", "pos": "verb", "pron": "FAWN", "also": "", "d1": "Show affection or try to please in the manner of a dog; try to win favor through flattery and submissive behavior", "sent": "Although he was only president of a chain of grocery stores, he was used to being <b>fawned</b> over like a king or rock star. “You are truly king of the low-priced produce world,” said the regional manager. “May I wash your car for you?”", "related": "Sycophant, Lackey, Toady, and Myrmidon are all words for a person who fawns, such as the regional manager in the sentence above. The adjective Obsequious means fawning. The verb Truckle means to act subserviently and Kowtow means to fawn—or, literally, to bow until one’s forehead touches the floor.", "moreinfo": "", "hook": "a dog fawns for treats: grovel and flatter.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fecund", "pos": "adj", "pron": "FEE-cuhnd or FECK-uhnd", "also": "fecundity (noun)", "d1": "Fruitful, fertile; capable of abundantly producing offspring, vegetation, or creative or intellectual work", "sent": "Rabbits are quite <b>fecund</b>; if you’ve got two, you’ll soon have forty.\nWhile some novelists seem to return to the same themes over and over, Bredlaw’s <b>fecund</b> mind produced whole new universes for every story he wrote.", "related": "Prolific is a synonym. Teeming means “full of things, abundantly filled,” as in “Rome was teeming with tourists.”", "moreinfo": "Fecund, unsurprisingly, shares a root with fetus.", "hook": "fruitful and fertile: abundantly productive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "felicitous", "pos": "adj", "pron": "fuh-LISS-it-uss", "also": "", "d1": "Admirably appropriate, very well-suited for the occasion; pleasant, fortunate, marked by happiness", "sent": "“What a <b>felicitous</b> occasion!” said the new grandfather, arriving at the hospital with an “It’s a Girl!” balloon. The new father found the balloon remarkably <b>felicitous</b>, especially since the baby’s gender had been announced less than an hour ago.", "related": "Apt is a synonym in its meaning of “exactly appropriate” (Apt can also mean “inclined, having a natural tendency” or “quick to learn”). Fortuitous means “happening by chance, accidental” and usually also has the meaning of “lucky.”", "moreinfo": "Felicity means happiness and can also be a woman’s name, as in the titular character of the televised drama Felicity (1998–2002).", "hook": "full of felicity (happiness): aptly and happily suited.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fervid", "pos": "adj", "pron": "FER-vid", "also": "", "d1": "Very hot; heated in passion or enthusiasm", "sent": "He is a <b>fervid</b> fan of Virginia Tech football, so much so that we’ve all gotten used to receiving “Go Hokies!” hats and shirts for every birthday.", "related": "Ardent (very passionate), Zealous (full of fervor or dedicated enthusiasm for a cause, person, etc.)", "moreinfo": "Like fervid, Fervent and Perfervid also mean “passionate, fiery, deeply enthusiastic” and come from a common root relating to heat.", "hook": "fever + vivid: burning with passion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fetid", "pos": "adj", "pron": "FET-id or FEE-tid", "also": "", "d1": "Stinking; having an offensive smell", "sent": "I hate doing your laundry—it’s always full of <b>fetid</b> gym socks.", "related": "Noisome (disgusting, foul), Noxious (harmful to health; corrupting) Memory Trick: Fetid looks a little like “feet”—smells like feet, too.", "moreinfo": "", "hook": "\"fe-TID\" stench: foul-smelling.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fledgling", "pos": "noun, adj", "pron": "FLEDGE-ling", "also": "", "d1": "A young bird that has just recently gotten its feathers, an inexperienced person (noun); new or inexperienced (adj)", "sent": "The zoo’s EagleCam will hopefully be able to catch the moment the <b>fledglings</b> fly out of the nest for the very first time!\nThe Society of Engineers is available for career day presentations in elementary schools, where we hope to encourage <b>fledgling</b> talents in the applied sciences.", "related": "Tyro (beginner, novice)", "moreinfo": "The verb fledge means to nurture, as one would a young bird until it is ready to fly, or to cover with feathers or adorn.", "hook": "a bird that just got its feathers: a novice.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "florid", "pos": "adj", "pron": "FLOR-id", "also": "", "d1": "Reddish or rosy; flowery, showy, or excessively fancy", "sent": "His writing was so <b>florid</b> that it was hard for modern readers to understand, and unintentionally humorous when they did. He once called a woman in a hoop skirt a “confection of gossamer-clad ephemerality, the bounty of her raiment ringing in my turgid heart like the tintinnabulation of so many church bells.”", "related": "Ruddy (having reddish skin, in a manner indicating health), Bombastic (far too showy or dramatic than is appropriate; pretentious), Turgid and Tumid (inflated like a balloon, or using language much too fancy for the sentiment or occasion), Declamatory (pompous, merely oratorical), Magniloquent and Grandiloquent (speaking in a lofty, grandiose style), Rococo (ornate, florid)", "moreinfo": "Florid, of course, shares a root with flower.", "hook": "flor (flower): flushed red, or overly flowery.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "flout", "pos": "verb", "pron": "FLOUT", "also": "", "d1": "Treat with disdain, contempt, or scorn (usually of rules)", "sent": "He <b>flouted</b> the boarding school’s curfew so blatantly that, on his way back from a party that lasted past midnight, he actually stopped by the headmaster’s house to say hello to his daughter.", "related": "", "moreinfo": "Don’t confuse with flaunt, meaning “to show off or parade oneself in a conspicuous way.” Flout comes from Middle English “flouten,” meaning “to play the flute.” Apparently it was once possible to play the flute at someone in a jeering way.", "hook": "flout the rules: openly scorn and defy them.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fluke", "pos": "noun", "pron": "FLOO’k", "also": "", "d1": "Stroke of luck, something accidentally successful", "sent": "It’s amazing that I won the prize during halftime, but I guarantee you, it was just a <b>fluke</b> that I made that basket—if I tried a thousand more times, I’m sure I couldn’t do it again.", "related": "Fortuitous (accidental, lucky), Windfall (unexpected, sudden gain or good fortune, as in “The prize winner’s windfall more than solved his mortgage problem.”)", "moreinfo": "A fluke can also be a flatworm (a “liver fluke”), type of fish, anchor blade, barbed arrowhead, or even a lobe of a whale’s tail. What all of these objects have in common is being flat (the old Germanic root means flat). The origin of fluke as a “stroke of good luck” is unknown— having flukes parasitizing your liver, for instance, sounds incredibly unlucky.", "hook": "a lucky fluke: an accidental success.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "forage", "pos": "verb", "pron": "FOR-idge", "also": "", "d1": "Wander in search of; rummage, hunt, make a raid", "sent": "It’s important to seal your trash cans tightly in this neighborhood, or else you’ll get raccoons <b>foraging</b> for food in your backyard.", "related": "Plunder, pillage, ransack, depredate, and despoil are words that match the meaning of raiding or looting, although forage is more often used in the gentler sense of poking around the forest looking for edible plants.", "moreinfo": "Forage shares an origin with fodder, meaning “food for livestock” and also used to mean raw material, or something low quality but abundant, as in “The novelist used all of her family arguments as fodder for her work.”", "hook": "animals forage for food: hunt and rummage.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "ford", "pos": "noun, verb", "pron": "FORD", "also": "", "d1": "Place where a river or similar body of water is shallow enough to walk or ride a vehicle across (noun); to cross at such a place (verb)", "sent": "The pioneers made camp near the riverbank, waiting for the rains to die down and the river to become <b>fordable</b> again. A week later, the waters were shallow enough to <b>ford</b> the river with their entire caravan—horses, wagons, and all.", "related": "Traverse (pass over, along, or through; go across)", "moreinfo": "It doesn’t particularly look like it, but ford is related to Latin “portus,” meaning “port.”", "hook": "ford a river: cross at a shallow spot.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "forestall", "pos": "verb", "pron": "fore-STALL", "also": "", "d1": "Delay, hinder, prevent by taking action beforehand", "sent": "Our research has been <b>forestalled</b> by a lack of funding; we’re all just biding our time while we wait for the university to approve our grant proposal.", "related": "Waylay (attack after lying in wait, intercept unexpectedly), Obviate (prevent, make unnecessary), Preclude (prevent, make impossible, exclude), Stymie (hinder, thwart)", "moreinfo": "“Fore” means “before” and stall means thwart, stop, or hinder, as in “She was stalled in traffic for hours.”", "hook": "fore (before) + stall: head it off in advance.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fortuitous", "pos": "adj", "pron": "for-TOO-it-uss", "also": "", "d1": "Happening by chance; lucky", "sent": "It was amazingly <b>fortuitous</b> that the exclusive beach resort had a cancellation for exactly the weekend she had wanted to get married, allowing her to have the perfect wedding after all.", "related": "Fluke (stroke of luck, something accidentally successful), Inadvertent (unintentional, characterized by a lack of attention)", "moreinfo": "Fortuitous shares a root with fortune. It usually carries both the sense of “happening accidentally” and “fortunate,” but can also mean happening by chance in a negative or neutral way.", "hook": "Fortuna's luck: happening by lucky chance.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fracas", "pos": "noun", "pron": "FRAY-cuss or FRACK-uss", "also": "", "d1": "Noisy disturbance or fight; brawl", "sent": "Rugby is one of the most aggressive of sports—when the players rush to pile on top of the person with the ball, bones can easily be broken in the <b>fracas</b>.", "related": "Fray (scuffle, brawl, heated dispute)", "moreinfo": "In French, “fracasser” is to shatter; in Italian, “fracassare” is to make an uproar. Those, and fracas, come from Latin “frangere” (to break), also appearing in frangible, or breakable.", "hook": "a fracture of a brawl: a noisy fight.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fractious", "pos": "adj", "pron": "FRACK-chuss", "also": "", "d1": "Unruly, troublemaking; irritable", "sent": "The Students for Progressive Action were a <b>fractious</b> bunch, always fighting with one another over exactly which progressive action should take priority.", "related": "Obstreperous (unruly, noisy), Refractory (stubbornly disobedient), Captious (faultfinding, making a big deal of trivial faults)", "moreinfo": "The word fraction once meant “brawling, discord”—even today, a fraction (in math) is something that has been broken up. Don’t confuse fractious with factious, meaning “party strife, breaking into factions or cliques within a larger organization.”", "hook": "splinters and fights: unruly and irritable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "frenetic", "pos": "adj", "pron": "fruh-NET-ick", "also": "", "d1": "Wildly excited, frantic, distracted", "sent": "The advice in the expert’s time management book struck many as unrealistic, as not everyone can handle the <b>frenetic</b> lifestyle the author espouses: getting up before dawn to begin work before spending quality time with the kids over breakfast, taking conference calls from the treadmill, etc.", "related": "Frenzied (wildly excited; violently agitated)", "moreinfo": "The Greek “phren” meant “mind”; frenetic is related to the idea of an inflammation or disease of the brain.", "hook": "frantic + frenzy: wildly excited.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "fulminate", "pos": "verb", "pron": "FULL-min-ayt", "also": "", "d1": "Explode, detonate; attack verbally in a vehement, thunderous way", "sent": "Please don’t bring up anything related to gun control around my family, or my dad will <b>fulminate</b> for hours about the Second Amendment.", "related": "To rail against or rail at is to issue a bitter denunciation of.", "moreinfo": "Fulminate comes from a Latin word for “hurl lightning.” When you fulminate, you are as angry as the Romans imagined Jupiter to be, hurling lightning bolts in your fury!", "hook": "full detonation: explode, or rail against thunderously.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "furtive", "pos": "adj", "pron": "FUR-tiv", "also": "", "d1": "Done secretly; stealthy, sly, shifty", "sent": "As a spokesperson for a popular diet plan, the actress had to be quite <b>furtive</b> about eating junk food, even hiding her M&Ms in a breath mint container lest the paparazzi snap photos of the inside of her car.", "related": "Clandestine, Covert, and Surreptitious all mean secret, undercover. Furtive contains the added sense of doing something wrong. For instance, the National Clandestine Service is part of the CIA, and military units regularly engage in covert operations. It is unlikely, though, that a government would ever use furtive in the name of its departments or operations, due to the word’s negative associations. Furtive, in fact, comes from a Latin word for “thief.”", "moreinfo": "", "hook": "a furtive thief (fur = thief): stealthy and sly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "gambol", "pos": "verb", "pron": "GAM-bull", "also": "", "d1": "Frolic; skip or leap playfully", "sent": "Watching the children <b>gambol</b> in the park like frisky little lambs, she wondered how they could have so much energy.", "related": "Caper (gambol; or, a prank, trick, or carefree activity), Cavort (prance, make merry), Lark (merry adventure)", "moreinfo": "Gambol comes from the Latin “gamba,” a horse’s leg.", "hook": "lambs gambol in spring: frolic and leap playfully.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "garner", "pos": "verb", "pron": "GAR-ner", "also": "", "d1": "Gather and store; amass, collect", "sent": "The publisher sent copies of the soon-to-be-published manuscript to reviewers, hoping to <b>garner</b> acclaim and publicity for the book.", "related": "Accrue (increase gradually), Augment (grow larger), Agglomerate (form into a mass or cluster, join together), Aggregate (gather together, amount to), Consolidate (unite, combine, firm up—you can consolidate loans or consolidate power)", "moreinfo": "Don’t confuse garner with garnish, which means either to decorate (such as with a radish carved into a flower next to your sushi) or to take a portion off the top, as in, “After he lost a lawsuit and failed to pay, the judge ordered that his wages be garnished and the money sent directly from his employer towards his debts.” Garner comes from granary, a place to store grain.", "hook": "gather into a granary: collect and amass.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "gestation", "pos": "noun", "pron": "jess-TAY-shun", "also": "gestate (verb)", "d1": "Pregnancy; the period from conception until birth of an animal or (metaphorically) of an idea or plan", "sent": "The <b>gestation</b> period of an elephant is 22 months, more than twice as long as that of humans!", "related": "", "moreinfo": "Just as you can conceive of an idea, you can also gestate metaphorically—“I had the idea for this novel in 2001. After letting it gestate for a decade, I finally got started writing.”", "hook": "gestation is pregnancy: a developing period.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "glacial", "pos": "adj", "pron": "GLAY-shull", "also": "", "d1": "Pertaining to glaciers; cold, icy, slow, unsympathetic", "sent": "He had wanted to appear in the singing reality competition his whole young life, but he was not encouraged by the judges’ <b>glacial</b> response to his audition. The awkward silence was excruciating as he waited for the stony-faced panel to say anything at all.", "related": "Frigid (very cold, without human warmth or emotion), Gelid (icy)", "moreinfo": "A very obvious metaphor—glaciers are cold, slow, and (naturally) don’t have feelings. A person who acts like a glacier is unpleasant indeed.", "hook": "glacier-slow and cold: icy, slow, unsympathetic.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "glower", "pos": "verb", "pron": "GLAH-wer", "also": "", "d1": "Stare in an angry, sullen way", "sent": "He couldn’t figure out why his girlfriend was <b>glowering</b> at him throughout dinner. “Oh,” he finally realized, “Is it your birthday? Oh, and I forgot you hate seafood. Sorry about the fishsticks.”", "related": "Lower as a verb means “look angry, appear threatening.” A person can lower (as in the girlfriend above), or, often, the sky lowers before a storm.", "moreinfo": "", "hook": "glare and lower the brow: stare angrily.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "goad", "pos": "verb", "pron": "GOH’d", "also": "", "d1": "Urge on (as cattle) with a pointed or electrically charged stick; spur on, stimulate, encourage", "sent": "He never forgave his friends for <b>goading</b> him into spray-painting the school with them. While the effect was temporarily hilarious, he lost a scholarship over the incident.", "related": "Prod is a synonym (a “cattle prod” is also a pointed or electrified stick). Cajole, Coax, and Wheedle are all much gentler, meaning “artfully persuade, such as by flattery.”", "moreinfo": "In common language, goad means “to peer-pressure.”", "hook": "a goad prods cattle: urge on, provoke.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "gouge", "pos": "noun, verb", "pron": "GAH-oodge", "also": "", "d1": "Scooping or digging tool, like a chisel, or a hole made with such a tool (noun); cut or scoop out; force out a person’s eye with one’s thumb; swindle, extort money from (verb)", "sent": "I was happy with this new video game console for a day or two, until I saw it advertised all over town for half the price and realized I’d been <b>gouged</b>.\nHe loves gory horror films, where people’s eyes are <b>gouged</b> out and gross stuff like that.", "related": "Rout (dig around, as with a snout; rummage; scoop out or gouge)", "moreinfo": "", "hook": "gouge out: scoop out; or overcharge and swindle.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 7", "setNum": 7, "coll": "Advanced"}, {"w": "graft", "pos": "verb, noun", "pron": "GRAFT", "also": "", "d1": "Insert part of a plant into another plant, where it continues to grow; join living tissue (such as skin) to part of the body where it will continue to live and grow; attach as if by grafting (verb); the part so grafted (as in a graft of skin); the act of acquiring money or other benefits through illegal means, esp. by abusing one’s power (noun)", "sent": "The part of the book describing the financial crisis is good, but the “What You Can Do” section seems <b>grafted</b> on, almost as though written by a different author.\nIt’s not cool for your boss to pressure you into buying Girl Scout cookies from his daughter. If she were selling something larger, we’d call that <b>graft</b>.", "related": "", "moreinfo": "The “skin graft” sense of graft is related to the root “graph,” for a writing or carving tool. This root also appears in graffiti, cartography (mapmaking), epigraph (inscription on a building, statue, etc.), and even cacography (bad spelling or handwriting).", "hook": "graft a branch on; or graft, corrupt money-grabbing.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "grandiloquent", "pos": "adj", "pron": "gran-DILL-oh-kwent", "also": "", "d1": "Relating to lofty speech, esp. to the point of being pompous, overblown, bombastic", "sent": "After memorizing 1,000 vocabulary flashcards for the GRE, Derek couldn’t help but become a little <b>grandiloquent</b>, declaring his desire to “abscond from my familial domicile and satisfy my penchant for erudition.” “You can do that later,” said his mother, “but now it’s your turn to do the dishes.”", "related": "Magniloquent (synonym), Declamatory (pompous, merely oratorical)", "moreinfo": "The root “loq” refers to speech; thus, grandiloquent has the sense of “grand speech.”", "hook": "grand + eloquent: pompous, lofty speech.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "grandstand", "pos": "verb", "pron": "GRAND-stand", "also": "", "d1": "Perform showily in an attempt to impress onlookers", "sent": "I was really passionate about the candidate when he spoke at our school, but now that I think about it, he was just <b>grandstanding</b>. I mean, who could disagree that young people are the future? And doing a cheer for the environment doesn’t actually signify a commitment to change any public policies about it.", "related": "Declaim (speak in an impassioned, pompous, or oratorical manner; give a formal speech)", "moreinfo": "As a noun, a grandstand is essentially “the bleachers,” so to grandstand is to perform as though for bleachers full of onlookers. In a memorable episode of 30 Rock, Queen Latifah’s character, a Senator, grandstands by making animated nonsense speeches in which she just shouts “America” and “the future” and “the troops” so passionately that everyone applauds.", "hook": "play to the grandstand: show off for the crowd.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "grating", "pos": "adj", "pron": "GRAY-ting", "also": "", "d1": "Irritating; harsh or discordant (of a noise); scraping", "sent": "Folding jeans at the mall finally became unbearable when her kindly old supervisor was replaced with a young woman whose <b>grating</b> tone made commands like “Fold faster and then clean up this display!” sound like nails on a chalkboard.", "related": "Rasping is a synonym in all senses—irritating, relating to harsh noise, or scraping, as in “The bottom of the boat rasped the rocky ocean floor.” A person with a sore throat often has a raspy voice.", "moreinfo": "A grate, of course, can also be a frame of bars, such as to secure a window. A cheese grater shreds cheese. A grating voice is kind of like applying a cheese grater to your ears.", "hook": "a grating noise: harsh and irritating.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "grievous", "pos": "adj", "pron": "GREE-vuss", "also": "", "d1": "Causing grief or suffering; very serious, grave; flagrant, outrageous", "sent": "While people certainly do injure themselves on hot stoves, such burns rarely compare to the <b>grievous</b> injuries sustained by people who do not observe safety procedures with twelve-gallon deep fryers.", "related": "Dire (causing suffering or fear; ominous; urgent or desperate, as in “a dire emergency requiring immediate response”)", "moreinfo": "“Grievous bodily harm” is a term in English law. General Grievous is a fictional villain in Star Wars Episode III: Revenge of the Sith.", "hook": "causes grief: very serious, grave.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "grouse", "pos": "verb, noun", "pron": "GRAH-ooss", "also": "", "d1": "Complain or grumble (verb); a reason for complaint (noun)", "sent": "By the end of the trip, everyone was annoyed by Lena’s <b>grousing</b>—the bus ride was too bumpy, the food was too spicy, the air conditioning was too dehydrating, etc….\nDon’t be offended, but I’ve got a <b>grouse</b> about the way you’re handling this project.", "related": "", "moreinfo": "A grouse is also a type of bird, although this usage is of an unrelated origin. The “complain” meaning of grouse comes from the Old French “grouchier” and shares a root with grudge.", "hook": "grouse = grumble: complain.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "grovel", "pos": "verb", "pron": "GRAH-vull", "also": "", "d1": "Creep or crawl with one’s face to the ground, prostrate oneself as a token of subservience, degrade or abase oneself", "sent": "Most of the laid-off employees packed their things and left the building—only one was seen <b>groveling</b>, literally on his knees asking his boss not to fire him and even offering to wash the boss’s car.", "related": "Sycophant, Lackey, Toady, and Myrmidon are all words for a fawning person (colloquially, a “bootlicker”). Truckle means to act subserviently and Kowtow means to fawn—or, literally, to bow until one’s forehead touches the floor. Genuflect also means bow, but often in a courtly way, such as a knight bowing to the king. Memory Trick: When you kneel down to grovel, your knees get all scratched up from being in gravel.", "moreinfo": "", "hook": "grovel on the ground: crawl and abase yourself.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "halcyon", "pos": "adj", "pron": "HAL-see-un", "also": "", "d1": "Calm and peaceful, carefree; prosperous, successful, happy", "sent": "Installing drywall wasn’t the career he’d planned for—every day he reminisced about the <b>halcyon</b> days of his high school football career, when he was treated like a god, and he had not a care in the world other than the next big game.", "related": "Tranquil, Pacific, and Placid also mean peaceful.", "moreinfo": "The halcyon, in classical mythology, was a bird whose nest floated on the sea and who could charm the waves into calmness.", "hook": "\"halcyon days\": calm, peaceful, happy times.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hallmark", "pos": "noun", "pron": "HALL-mark", "also": "", "d1": "A mark of indication of quality, purity, genuineness, etc.; any distinguishing characteristic", "sent": "Signature red soles are the <b>hallmark</b> of Christian Louboutin’s shoes.\nFast-paced rhymes, an angry tenor, and personal attacks on celebrities are <b>hallmarks</b> of Eminem’s music.", "related": "An earmark is also any distinguishing mark, such as a mark on an animal’s ear to show ownership. Earmark can also be a verb meaning “allocate or set aside” (to earmark funds for a project). An earmark is neutral, but a hallmark generally has more positive connotations.", "moreinfo": "The Goldsmiths’ Company of London made gold and silver articles stamped with a mark. The company was located in Goldsmiths’ Hall—thus, a “hall mark.”", "hook": "a hallmark stamp of quality: a defining characteristic.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hand-wringing", "pos": "noun", "pron": "HAND-ring-ing", "also": "", "d1": "Grasping, squeezing, etc. of the hands as an expression of nervousness, guilt, etc.; extend debate over what to do about an issue", "sent": "There has been much <b>hand-wringing</b> (or wringing of hands) over falling test scores, with so- called “experts” acting as if the world will end if students do 1% worse in math and science.", "related": "", "moreinfo": "", "hook": "wringing the hands in worry: anxious fretting.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hapless", "pos": "adj", "pron": "HAP-less", "also": "", "d1": "Unlucky, unfortunate", "sent": "Hiring this <b>hapless</b> new office manager was a mistake—he’s always losing and breaking things, as though bad luck simply follows wherever he goes.", "related": "Bootless (useless), Woebegone (beset with woe—that is, grief or distress)", "moreinfo": "Hap is a very rare old word meaning “luck or lot.”", "hook": "hap (luck) + less: unlucky.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "harangue", "pos": "noun, verb", "pron": "huh-RANG", "also": "", "d1": "Long, intense verbal attack, esp. when delivered publicly", "sent": "Look, I’ll clean the gutters when I get a free weekend—I don’t need you to keep <b>haranguing</b> me about it.", "related": "Tirade, Diatribe, and Fulmination are all words for bitter, angry speeches or attacks. Memory Trick: What do you call a large ape who always yells at you? A harangutan! (That’s the worst joke on all of these flashcards—we promise).", "moreinfo": "", "hook": "a long harangue: a ranting tirade.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "harrow", "pos": "noun, verb", "pron": "HAIR-oh", "also": "harrowing (adj)", "d1": "Farming tool that breaks up soil (noun); painfully disturb or distress (verb)", "sent": "Let’s start our garden together—you <b>harrow</b>, and I’ll follow behind you planting the seeds.\nThe bus ride across Siberia was a <b>harrowing</b> experience—the roads were all ice, and the ancient, barely heated vehicle seemed to be lacking both headlights and brakes.", "related": "", "moreinfo": "Shakespeare may have been the first to use harrow in a metaphorical way (“I could a tale unfold whose lightest word would harrow up thy soul”—Hamlet).", "hook": "a harrow rakes soil; \"harrowing\" distresses painfully.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hedge", "pos": "verb", "pron": "HEDGE", "also": "", "d1": "Avoid commitment by leaving provisions for withdrawal or changing one’s mind; protect a bet by also betting on the other side", "sent": "While he coaxed and cajoled us all into seeing “the best movie ever,” he <b>hedged</b> once we were in the theater: “I don’t know if you all like this sort of thing,” he said. “I mean, you can make up your own minds.”\nWhen the professor called on him to take a stand on the issue, he <b>hedged</b> for fear of offending her: “Well, there are valid points on both sides,” he said.", "related": "Equivocate, Waffle, Vacillate, and Tergiversate (waver, use unclear language to deceive or avoid committing), Ambivalent (unable to decide, or wanting to do two contradictory things at once), Palter (talk insincerely; bargain or haggle)", "moreinfo": "A hedge fund is an investment fund that hedges risk with a variety of methods, such as short selling and derivatives.", "hook": "hedge your bets: avoid commitment, cover both sides.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hegemony", "pos": "noun", "pron": "huh-JEM-uh-nee or HEDGE-uh-moh-nee", "also": "hegemon (noun)", "d1": "Domination, authority; influence by one country over others socially, culturally, economically, etc.", "sent": "The discovery of oil by a previously poor nation disrupted the larger, richer nation’s <b>hegemony</b> in the region—suddenly, the hegemon had a competitor.", "related": "Autonomous (self-governing, independent), Fiat (dictate or authoritative order, as in “The king rules by fiat.”), Sovereignty (supreme power, autonomy)", "moreinfo": "", "hook": "a hegemon leads: one power's domination over others.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hermetic", "pos": "adj", "pron": "her-MET-ick", "also": "", "d1": "Airtight, sealed, isolated; reclusive; pertaining to alchemy, occult", "sent": "These packaged meals are <b>hermetically</b> sealed—they’ll last years in storage, but once opened, you need to finish the contents within a couple of days.\nWhile writing hundreds of vocabulary flashcards, the GRE instructor lived a <b>hermetic</b> lifestyle, her skin growing pallid and her social network drastically shrinking.", "related": "", "moreinfo": "Hermetic comes from Hermes Trismegistus, a Greek/Egyptian god of magic and alchemy; he supposedly invented a magic airtight seal for containers.", "hook": "hermetically sealed: airtight and isolated.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hew", "pos": "verb", "pron": "HYOO", "also": "", "d1": "Strike, chop, or hack (as with an axe, sword. etc.); make or shape something (such as a statue) with a cutting tool", "sent": "The pioneer had to <b>hew</b> his own way through the brush in order to proceed westward.\nShe preferred rustic furniture; her dining room chairs were little more than stumps roughly <b>hewn</b> into stools.", "related": "", "moreinfo": "The past tense of hew is hewn, and the expression roughly hewn (or rough-hewn, or rough hewed) is often used to describe something that seems unfinished or looks as though it was “carved” with a heavy axe rather than more delicate tools. For instance, a manly-man movie star— someone like Russell Crowe—is a more roughly hewn than someone like Zac Efron.", "hook": "hew wood with an axe: chop or shape.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hoary", "pos": "adj", "pron": "HOR-ee", "also": "", "d1": "Very old, gray or white as from old age", "sent": "<b>Hoary</b> with age, his white beard making his age obvious even from the top of the bleachers, the old man surprised everyone when he was able to make a free throw.\nDad, I’ve heard your <b>hoary</b> old college fraternity stories a hundred times.", "related": "Grizzled (graying), Wizened (withered or shriveled, as from age), Antediluvian (very old; literally, from before the Biblical flood)", "moreinfo": "", "hook": "hoar-frost white: very old and gray.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "homage", "pos": "noun", "pron": "HAH-midge", "also": "", "d1": "Honor or respect demonstrated publicly", "sent": "This structure I built in the backyard is not just a skateboard ramp; it is an <b>homage</b> to my hero Tony Hawk. I have dubbed it the “Tony Hawk Rocks Western Pennsylvania Skateboard Ramp.”\nI’m not copying Madonna’s song—I am referencing it in my own song as an <b>homage</b> to her work.", "related": "Tribute (gift, testimonial, etc. as expression of esteem for someone; performance in someone’s honor, etc.; rent, tax, etc. paid by a subject to a lord)", "moreinfo": "Under the feudal system, a vassal was required to pay homage to his lord. The word probably comes from the word for “man” (French homme, Latin “homo”). The French origin is responsible for what is said by some as a silent “h” (hence “an homage”).", "hook": "pay homage: public honor and respect.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hoodwink", "pos": "verb", "pron": "HOOD-wink", "also": "", "d1": "Trick, deceive", "sent": "Pretending to be the building’s landlord, the shyster was able to <b>hoodwink</b> eleven people into paying deposits on a vacant apartment—of course, he absconded with the money, leaving the victims without their money or a place to live.", "related": "Bilk, Swindle, Con, and Fleece are all verbs for cheating others. Dupe means “fool or exploit.” Fleece is perhaps more severe, having the connotation of taking everything from the victim, the way one sheers all of the fleece from a sheep.", "moreinfo": "Hoodwink comes from the idea of covering a person’s eyes with a hood.", "hook": "pull a hood over the eyes: trick and deceive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "hotly", "pos": "adv", "pron": "HOT-lee", "also": "", "d1": "In an intense, fiery, or heated way", "sent": "The issue of how evolution should be taught in schools was <b>hotly</b> disputed by members of the school board, religious leaders, and parent groups.", "related": "Heatedly (synonym)", "moreinfo": "", "hook": "argue hotly: intensely and heatedly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "husband", "pos": "verb", "pron": "HUZZ-buhnd", "also": "", "d1": "Manage prudently, sparingly, or economically; conserve", "sent": "As we are dealing with cutbacks, I am calling on you as the office manager to <b>husband</b> our resources, parceling out office supplies and buying new ones only when absolutely necessary.", "related": "A Steward can be a household manager or a manager of food and drinks, such as on a train or plane; to Steward also means “conserve, use wisely.”", "moreinfo": "“Animal husbandry” is the practice of raising or breeding livestock.", "hook": "husband your resources: manage sparingly, conserve.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "iconoclast", "pos": "noun", "pron": "eye-CAH-noh-clast", "also": "iconoclastic (adj)", "d1": "Attacker of cherished beliefs or institutions", "sent": "A lifelong <b>iconoclast</b>, Ayn Rand wrote a controversial book entitled The Virtue of Selfishness.", "related": "Maverick (lone dissenter, person who takes an independent stand), Heterodox (unorthodox)", "moreinfo": "The original iconoclasts were Eastern Orthodox or Protestant Christians who opposed the Catholic use of icons in worship. In extreme cases, they would physically smash icons in churches.", "hook": "icon + clast (break): a smasher of cherished beliefs.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "idolatry", "pos": "noun", "pron": "eye-DOLL-uh-tree", "also": "", "d1": "Idol worship; excessive or unthinking devotion or adoration", "sent": "After a year in an education Ph.D. program, she’d had enough with the <b>idolatry</b> of Howard Gardner and his theory of multiple intelligences—“Gardner isn’t a god,” she would say, “and you simply can’t learn calculus through movement or interpersonal skills.”", "related": "Veneration and Reverence refer to deep admiration and respect. Apotheosis is deification, the process of making someone into or like a god. Lionization is treating someone as a celebrity.", "moreinfo": "An idol (forbidden in many religions) is a representation of an object of worship.", "hook": "idol + latry (worship): idol worship, blind devotion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "idyllic", "pos": "adj", "pron": "eye-DILL-ick", "also": "idyll (noun)", "d1": "Presenting a positive, peaceful view of rural life (as poetry or prose); pleasant in a natural, simple way", "sent": "An action-packed vacation wasn’t their style—for their honeymoon, they enjoyed a quiet idyll in a cabin in the woods, just watching the deer and enjoying nature.", "related": "Bucolic, Pastoral, Georgic, and Arcadian are all words relating to a positive view of rural life and songs or poems on that theme.", "moreinfo": "As a noun, an idyll can be a poem on an idyllic theme, or a carefree or romantic span of time, such as one spent in peaceful nature.", "hook": "an idyllic scene: a peaceful, perfect rural picture.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 8", "setNum": 8, "coll": "Advanced"}, {"w": "ignoble", "pos": "adj", "pron": "ig-NOH-bull", "also": "", "d1": "Not noble; having mean, base, low motives; low quality", "sent": "What you have done may not be illegal, but it surely is <b>ignoble</b>—people who don’t read the user agreement surely do not expect that, by clicking “I Agree,” they have signed up for a Jelly of the Month club!", "related": "Ignominious (disgraceful, humiliating, contemptible)", "moreinfo": "The Latin “ig” is simply a variation on “in,” meaning “not.”", "hook": "i (not) + noble: base, low, dishonorable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "imbue", "pos": "verb", "pron": "im-BYOO", "also": "", "d1": "Permeate or saturate, as dye in a fabric; influence throughout", "sent": "After shearing the sheep and spinning the yarn, the next step is to <b>imbue</b> the yarn with dye.\nHis poems are <b>imbued</b> with a sense of longing for a lost homeland.", "related": "Infuse, Suffuse, and Pervade also mean “spread throughout.” Inculcate means to teach persistently, implant (an idea) in a person, as in “to inculcate morals in children.”", "moreinfo": "", "hook": "imbue with color or values: saturate and permeate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "immutable", "pos": "adj", "pron": "im-MYOO-tuh-bull", "also": "", "d1": "Unchangeable", "sent": "Studies of the brains of stroke patients have shown that our identities are not fixed and <b>immutable</b>; rather, physical injuries to the brain can drastically change our personalities.", "related": "Immalleable (not moldable or adaptable)", "moreinfo": "Immutable shares a root (meaning “change”) with mutation and transmute.", "hook": "im (not) + mutable: unchangeable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impasse", "pos": "noun", "pron": "IM-pass", "also": "", "d1": "Position or road from which there is no escape; deadlock", "sent": "If the union won’t budge on its demands and the transit authority won’t raise salaries, then we are at an <b>impasse</b>.", "related": "Standstill, gridlock, logjam, stalemate, standoff, and standstill are all words for being stuck due to different people’s opposing goals. Not surprisingly, all of these words are common in politics.", "moreinfo": "A physical impasse—a road that hits a dead end—can be called a cul-de-sac.", "hook": "im (not) + passe (pass): a deadlock with no way through.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impassive", "pos": "adj", "pron": "im-PASS-iv", "also": "", "d1": "Not having or not showing physical feeling or emotion", "sent": "Having been in and out of hospitals all his life, he accepted this latest diagnosis <b>impassively</b> —“Whatever happens, happens,” he said.", "related": "Stoic (not having or showing feeling, esp. in response to suffering), Inscrutable (not able to be scrutinized, mysterious).", "moreinfo": "Note that impassive is NOT the antonym of passive, which means “inactive, not reacting.”", "hook": "im (not) + passion: showing no emotion, blank.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impecunious", "pos": "adj", "pron": "im-peck-YOO-nee-uss", "also": "", "d1": "Poor, without money", "sent": "Having grown up with <b>impecunious</b> parents who could barely keep the electricity on in the house, she was now obsessed with wealth and security.", "related": "Penurious (poor or stingy), Indigent (destitute), Insolvent (unable to meet one’s financial obligations, bankrupt)", "moreinfo": "“Pecunia” is Latin for money and also appears in pecuniary, “relating to money.”", "hook": "im (not) + pecunia (money): penniless.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "imperious", "pos": "adj", "pron": "im-PEER-ee-uss", "also": "", "d1": "Commanding, domineering; acting like a high ranking person; urgent", "sent": "Her friend were peeved by her <b>imperious</b> attitude and talked about her while she was in the ladies’ room: “Who does she think she is, not only picking the bar and the meeting time but also telling us where to sit?”", "related": "Overbearing is a synonym. Autocratic refers to absolute rule and Despotic and Tyrannical refer to the abuse of absolute rule.", "moreinfo": "The related imperial means “pertaining to an empire or emperor.” Imperious behavior can be appropriate when practiced by an emperor, but generally, imperious just means arrogant and bossy.", "hook": "imperial and bossy: commanding, domineering.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impermeable", "pos": "adj", "pron": "im-PER-mee-uh-bull", "also": "permeable (adj)", "d1": "Impassable, not allowing passage through (such as by a liquid)", "sent": "A good raincoat is totally <b>impermeable</b> to water.", "related": "Impervious (impenetrable, not able to be harmed or emotionally disturbed, as in “impervious to criticism”)", "moreinfo": "Impermeable contain the roots “in/im” (not) and “per” (through).", "hook": "im (not) + permeable: lets nothing pass through.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "imperturbable", "pos": "adj", "pron": "im-per-TER-buh-bull", "also": "", "d1": "Calm, not able to be upset or agitated", "sent": "Having seen pretty much everything, the kindergarten teacher was truly <b>imperturbable</b>: a morning containing a discipline problem, two bathroom accidents, one fight, and one temper tantrum didn’t bother her in the least.", "related": "Impervious (impenetrable, not able to be harmed or emotionally disturbed, as in “impervious to criticism”), Stoic (not having or showing feeling, esp. in response to suffering)", "moreinfo": "Of course, a person who can be upset is perturbable and has been perturbed. Perturb contains a root from the Latin “turbare” (to disturb); this root also appears in turbulence and turbid (muddy and choppy, as a turbulent body of water).", "hook": "im (not) + perturb: calm and unflappable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impervious", "pos": "adj", "pron": "im-PER-vee-uss", "also": "", "d1": "Impenetrable, not able to be harmed or emotionally disturbed", "sent": "The problem with arrogant people is that they are <b>impervious</b> to criticism of their arrogance; anything you say to them just rolls right off.", "related": "Impermeable (impassable, not allowing passage through), Stoic (not having or showing feeling, esp. in response to suffering)", "moreinfo": "Impervious contains the roots “in/im” (not), “per” (through), and “via” (road).", "hook": "im (not) + pervious: impenetrable, unaffected.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impetuous", "pos": "adj", "pron": "im-PET-choo-uss", "also": "", "d1": "Passionately impulsive, marked by sudden, hasty emotion; forceful, violent", "sent": "Reflecting on her most recent breakup, Heather decided that next time she would like to date someone less <b>impetuous</b>; a man who quits his job on a whim and suggests moving together to Utah and raising llamas was just a little too impulsive for her tastes.", "related": "Rash (hasty, lacking forethought or caution)", "moreinfo": "Impetuous is related to impetus, a moving force, motivation, or stimulus.", "hook": "driven by impetus: rashly impulsive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impious", "pos": "adj", "pron": "im-PIE-uss", "also": "pious (adj), piety (noun)", "d1": "Not religious, lacking reverence, ungodly", "sent": "In religious schools, <b>impious</b> behavior is generally prohibited.", "related": "Irreverent (synonym), Sacrilegious (violating what is sacred) Blasphemous (impious behavior, esp. speech)", "moreinfo": "Pious (reverent) shares a root with expiate (to atone, ask to be forgiven of one’s sins).", "hook": "im (not) + pious: irreverent, ungodly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "implacable", "pos": "adj", "pron": "im-PLACK-uh-bull", "also": "placate (verb), placatory (adj)", "d1": "Not able to be appeased, calmed, or satisfied", "sent": "After the dog groomer misunderstood and shaved the family Weimaraner totally bald, Mr. Garcia was <b>implacable</b>; neither an offer of a free gift certificate nor a complimentary doggie sweater would reduce his fury.", "related": "Inexorable (unyielding, merciless, not moved by pleas)", "moreinfo": "Implacable means “not able to be placated.” Someone who can be placated is placatory.", "hook": "im (not) + placate: can't be appeased or calmed.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "imprecation", "pos": "noun", "pron": "im-preck-AY-shun", "also": "", "d1": "Curse; prayer for harm to come to someone", "sent": "The haunted house features a ”wicked witch” chanting <b>imprecations</b> at all who pass through.", "related": "Malediction (synonym)", "moreinfo": "Imprecation proceeds from the Latin “precari” (pray). As a verb, imprecate means to curse or call down evil upon.", "hook": "im + precari (pray): a curse, praying harm on someone.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impugn", "pos": "verb", "pron": "im-PYOON", "also": "", "d1": "Attack the truth or integrity of", "sent": "I hate to <b>impugn</b> the motives of the volunteers, but I think that some of them are here for personal gain, not to help.", "related": "Slander, Traduce, and Defame all mean “to speak maliciously and falsely of.” (Impugning, in contrast, can sometimes help to uncover the truth).", "moreinfo": "Impugn comes from the Latin “pugnare” (to fight), which also gives us pugnacious (combative, belligerent).", "hook": "im + pugn (fight): attack the truth of, challenge.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "impute", "pos": "verb", "pron": "im-PYOOT", "also": "", "d1": "Credit, attribute; lay blame or responsibility for (sometimes falsely)", "sent": "The ineffectual CEO was nevertheless a master of public relations—he made sure that all successes were <b>imputed</b> to him, and all of the failures were <b>imputed</b> to others.", "related": "", "moreinfo": "Impute proceeds from the Latin “putare” (consider), which also gives us putative (supposed, assumed).", "hook": "impute to: attribute or pin blame on.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "incarnadine", "pos": "adj, noun", "pron": "in-CAR-nuh-dine or in-CAR-nuh-deen", "also": "", "d1": "Blood red or flesh-colored", "sent": "The police took the body to the morgue; all that was left at the murder scene was an <b>incarnadine</b> stain on a pillow.", "related": "Vermilion means bright red or reddish-orange; the word comes from the Latin for “little worm,” specifically the insect used for the dye.", "moreinfo": "Incarnadine shares a root (meaning “flesh”) with carnal, carnage, and incarnate. Don’t confuse with Incarnate (embodied, personified; put into concrete form, embody, take on a human body).", "hook": "carne (flesh) red: blood-red.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "inconstancy", "pos": "noun", "pron": "in-CAHN-stun-see", "also": "", "d1": "Fickleness, unreliability; the state of changing without good reason", "sent": "Old-fashioned poems often praised a lover’s constancy; the poet would likely be shocked by any <b>inconstancy</b> from his lady, such as if she were receiving poems from other poets.", "related": "Continent (characterized by restraint)", "moreinfo": "", "hook": "in (not) + constant: fickleness, unreliability.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "inculcate", "pos": "verb", "pron": "in-CULL-cayt or IN-cull-cayt", "also": "", "d1": "Teach persistently, implant (an idea) in a person", "sent": "Parents spend years trying to <b>inculcate</b> morality in their children, constantly teaching and correcting them.", "related": "", "moreinfo": "Inculcate comes from a Latin word for “tread,” which itself comes from a word for “heel.” Imagine actually stomping morals into your children!", "hook": "stamp it in with the heel: drill an idea in.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "indefatigable", "pos": "adj", "pron": "in-deh-FAT-ig-uh-bull", "also": "defatigate (verb)", "d1": "Untiring, not able to become fatigued", "sent": "The boxer was <b>indefatigable</b>; round after round, he never lost speed or energy, even after he had thoroughly defatigated his opponent.", "related": "Unflagging (tireless), Insuperable and Indomitable (not able to be defeated)", "moreinfo": "The root word in indefatigable is fatigue, of course. To defatigate is to make tired.", "hook": "in (not) + fatigue: tireless.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "indigence", "pos": "noun", "pron": "IN-dih-jenss", "also": "indigent (adj)", "d1": "Extreme poverty", "sent": "The city government has several agencies that provide shelter, food, and other assistance to the indigent.", "related": "Impecunious (poor, without money), Penurious (poor or stingy), Indigent (destitute), Insolvent (unable to meet one’s financial obligations, bankrupt)", "moreinfo": "Don’t confuse with indignant (offended, angry at injustice).", "hook": "an indigent's state: extreme poverty.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "indolent", "pos": "adj", "pron": "IN-duh-lent", "also": "", "d1": "Lazy, slothful", "sent": "Having worked all his life, the CEO was constantly frustrated with his <b>indolent</b> son, who used his inherited wealth as an excuse to sunbathe and party.", "related": "Torpid, sluggish, idle, lethargic, loafing, and slack are all related to laziness or slowness.", "moreinfo": "The Latin “dolere” means “suffer pain”—today, dolor means anguish or grief. Indolent arose from the idea of avoiding pain and now means laziness.", "hook": "in (not) + working: lazy and idle.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "inert", "pos": "adj", "pron": "in-ERT", "also": "", "d1": "Inactive; having little or no power to move", "sent": "“All of the missiles at the military museum are <b>inert</b>, Timmy,” said the tour guide, answering the question children always asked. “They’re not going to blow up.”\nWhen she saw her father’s <b>inert</b> body on the floor, she thought the worst, but fortunately he was just practicing very slow yoga.", "related": "Latent, Dormant (not active at this time)", "moreinfo": "", "hook": "an inert gas does not react: inactive, motionless.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "inexorable", "pos": "adj", "pron": "in-ECK-ser-uh-bull", "also": "", "d1": "Relentless, unyielding; not moved by pleading", "sent": "Many people fled Europe in the face of Hitler’s <b>inexorable</b> march across the continent.", "related": "Unflagging and Indefatigable (tireless), Insuperable and Indomitable (not able to be defeated)", "moreinfo": "Inexorable shares a root (“orare,” meaning “pray”) with orator (now a public speaker, but originally a worship leader). The sense here is that an inexorable force is pitiless and unmoved by prayers.", "hook": "can't be begged off: relentless, unstoppable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "infallible", "pos": "adj", "pron": "in-FAL-ih-bull", "also": "fallible (adj), fallacious (adj)", "d1": "Incapable of error; certain", "sent": "No good scientist thinks he or she is <b>infallible</b>—it is fundamental to the scientific method that every theory is open to revision based on new evidence.", "related": "Unerring (synonym)", "moreinfo": "L’Oreal has released a new line of lipstick called Infallible, which implies that the lipstick is immune from being logically incorrect. A better name might have been something like “Flawless.”", "hook": "in (not) + fallible: incapable of error.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 9", "setNum": 9, "coll": "Advanced"}, {"w": "ingrate", "pos": "noun", "pron": "IN-grayt", "also": "", "d1": "Ungrateful person", "sent": "You <b>ingrate</b>! I have slaved at this laundromat to pay for your college education, and you quit two weeks before graduation to become a Marxist revolutionary, and then you tell me I’m the enemy of the working class?", "related": "", "moreinfo": "The “grate” in ingrate is of course related to grateful, but also grace and ingratiate (gain favor with, as by flattery).", "hook": "in (not) + grate (grateful): an ungrateful person.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "ingratiate", "pos": "verb", "pron": "in-GRAY-shee-ayt", "also": "", "d1": "Make an effort to gain favor with", "sent": "Ryan’s attempts to <b>ingratiate</b> himself with the boss were quite transparent—no one really believes that a 25 year old loves the same cigars, classic rock, and AARP crosswords as the 65 year old company president.", "related": "Fawn (show affection or try to please in the manner of a dog; try to win favor through flattery and submissive behavior), Sycophant, Lackey, Toady, and Myrmidon are all words for a person who fawns.", "moreinfo": "The Latin root “gratia” means grace; ingratiate has the sense of the modern expression “to get into someone’s good graces.”", "hook": "in + gratia (favor): worm into someone's good graces.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inimical", "pos": "adj", "pron": "in-IM-ick-ull", "also": "", "d1": "Hostile, adverse, harmful", "sent": "Most people think that being shouted at in the freezing rain is <b>inimical</b> to learning; sadly, our boot camp instructor disagreed.", "related": "Conducive is an antonym and is also used with the word “to.” Loud noise is inimical to studying, and a quiet environment is conducive to studying.", "moreinfo": "", "hook": "an enemy (inimicus): hostile and harmful.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "iniquity", "pos": "noun", "pron": "in-ICK-wit-ee", "also": "", "d1": "Injustice, wickedness, sin", "sent": "The preacher’s sermon about loving your neighbor was regarded by some as a welcome departure from his usual fiery homilies railing against <b>iniquity</b>.\nIniquitous corporations, such as those that spill oil into our oceans, must be punished.", "related": "Peccadillo (small sin or fault)", "moreinfo": "Don’t confuse with inequity, meaning “lack of equality, unfairness.”", "hook": "in (not) + equity (fairness): wickedness, injustice.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inordinate", "pos": "adj", "pron": "in-OR-din-it", "also": "", "d1": "Excessive, not within proper limits, unrestrained", "sent": "Students taking online GRE practice tests at home often take an <b>inordinate</b> number of breaks —remember, on the real thing, you can’t stop just because you’re tired or hungry.", "related": "Gratuitous (free; without cause or justification)", "moreinfo": "Inordinate contains a root for “order” and thus has the sense of “not orderly.”", "hook": "in (not) + ordinate (ordered): excessive, beyond limits.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inquest", "pos": "noun", "pron": "IN-kwest", "also": "", "d1": "Legal or judicial inquiry, especially before a jury and especially made by a coroner into the cause of someone’s death; the results of such an inquiry", "sent": "The family waited nervously for the results of the <b>inquest</b>, which finally returned a verdict of misadventure; that is, their grandfather had not been murdered, but rather died in a freak accident of his own doing.", "related": "", "moreinfo": "Inquest is simply a form of the Latin word for “inquire.”", "hook": "in + quest: a legal inquiry, often into a death.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "insensible", "pos": "adj", "pron": "in-SEN-sih-bull", "also": "", "d1": "Incapable of feeling; unconscious, unaware", "sent": "Very intoxicated people can be <b>insensible</b> to pain, leading to serious problems as they injure themselves and don’t realize it.\nI cannot believe that, while I was <b>insensible</b> after the operation, you put funny hats on me and took pictures! You are <b>insensible</b> to shame!", "related": "Insensate (inanimate, as an object; without sense or human feeling, cruel)", "moreinfo": "", "hook": "in (not) + sensible (feeling): unconscious or unfeeling.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "insinuate", "pos": "verb", "pron": "in-SIN-yoo-ayt", "also": "", "d1": "Hint, suggest slyly; introduce (an idea) into someone’s mind in a subtle, artful way", "sent": "“Where’s your boyfriend? You didn’t leave him home alone, did you?” asked Ming. “Are you <b>insinuating</b> something?” asked Helen. “If you have something to say, just say it.”", "related": "Implicit and Tacit (implied, unspoken)", "moreinfo": "Insinuate contains a root for “a curve, winding” that also exists in sinew and sinus. Insinuate can also mean to introduce yourself (rather than an idea) in a stealthy, covert way, as in “By researching where the bosses would be and what kinds of things they liked to talk about, Fitz was able to insinuate himself into the company’s leadership.”", "hook": "slip an idea in sinuously: hint slyly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "insipid", "pos": "adj", "pron": "in-SIP-id", "also": "", "d1": "Dull, stale, lacking taste or interest", "sent": "This is a university level poetry class, and your <b>insipid</b> drivel just won’t cut it here. “Things that are bad always make me sad”? Really?\nThe restaurant critic called the dish “<b>insipid</b>”—I did think it was bland, but I probably would’ve been more polite about it.", "related": "Banal, Hackneyed, Inane, Insipid and Trite all mean “lacking freshness and originality, shallow.”", "moreinfo": "The rare antonym sipid and the variant sapid mean “tasty, agreeably distinct.” The root “sapere” (having taste) also means “be wise” and appears in sage and sapient, which both mean wise.", "hook": "in (not) + sapid (tasty): dull and flavorless.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "insular", "pos": "adj", "pron": "IN-sull-er or IN-syoo-ler", "also": "", "d1": "Pertaining to an island; detached, standing alone; narrow-minded, provincial", "sent": "The young actress couldn’t wait to escape the <b>insularity</b> of her small town, where life revolved around high school football and Taco Bell was considered exotic international cuisine.", "related": "Xenophobia (fear of foreigners), Illiberality (narrow-mindedness, lack of generosity)", "moreinfo": "Word origins sometimes contain biases or old-fashioned ideas—for instance, the implication that people on islands are narrow-minded. A similar bias is implied in provincial and parochial (pertaining to a province or parish, respectively)—the idea is that people from “out there in the country” are not as sophisticated as city people, who have their own word, urbane (cosmopolitan, refined).", "hook": "insula = island: isolated, narrow-minded.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "insurrection", "pos": "noun", "pron": "in-ser-ECK-shun", "also": "", "d1": "Rebellion or revolt against a government or similarly established authority", "sent": "Due to frequent <b>insurrections</b>, the nation has had six governments in just five years.\nThe principal prepared for <b>insurrection</b> as she announced that all teachers were to spend the rest of the year exclusively preparing for standardized tests.", "related": "Junta (small group ruling a country, esp. after a revolution), Cabal (a conspiratorial group), Sedition (incitement of dissent against a government; promoting rebellion by speech or writing)", "moreinfo": "Insurrection contains the root “surge” (rise up), also appearing in resurgence and insurgent (one who participates in an insurrection).", "hook": "to rise up against: a rebellion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inter", "pos": "verb", "pron": "in-TER", "also": "", "d1": "Bury (a dead body) or place in a tomb", "sent": "After the funeral, the body will be <b>interred</b> in the cemetery.\nOccasionally, a criminal investigation requires disinterring, or exhuming, a body for autopsy; this can be upsetting to family members who have already buried their loved one.", "related": "", "moreinfo": "Inter comes from “in” and “terra” (earth)—thus simply “to place in the earth.” The root for earth also appears in terrestrial, terrarium, terrace, territory, Mediterranean, and extra- terrestrial.", "hook": "put \"in the earth\": bury (opposite of exhume).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "interplay", "pos": "noun", "pron": "IN-ter-play", "also": "", "d1": "Interaction, reciprocal relationship or influence", "sent": "Bilingual readers will enjoy the <b>interplay</b> of English and Spanish in many of the poems in this anthology of the work of Mexican-American poets.", "related": "Converge (move towards one another or towards a point; unite), Dovetail (join or fit together)", "moreinfo": "", "hook": "inter + play: interaction, give and take.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "interregnum", "pos": "noun", "pron": "in-ter-REG-num", "also": "", "d1": "A time in between two reigns or regimes during which there is no ruler; a period during which government does not function; any period of freedom from authority or break or interruption in a series", "sent": "When the king died with no heir, his ministers ruled in the <b>interregnum</b> as the nobles argued over which of the king’s nephews should rule next.\nIn the <b>interregnum</b> between Madonna and Lady Gaga, there was no single female pop star who commanded such titanic audiences.", "related": "Interrex (person holding supreme authority during an interregnum), Hiatus (break or gap in an activity), Abeyance (temporary suspension, inactivity)", "moreinfo": "The Latin root “reg” (kingship, rule) also occurs in regal, regulate, regime, regiment, regicide (killing a king), and regale (entertain, amuse).", "hook": "inter (between) + regnum (reign): a gap between rulers.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "intransigent", "pos": "adj", "pron": "in-TRAN-zih-jent", "also": "", "d1": "Refusing to compromise, inflexible, having extreme attitudes", "sent": "“Even three detentions and a note home to your parents haven’t convinced you to behave yourself in class!” the teacher said to the <b>intransigent</b> child.", "related": "Intractable, Obdurate, and Obstreperous are also used to describe people who are stubborn and hard to control.", "moreinfo": "Intransigent shares a root with transaction—as in, intransigent people will not likely agree to a reasonable transaction.", "hook": "won't compromise: refusing to budge.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inundate", "pos": "verb", "pron": "IN-un-dayt", "also": "", "d1": "Flood, cover with water, overwhelm", "sent": "As the city was <b>inundated</b> with water, the mayor feared that many evacuees would have nowhere to go.\nI can’t go out—I am <b>inundated</b> with homework!", "related": "Deluge means to flood, or a flood itself, and is used metaphorically in the same way as inundate (deluged with work, a deluge of complaints). Engulf means “flow over and enclose, swallow up or submerge.” A storm engulfing an island would be even more severe than a storm inundating or deluging it.", "moreinfo": "", "hook": "in + unda (wave): flood and overwhelm.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inure", "pos": "verb", "pron": "in-YOOR", "also": "", "d1": "Toughen up; accustom or habituate to pain, hardship, etc.", "sent": "Having had over a dozen surgeries before she was ten, spending months at a time in the hospital, she considered herself <b>inured</b> to pain and disappointment.", "related": "Stoic (not having or showing feeling, esp. in response to suffering), Hardy (bold, brave, capable of withstanding hardship, fatigue, cold, etc.), Fortitude (strength in facing adversity), Grit (firmness of mind, esp. during hardship; courage)", "moreinfo": "", "hook": "wear you in: toughen, habituate to hardship.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "invective", "pos": "noun", "pron": "in-VECK-tiv", "also": "", "d1": "Violent denunciation; accusations, insults, or verbal abuse", "sent": "Although the money was good, she quit her job after nearly having a nervous breakdown from her boss’s <b>invective</b>.", "related": "Vituperation (synonym), Censure (strong disapproval or official reprimand), Contumely (contemptuous treatment or a humiliating insult), Vitriol (very caustic criticism)", "moreinfo": "Invective comes from a root for attack that also gives us inveigh (to protest strongly or attack with words).", "hook": "a verbal invasion: abusive language.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "inveigle", "pos": "verb", "pron": "in-VAY-gull", "also": "", "d1": "Entice, lure; get something by flattery, cleverness, or offering incentives", "sent": "After Mrs. Kim found out that her son’s friends had <b>inveigled</b> him into doing something stupid, she gave him a lecture on standing up to peer pressure.", "related": "Coax and cajole are gentler versions—trying to get someone to do something through persuasion or flattery.", "moreinfo": "Don’t confuse with inveigh (to protest strongly or attack with words).", "hook": "in + beguile: lure by flattery.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "investiture", "pos": "noun", "pron": "in-VEST-it-choor or in-VEST-it-cher", "also": "", "d1": "Investing; formally giving someone a right or title", "sent": "The former dean had her academic robes dry cleaned in preparation for her <b>investiture</b> as university president.", "related": "Divest (deprive or strip of a rank, title, etc., or of clothing or gear; to sell off holdings)", "moreinfo": "", "hook": "invest with a title: a formal installation in office.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "invidious", "pos": "adj", "pron": "in-VID-ee-uss", "also": "", "d1": "Hateful, offensive, injurious", "sent": "School bullying has become a serious problem, with ongoing <b>invidious</b> behavior driving students to suicide.", "related": "Malicious and Malevolent both mean “intending ill will towards another.”", "moreinfo": "Invidious comes from the Latin word for envy. Don’t confuse invidious with insidious, which means deceitful, tricky, intended to entrap or ensnare.", "hook": "invites envy and ill will: hateful, offensive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "irascible", "pos": "adj", "pron": "ih-RASS-uh-bull or eye-RASS-uh-bull", "also": "", "d1": "Irritable, easily angered", "sent": "“I spent my entire childhood tiptoeing around so as not to anger my <b>irascible</b> mother,” Joe told his therapist.", "related": "Dyspeptic (grumpy, pessimistic, irritable), Curmudgeon (bad-tempered, difficult person), Crotchety (grouchy, picky, given to odd notions), Cantankerous (disagreeable, contentious)", "moreinfo": "Irascible shares a root with irate (angry) and ire (anger).", "hook": "ira (anger) + scible: quick to anger.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "irresolute", "pos": "adj", "pron": "ih-REZ-uh-loot", "also": "resolute (adj)", "d1": "Wavering, not sure how to proceed, not firm in one’s decision-making", "sent": "If we were voting on the bill this moment, we’d have enough votes to pass it. But many of our supporters are <b>irresolute</b>—we’re worried that when lobbyists get to them, they’ll quickly change their minds.", "related": "Ambivalent (uncertain; unable to decide, or wanting to do two contradictory things at once), Equivocal (allowing for several different meanings; undecided or having mixed feelings)", "moreinfo": "Resolute or resolved means “decided; firm in purpose.” A resolution can be a mutual agreement or a solution to a problem.", "hook": "ir (not) + resolute: wavering, indecisive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "itinerant", "pos": "adj", "pron": "eye-TIN-uh-ruhnt or it-TIN-uh-ruhnt", "also": "", "d1": "Traveling from place to place, esp. as part of a job", "sent": "In rural areas in the 1940s, it was common that a small town would lack its own doctor, instead being seen by an <b>itinerant</b> family physician who made rounds to many such towns.", "related": "Peripatetic and wayfaring are synonyms. Transient also means moving around, but is more associated with homeless people or those on the fringe of society.", "moreinfo": "Itinerant shares a root with itinerary, a travel schedule.", "hook": "always on an itinerary: roaming from place to place.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "itinerary", "pos": "noun", "pron": "eye-TIN-uh-rare-ee or it-TIN-uh-rare-ee", "also": "", "d1": "Travel schedule; detailed plan for a journey", "sent": "Great, that was the Parthenon! What’s next on our <b>itinerary</b>?", "related": "Agenda is a similar but more general word that can be used metaphorically—a meeting usually has an agenda, a trip could have an agenda (goal or plan) for the day, and a person who wants something but isn’t being direct about it is said to have an agenda or hidden agenda.", "moreinfo": "Itinerary shares a root with itinerant (traveling from place to place, esp. as part of a job). An itinerary can sometimes be a guidebook or a record of travel that has already happened.", "hook": "your travel itinerary: a trip schedule.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 10", "setNum": 10, "coll": "Advanced"}, {"w": "jettison", "pos": "verb", "pron": "JET-iss-un", "also": "", "d1": "Discard, cast off; throw items overboard in order to lighten a ship in an emergency", "sent": "We got so tired while hiking the Appalachian Trail that we <b>jettisoned</b> some of our fancy camping supplies just so we could drag ourselves to a place where we could get medical attention.", "related": "Cargo jettisoned off a ship is called jetsam. Any bunch of discarded, worthless stuff can be called flotsam and jetsam.", "moreinfo": "Jettison comes from a root for “throw” that also gives us jetty, “a wharf, pier, or other structure that juts out into the water.”", "hook": "jettison the cargo: throw overboard, discard.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "jingoism", "pos": "noun", "pron": "JING-go-izm", "also": "jingoist (noun)", "d1": "Excessive, loud patriotism and aggressive, warlike foreign policy", "sent": "He is such a jingoist that he’s always yelling at the TV, calling even the most conservative commentators “wimps” for failing to suggest that we simply nuke, burn, pillage, and otherwise extirpate our so-called “enemies.”", "related": "Hawkish (advocating war), Chauvinism (fanatical patriotism or blind enthusiasm for military glory; undue or biased devotion to any group, cause, etc.)", "moreinfo": "The opposite of a jingoist is a pacifist (someone opposed to war) or possibly a cosmopolite (someone who considers him or herself a citizen of the entire world).", "hook": "flag-waving war-lust: aggressive patriotism.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "juxtapose", "pos": "verb", "pron": "juck-stuh-POHZ", "also": "juxtaposition (noun)", "d1": "Place side-by-side (either physically or in a metaphorical way, such as to make a comparison)", "sent": "Making a decision between two engagement rings from two different stores was difficult, he noted—it would be much easier if he could <b>juxtapose</b> them and compare them directly.", "related": "Abreast (side-by-side; metaphorically, “up to date with,” as in “keeping abreast of the news”), Abut (touch, border on, end at, as in Their house abuts my property).", "moreinfo": "", "hook": "juxta (next to) + pose: place side by side.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "kindle", "pos": "verb", "pron": "KIN-dull", "also": "", "d1": "Ignite, cause to begin burning; incite, arouse, inflame", "sent": "It’s hard to <b>kindle</b> a campfire when it’s so damp out.\nAlthough they were apart, the lovers’ passion was only further <b>kindled</b> by the love letters they wrote to one another.", "related": "Incendiary (starting fire; inflaming the senses or arousing rebellion)", "moreinfo": "Kindling, also called tinder, is material for lighting a fire (such as twigs or straw). Amazon’s Kindle e-book reader is probably so called because it (in theory) ignites a love of reading or knowledge.", "hook": "kindle a fire: ignite, arouse.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "kinetic", "pos": "adj", "pron": "kin-ET-ick", "also": "", "d1": "Pertaining to motion", "sent": "Marisa told her mother what she had learned in science class: a ball sitting on a table has potential energy, but a ball falling towards the ground has <b>kinetic</b> energy.", "related": "", "moreinfo": "Kinetic contains a root for motion that appears in many other words that you don’t need to memorize, but now can easily puzzle out—kinesthetic learners prefer to learn through physical activity. Patients with dyskenesia have trouble with movement. You could major in kinesiology in preparation for being a coach or gym teacher.", "hook": "kinetic energy: of motion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "knell", "pos": "noun, verb", "pron": "NELL", "also": "", "d1": "The sound made by a bell for a funeral, or any sad sound or signal of a failure, death, ending, etc. (noun); to make such a sound (verb)", "sent": "The Senate minority leader’s speech was a death <b>knell</b> for the bill; all hope of bipartisan cooperation was lost.", "related": "Dirge (A funeral or mourning song or poem), Requiem (musical service or hymn for the dead), Threnody (poem or song of mourning), Elegy (song or poem of sorrow, esp. for a deceased person)", "moreinfo": "Don’t confuse knell with knoll, a small hill (as in the “grassy knoll” supposedly involved in JFK’s assassination).", "hook": "the death knell tolls: a mournful bell or omen of the end.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lachrymose", "pos": "adj", "pron": "LACK-ruh-mohss", "also": "", "d1": "Tearful, mournful", "sent": "Accustomed to <b>lachrymose</b> occasions, the funeral home kept boxes of tissues near every seat.", "related": "Maudlin (overly tearful and sentimental), Lament (express sorrow, mourn)", "moreinfo": "Interestingly, lacrimation is the medical condition of making too many tears.", "hook": "full of lachrymal tears: tearful, weepy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "larceny", "pos": "noun", "pron": "LAR-sen-ee", "also": "", "d1": "Theft", "sent": "The department store employs a security officer whose job it is to prevent <b>larceny</b>.", "related": "To purloin is to steal. To pilfer or filch is also to steal, but generally of something small (I filched these awesome coffee mugs from the local diner).", "moreinfo": "In legal terms, larceny refers to a particular type of theft—the thief must physically carry away the stolen item. No one but lawyers cares about this distinction.", "hook": "grand larceny: theft.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "largess or largesse", "pos": "noun", "pron": "lar-ZHESS or lar-JESS", "also": "", "d1": "Generosity, the giving of money or gifts (esp. with the implication that the giver is a bit superior to the recipient)", "sent": "While I did attend a tony private school, my parents were actually quite poor—I was at that school through the <b>largesse</b> of my grandfather.", "related": "Magnanimity, munificence, and openhandedness all mean generosity.", "moreinfo": "Largesse certainly does come from the idea of largeness (of spirit). The word is from French (thus the extra “e” in some spellings).", "hook": "giving largely: generous handouts.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "latent", "pos": "adj", "pron": "LAY-tent", "also": "", "d1": "Potential; existing but not visible or active", "sent": "Certain experts believe that some people have a genetic propensity for addiction; however, if such a person never comes into contact with drugs, the propensity for addiction can remain <b>latent</b> for life.", "related": "Dormant (not active at this time), Inert (inactive; having little or no power to move), Hiatus (break or gap in an activity)", "moreinfo": "", "hook": "latent talent: hidden, not yet active.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "laudable", "pos": "adj", "pron": "LAW-duh-bull", "also": "laud (verb)", "d1": "Worthy of praise", "sent": "When a major discount mart fired several employees for subduing a gunman, most people considered the action a <b>laudable</b> act of heroism, but the discount chain fired the employees for “violating company policies.” Nevertheless, the mayor lauded the former employees in a medal- granting ceremony.", "related": "Encomium (warm, glowing praise, esp. a formal expression of praise), Panegyric (formal, lofty, or elaborate praise), Paean (song of praise, triumph, or thanks)", "moreinfo": "Laud shares a root with applaud and plaudits (applause, approval).", "hook": "worthy of laud (praise): praiseworthy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lax", "pos": "adj", "pron": "LACKS", "also": "", "d1": "Not strict; careless, loose, slack", "sent": "My parents were really <b>lax</b> about homework—they never checked to see if I did it or not. Sadly, this legacy of <b>laxity</b> is not serving me well while studying for the GRE.", "related": "Slack (loose, negligent, or lazy, as in a slack rope or He is slack in his duties).", "moreinfo": "Lax comes from a Latin word for “loose” that also gives us laxative.", "hook": "lax rules: loose, not strict.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "leery", "pos": "adj", "pron": "LEER-ee", "also": "", "d1": "Suspicious or wary", "sent": "You should be <b>leery</b> of any business opportunity that requires a startup fee and a “sponsor”— you might find yourself sucked into a scam.", "related": "Chary (cautious, wary, or timid). There is a big overlap between leery and chary, although a person could be habitually chary (such as in being shy), whereas a person is generally leery of something specific (and sketchy!).", "moreinfo": "Leery is almost always followed by of. Relatedly, to leer is to look in an intense, creepy way, such as with lustful or malicious intent. You should be leery of anyone who leers at you.", "hook": "leery of strangers: wary and suspicious.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "legerdemain", "pos": "noun", "pron": "led-jer-deh-MAYN", "also": "", "d1": "Slight-of-hand (magic as performed by a magician); trickery or deception", "sent": "The child was astounded when her uncle pulled out a quarter from behind her ear. Of course, she hadn’t actually lost a quarter there; it was just a bit of <b>legerdemain</b> from an amateur magician.", "related": "Prestidigitation is a synonym and thaumaturgy is the working of miracles. To conjure is to produce by magic or call up a spirit or memory.", "moreinfo": "Legerdemain comes from Middle French, meaning light of hand. The modern French word for hand is main, which is related to the root in the English manual (relating to hands, as in manual labor) and manumit (free from slavery, untie the hands).", "hook": "\"light of hand\" (French): sleight of hand, trickery.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lethargic", "pos": "adj", "pron": "leth-AR-jick", "also": "", "d1": "Lazy, drowsy, or sluggish", "sent": "I do love the Golden Corral’s reasonably priced buffet, but I feel so <b>lethargic</b> after I eat my weight in mac-and-cheese and hand-carved turkey.", "related": "Torpid, sluggish, idle, indolent, loafing, and slack are all related to laziness or slowness.", "moreinfo": "In Greek mythology, the River Lethe was the river of forgetfulness or oblivion. It flowed through the underworld, and the dead were required to drink from it in order to forget their earthly lives.", "hook": "full of lethargy: sluggish and drowsy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "licentious", "pos": "adj", "pron": "lie-SENT-shuss", "also": "", "d1": "Sexually unrestrained; immoral; ignoring the rules", "sent": "The <b>licentious</b> behavior Joe was accustomed to practicing at the local strip club was enough to get him thrown out of a nice restaurant and fired from his new job.", "related": "Hedonistic and sybaritic mean “pleasure-seeking.” Debauched (excessively indulging in sensual pleasures) is worse and is closer to licentious.", "moreinfo": "Licentious shares a root with “license.” License is not just used in the sense of “driver’s license” but can also mean “breaking the rules” or “exceptional freedom,” as in “The licentious celebrity thinks he has license to do anything he wants, an attitude that landed him in court after his assistant sued him for harassment.”", "hook": "takes all license: sexually unrestrained, immoral.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "limpid", "pos": "adj", "pron": "LIMP-id", "also": "", "d1": "Clear, transparent; completely calm", "sent": "Hawaii was amazing! The water was crystal clear—so <b>limpid</b> that when you were scuba diving, you could see ahead for what seemed like miles!\nAfter two years meditating in religious seclusion, he had a totally <b>limpid</b> attitude, affected by nothing from the outside world.", "related": "Pellucid (translucent, clear, easy to understand)", "moreinfo": "", "hook": "a limpid pool: perfectly clear, transparent.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lionize", "pos": "verb", "pron": "LIE-un-ize", "also": "", "d1": "Treat like a celebrity", "sent": "Being a chef has long been a prestigious profession, but it is only in the last decade or so that “celebrity chefs” have been <b>lionized</b> and given their own television shows.", "related": "Apotheosis (elevation to the status of a god; perfect example or embodiment)", "moreinfo": "Lionize does come from lion, the animal—in the 16th century, lions were kept in the Tower of London as a tourist attraction. To lionize is to make a person into a spectacle of great interest.", "hook": "lionize a star: treat like a celebrity.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lissome", "pos": "adj", "pron": "LISS-um", "also": "", "d1": "Flexible, supple, agile", "sent": "The actress exercised and stretched every day, but was ultimately told by the casting director that she wasn’t <b>lissome</b> enough to play a ballet dancer. The actress had to agree—“I walk like an ogre,” she said.", "related": "Nimble (moving quickly and lightly; alert)", "moreinfo": "Lithe (limber, flexible) is a synonym—in fact, lissome originated as a variant of lithesome.", "hook": "lithe and lissom: supple and agile.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "listless", "pos": "adj", "pron": "LIST-less", "also": "", "d1": "Spiritless, lacking interest or energy", "sent": "“I’m bored, Mom,” said the <b>listless</b> child. “Can I have a cookie? Can we go to the park? Let’s play a game. There’s nothing to do!”", "related": "Indifferent (not caring, having no interest), Apathy (not caring; absence of feeling; lack of interest or concern)", "moreinfo": "Why doesn’t listless mean “not having a list?” Turns out the root isn’t list so much as lust —to be listless is to lack a “lust for life.”", "hook": "no \"lust\" or desire: spiritless and languid.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "livid", "pos": "adj", "pron": "LIV-id", "also": "", "d1": "Furiously angry, enraged", "sent": "Diane was <b>livid</b> when she discovered that her daughter had borrowed her wedding dress to wear to an ‘80s party. “I have never been angrier in my life,” she said.", "related": "Irascible means easily angered and the related irate means angry (ire is anger).", "moreinfo": "Originally from a French word for a bluish color, livid has the sense of turning blue from rage (although Americans would say that we turn purple with rage—same idea). Livid can also mean bruised or “black-and-blue,” or even turning pale (from sickness) or red (from anger)—but whatever livid is, it’s never good.", "hook": "livid with rage: furiously angry.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lugubrious", "pos": "adj", "pron": "luh-GOO-bree-uss or luh-GYOO-bree-uss", "also": "", "d1": "Mournful, gloomy (sometimes in an exaggerated way)", "sent": "Helen was having a good time at the Irish pub until the Traditional Music Hour started, and the <b>lugubrious</b> tunes made her cry into her Guinness.", "related": "Lachrymose (tearful, mournful), Maudlin (overly tearful and sentimental), Lament (express sorrow, mourn)", "moreinfo": "", "hook": "gloomy and glum: exaggeratedly mournful.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lumber", "pos": "verb", "pron": "LUM-ber", "also": "", "d1": "Walk in a heavy or clumsy way, sometimes due to being weighed down", "sent": "Alicia was a model and was accustomed to walking everywhere as though on a catwalk, so she was quite displeased when she broke her leg and had to <b>lumber</b> around in a cast, thumping the ground everywhere she went.", "related": "To trudge or plod is to walk or move in a laborious, difficult, or slow manner. A child might trudge reluctantly to school. A boring movie might plod along. A heavy, inflexible person might lumber around.", "moreinfo": "", "hook": "lumber along: walk heavily and clumsily.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "luminous", "pos": "adj", "pron": "LOO-min-uss", "also": "luminary (noun)", "d1": "Shining, radiant, well-lit; brilliant or enlightening", "sent": "Use our new light-reflecting shimmer blush for a <b>luminous</b> complexion!\nWe are conferring this honorary degree on the author in appreciation for sharing his <b>luminous</b> intellect with the world. He is truly a luminary.", "related": "Lustrous, effulgent, and refulgent also mean shining.", "moreinfo": "Luminous comes from the root “luc” for “light,” which also occurs in translucent, lucubrate (work or study, originally by candlelight), elucidate (make clear, explain), and lucid and pellucid (clear). A luminary is a person who inspires others (or “lights up” the world).", "hook": "a luminous glow: shining, radiant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "lurid", "pos": "adj", "pron": "LOOR-id", "also": "", "d1": "Gruesome or excessively vivid; sensational, shocking, unrestrained", "sent": "I do like to keep up with what celebrities are doing, but that tabloid is just too <b>lurid</b> for me— just look at the cover: “Worst Cellulite in Hollywood” and “Exclusive Crash Photos.” Truly horrible.", "related": "Gratuitous can mean free or voluntary (a gratuity is a tip in a restaurant), but the other meaning of gratuitous is “without cause or justification; uncalled for.” Gratuitous sex and violence in the movies is that which doesn’t add to the plot—it’s just there because some people like to look at things that are lurid.", "moreinfo": "", "hook": "lurid details: shockingly vivid, gruesome.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 11", "setNum": 11, "coll": "Advanced"}, {"w": "machination or machinations", "pos": "noun, usually plural", "pron": "mack-in-AY-shun or mash-in-AY-shun", "also": "", "d1": "Crafty schemes or plots", "sent": "It’s cute to think that teen idols became famous because their talent was simply so great that the music industry reached out to them, but usually, any teen idol is the product of intense coaching and parental <b>machinations</b>.", "related": "Collude (conspire; cooperate for illegal or fraudulent purposes), Cabal (a conspiratorial group)", "moreinfo": "The verb form machinate has the same meaning (to machinate to overthrow the government). It’s just a coincidence that machinations looks a little like Machiavelli, but machinating is quite Machiavellian!", "hook": "machines of plotting: crafty schemes.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "maelstrom", "pos": "noun", "pron": "MAYL-strum", "also": "", "d1": "Violent whirlpool; any chaotic, turbulent situation", "sent": "The Smiths lost their houseboat in a <b>maelstrom</b>, but were at least thankful that they weren’t on the boat at the time and thus escaped the violent storm at sea.\nAfter having been homeschooled her whole life, the first week of college was a <b>maelstrom</b> of social events, orientations, and business.", "related": "Tumult (a commotion, uprising, riot, or violent outburst), Din (loud, confused noise), Clamor (noisy uproar, as from a crowd), Hubbub (loud noise, confusion)", "moreinfo": "The unusual spelling of maelstrom is due to its Dutch origins.", "hook": "a maelstrom whirlpool: chaotic turbulence.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "magnanimous", "pos": "adj", "pron": "mag-NAN-im-uss", "also": "magnanimity (noun)", "d1": "High-minded, noble, lofty; generous in forgiving others, free of resentment", "sent": "The twins were so different from one another—while Andrea was petty and vengeful and would hold a grudge for years, Marina was quite <b>magnanimous</b>, easily forgiving insults or slights, and simply rising above the petty bickering and cliquish behavior of our high school.", "related": "", "moreinfo": "The Latin “magnus” means “great” and gives us magniloquent (talking in an overly grand way), magnify, and many others. Think of magnanimous as meaning having a great spirit or a big heart.", "hook": "magna (great) + animus (soul): big-souled, generously forgiving.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "magnate", "pos": "noun", "pron": "MAG-nayt or MAG-nit", "also": "", "d1": "Very important or influential person, esp. in business", "sent": "Many students pursue MBAs in hopes of becoming wealthy and powerful <b>magnates</b>; some students never quite make it there, instead spending their careers staring at spreadsheets and taking orders from <b>magnates</b>.", "related": "Scion (descendent, heir—often used to describe the son of a rich, powerful man), Baron (originally a British noble, but now used to describe a powerful businessperson, as in an oil baron or the robber barons of American history)", "moreinfo": "The Latin “magnus” means “great” and gives us magniloquent (talking in an overly grand way), magnanimous (high-minded, noble, forgiving), magnify, and many others.", "hook": "a business magnate: a powerful tycoon.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "malediction", "pos": "noun", "pron": "mal-eh-DICT-shun", "also": "", "d1": "A curse", "sent": "Sheila thought the fortune-teller was her friend, but when she didn’t pay her bill, the fortune teller cast a hex on her, a <b>malediction</b> intended to cause terrible things to befall her.", "related": "Imprecation is a synonym. Execration can mean a curse or cursing, but can also mean insulting or slandering. All three words can be used in the plural or not, with the same meaning —for instance, He was such a bitter person it seemed that only execration (or execrations) ever escaped his lips.", "moreinfo": "Mal means “bad,” of course. The root “dict” comes from “dicere” (to say) and also appears in dictator, dictionary, and indict (connect to a crime), as well as in malediction’s antonym, benediction (blessing).", "hook": "mal (bad) + diction (speech): a curse.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "malinger", "pos": "verb", "pron": "muh-LING-gur", "also": "malingerer (noun)", "d1": "Pretend to be sick, esp. to get out of work, duties, etc.", "sent": "Joey was sick in class on Monday and was sent to the school nurse to sleep it off. The next day, having realized that illness was a good way to get out of class, Joey said his stomach hurt and spent the afternoon in the nurse’s office. By Wednesday, though, the nurse accused him of <b>malingering</b> and sent him back to class.", "related": "To shirk is to evade your duties or try to get out of doing something. To skulk is to hide for a bad reason, such as avoiding work (or waiting to attack someone, etc.)", "moreinfo": "“Mal” means “bad,” and although malinger doesn’t actually come from linger (stick around, stay due to not wanting to leave), the idea of sticking around in a bad way (like malingerer Joey, above) is a good way to remember malinger.", "hook": "a malingerer fakes illness: shirk duty by feigning sickness.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "manifest", "pos": "verb, adj", "pron": "MAN-if-est", "also": "manifestation (noun)", "d1": "Obvious, apparent, perceptible to the eye (adj); to show, make clear, or prove (verb)", "sent": "My superstitious aunt claims that she saw a <b>manifestation</b> of our deceased grandfather, who appeared during a thunderstorm to warn us all about our cousin’s fiance.\nLupus is difficult to diagnose, but sometimes <b>manifests</b> as muscular weakness or joint pain.", "related": "", "moreinfo": "As a noun, a manifest is a list of people or goods aboard a plane, ship, train, etc. A manifestation is often when something “under the surface” breaks out or becomes apparent: The protest was a manifestation of a long-brewing discontent.", "hook": "a manifest truth: obvious; or to manifest, to show.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "mannered", "pos": "adj", "pron": "MAN-erd", "also": "", "d1": "Having a particular manner, esp. an artificial one", "sent": "Although he grew up in rural Ohio, sometime before he got his own makeover show on television he adopted a <b>mannered</b> way of speaking, as though he had grown up in some very odd corner of Victorian England.", "related": "Affectation (fake behavior, such as in speech or dress, adopted to give a certain impression)", "moreinfo": "Mannered is often part of compound words, such as ill-mannered, which just means having bad manners.", "hook": "overly mannered: artificially stylized.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "mar", "pos": "verb", "pron": "MAR", "also": "", "d1": "Damage, spoil, ruin", "sent": "The interior designer’s secret was to buy furnishings and fixtures that had been <b>marred</b> on the shop floor and therefore were sold at steep discounts; she would then fix the defects herself or add additional aging effects to the pieces.", "related": "Vitiate (spoil, weaken, or corrupt), Deface (disfigure, mar the surface of)", "moreinfo": "", "hook": "mar the surface: damage and spoil.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "martinet", "pos": "noun", "pron": "mar-tin-ET", "also": "", "d1": "Person who adheres to rules extremely closely; strict disciplinarian", "sent": "It was no fun growing up with a military officer for a dad. He was such a <b>martinet</b> he once made me do twenty pushups for being one minute late to bed—even though the reason I was late was that I wanted to kiss him goodnight.", "related": "Doctrinaire (person who applies doctrine in an impractical or rigid and close- minded way), Jingoism (excessive, loud patriotism and aggressive, warlike foreign policy), Hawkish (advocating war), Chauvinism (fanatical patriotism or blind enthusiasm for military glory; undue or biased devotion to any group, cause, etc.)", "moreinfo": "After the general Jean Martinet, a French drillmaster.", "hook": "drills strictly by the book: a rigid disciplinarian.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "maudlin", "pos": "adj", "pron": "MAWD-lin", "also": "", "d1": "Excessively sentimental, showing sadness or some other emotion in a foolish or silly way", "sent": "I had no idea the film was going to be a <b>maudlin</b> affair in which the male lead dies and the female lead has his baby, who then also dies. Half the theater was weeping, and the other half was just shaking their heads at how badly written the movie was.", "related": "Cloying, treacly and saccharine all mean “disgustingly or distastefully sweet” (as in some television shows marketed to little girls, for example).", "moreinfo": "Maudlin can also mean acting foolishly emotional due to drunkenness.", "hook": "a maudlin drunk: tearfully oversentimental.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "maxim", "pos": "noun", "pron": "MACK-sim", "also": "", "d1": "A general truth or fundamental principle, esp. expressed as a proverb or saying", "sent": "My favorite <b>maxim</b> is “Seize the day!” How much would it cost to get that on a tattoo? How much more for “Curiosity killed the cat”?", "related": "Dictum, Apothegm, and Adage are all words for a proverb, saying, or truism. A saw is also a maxim and often appears as “an old saw.” Platitude is more negative, meaning a cliched or trite statement.", "moreinfo": "Maxim shares a root with maximum; the idea is that a maxim is an expression of the “biggest,” most fundamental truth.", "hook": "a wise maxim: a proverb or guiding principle.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "mendicant", "pos": "noun", "pron": "MEN-dih-cuhnt", "also": "", "d1": "Beggar, or religious follower who lives by begging", "sent": "Having joined a <b>mendicant</b> order, the friar had vowed not to own property, and instead to subsist on the donations of the faithful.", "related": "Pauper (very poor person), Alms (money or other donations given as charity)", "moreinfo": "Mendicant comes from a root for “defect, fault” that also gives us mend and amendment, which relate to fixing faults. The original sense was that mendicants were beggars who had physical disabilities.", "hook": "a mendicant monk begs: a beggar.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "meretricious", "pos": "adj", "pron": "mair-uh-TRISH-uss", "also": "", "d1": "Attractive in a vulgar or flashy way, tawdry; deceptive", "sent": "The singer performed her concert draped in what looked from far away like precious jewels. Up close, though, the fan could see that the accessories were just <b>meretricious</b> plastic, glittery junk, like what little girls buy at the mall.", "related": "Showy means showing off and could be good or bad (a showy car). Garish refers to something much too bright, vivid, or fancy (makeup that looks okay in a nightclub looks garish in the office). Gaudy items stand out in a cheap, tasteless, or overly colorful way (wearing too much big jewelry looks gaudy).", "moreinfo": "Meretricious comes from a word for “prostitute.” The definition “deceptive” is related to the idea of something looking better than it really is. Keep in mind that all of these word origins are based on very old-fashioned ideas, some of them as old as the Romans.", "hook": "flashy like a decoy: gaudy and deceptively attractive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "metaphysical", "pos": "adj", "pron": "met-uh-FIZZ-ick-ull", "also": "metaphysics (noun)", "d1": "Concerned with abstract thought, related to metaphysics (branch of philosophy concerned with explaining the nature of being and of the world); very subtle or abstruse", "sent": "My poetry class has all kinds. In contrast to Gary’s poetry about dogs and horses, Neil’s poetry is very <b>metaphysical</b>, exploring the relation of mortal humans to a timeless universe. It’s a little over Gary’s head.", "related": "Ontology is part of metaphysics and is concerned with the investigation of the basic categories of being and their relation to one another.", "moreinfo": "Metaphysics is much older than science—to the Greeks, all inquiry was “philosophy.” Today, of course, science does a lot of the explaining of the world, so metaphysics can be understood as a non-empirical study of those topics. Empirical means “based on experience or experimentation; not purely based on theory.”", "hook": "beyond physics: of abstract being and philosophy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "milieu", "pos": "noun", "pron": "mill-YUH", "also": "", "d1": "Environment, atmosphere; the environmental setting in which something happens or develops", "sent": "Becoming a priest in the anything-goes <b>milieu</b> of the 1960s gave Father Bryant an interesting perspective on two contrasting philosophies.\nAfter the fall of the Soviet Union, a <b>milieu</b> of crushing poverty, yet hopeful aspiration, existed in the former satellite state.", "related": "Zeitgeist (the “spirit of an age,” the cultural or intellectual mood of a time period), Ethos (the character, personality, or moral values specific to a person, group, time period, etc.)", "moreinfo": "Milieu comes from a French word for “middle.” A milieu is certainly something you’re in the middle of.", "hook": "your social milieu: environment, setting.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "militate", "pos": "verb", "pron": "MILL-it-ayt", "also": "", "d1": "Have a great effect, weigh heavily (often as militate against)", "sent": "While his resume was stellar, his speech impediment <b>militated</b> against his performance in job interviews.", "related": "Inimical (hostile, adverse or harmful—something that militates against your success would be inimical to your success)", "moreinfo": "Of course, militate is related to the military; it used to mean to fight for a side or belief. Today, it’s more circumstances that militate (rather than people).", "hook": "\"militate against\": weigh heavily against, like an army.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "mired", "pos": "adj", "pron": "MY-erd", "also": "", "d1": "Stuck, entangled (in something, like a swamp or muddy area), soiled", "sent": "<b>Mired</b> in her predecessor’s mess and mistakes, the new CEO found it difficult to take the company in a new direction.", "related": "Morass and quagmire are also words (often used metaphorically) for soft, swampy ground that a person can sink into. The Vietnam War was famously called a quagmire.", "moreinfo": "The expression muck and mire means, literally, “animal waste and mud” and is used in the sense, “The federal prosecutor spent weeks wading through the muck and mire of the scandal—every uncovered document showed that the corruption was deeper and worse than previously thought.” To muck up is to mess up or get dirty, and to muck about or around is to waste time.", "hook": "mired in mud: stuck and bogged down.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "mirth", "pos": "noun", "pron": "MERTH", "also": "", "d1": "Jollity, merriment; amusement or laughter", "sent": "Nothing could beat the <b>mirth</b> of the office holiday party—once everyone had heard how fat their bonuses would be, the delighted staff formed a conga line and drank and danced the night away.", "related": "Gaiety is a synonym. Memory Trick: The slang term mirthquake (circa 1928) means an explosive outburst of laughter. Of course, mirthquake won’t be on the GRE, but it might help you remember mirth!", "moreinfo": "", "hook": "full of mirth: merriment and laughter.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "misanthrope or misanthropist", "pos": "noun", "pron": "MISS-un-throhp / miss-AN-thruh-pist", "also": "", "d1": "Hater of humankind", "sent": "He is such a <b>misanthrope</b> that when some Girl Scouts going door-to-door asked if he’d like to sponsor a hungry child overseas, he replied, “The fewer people in the world, the better,” and shut the door in their faces!", "related": "Antonym Philanthropist literally means “lover of humankind,” although in modern English it refers to someone who donates money to charity.", "moreinfo": "“Anthro” means “man” (in the sense of “humankind”) and also gives us anthropology, androgens (male hormones, such as used in steroids), and androgynous (having both male and female qualities).", "hook": "mis (hate) + anthropos (human): a people-hater.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "missive", "pos": "noun", "pron": "MISS-iv", "also": "", "d1": "Letter, written message", "sent": "While Don was overseas fighting in World War II, he lived for the <b>missives</b> from the wife he had left behind.", "related": "", "moreinfo": "The Latin “mittere” (to send) also gives us transmit, remit, and mission.", "hook": "a missive arrives: a letter, something sent.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "modicum", "pos": "noun", "pron": "MOD-ick-um", "also": "", "d1": "A little bit or limited quantity", "sent": "In her first five years in Hollywood, she experienced only a <b>modicum</b> of success as an actress, appearing twice in commercials and once as a waitress on Desperate Housewives.", "related": "An iota, mite, or tad of something is also a small amount (as in, If you had one iota of decency, you would have come to the funeral, or I had the tailor shorten the sleeves just a tad).", "moreinfo": "Modicum shares a root with moderate.", "hook": "a modicum of sense: a small amount.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "modish", "pos": "adj", "pron": "MOH-dish", "also": "", "d1": "Stylish, contemporary", "sent": "While some sculptors sought to make their work universal and timeless, Dania sculpted <b>modish</b> creations that captured the pop cultural zeitgeist—for instance, a sculpture of Rihanna with an umbrella, or a three-foot high representation of the latest Alexander McQueen heels.", "related": "In vogue is a synonym.", "moreinfo": "In the U.S., “a la mode” generally means “with ice cream” (pie a la mode), but it really means “in fashion” (in French and also in English). Perhaps ice cream was once a big fad.", "hook": "a modish outfit: stylish, in fashion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "molt", "pos": "verb", "pron": "MOLT", "also": "", "d1": "Shed or cast off, esp. to regularly shed skin, feathers, etc. (as a snake)", "sent": "Wow, the special effects in that movie were really cool! The actress grew scales all over her body and then <b>molted</b>, leaving behind a scaly skin covering shaped like an entire woman, and then she looked like herself again.", "related": "To slough or shed is also to lose an outer coating; for instance, some people exfoliate their skin to slough off dead skin cells.", "moreinfo": "Molt shares a root (“change”) with mutate and mutable.", "hook": "a snake molts: sheds its skin or feathers.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "monastic", "pos": "adj", "pron": "muh-NAST-ick", "also": "", "d1": "Relating to or resembling a monastery (where monks or nuns live), esp. by being quiet, secluded, contemplative, strict, and/or lacking luxuries", "sent": "Christine decided that the only way she was going to finish her Ph.D. was to live a <b>monastic</b> lifestyle: she broke up with her boyfriend, cancelled her cable service, left the house only when necessary, and ultimately had a draft of her dissertation a few months later.", "related": "Austere (severe in manner or appearance; very self-disciplined, ascetic; without luxury or ease; sober or serious), Ascetic (abstinent or austere in lifestyle or a person who lives such a lifestyle), Hermit or Anchorite (person who lives away from society, esp. for religious reasons), Recluse (person who lives in solitude)", "moreinfo": "", "hook": "a monastic life: monk-like, austere and secluded.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 12", "setNum": 12, "coll": "Advanced"}, {"w": "morose", "pos": "adj", "pron": "muh-ROHSS", "also": "", "d1": "Gloomy, sullen", "sent": "She had always been a happy child, but once she hit high school and decided to become a goth, she adopted a <b>morose</b> attitude to match her all-black clothing.", "related": "", "moreinfo": "Morose sounds a bit like morbid, which means “mentally unhealthy, diseased, gruesome.” If you’re depressed, you’re morose; if you enjoy looking at photos of crime scenes, we’d say you have a morbid interest.", "hook": "morose and glum: gloomy and sullen.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "multifarious", "pos": "adj", "pron": "mull-tif-AYR-ee-uss", "also": "", "d1": "Diverse, having a lot of variety", "sent": "Last year’s jewelry line was all metal and neutrals, but this year’s presents a <b>multifarious</b> array of brilliant colors.", "related": "Heterogeneous (different in type, incongruous; composed of different types of elements)", "moreinfo": "", "hook": "multi (many) + farious (kinds): wildly varied.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "munificent", "pos": "adj", "pron": "myoo-NIF-iss-ent", "also": "", "d1": "Generous, giving liberally", "sent": "The elderly titan of industry was notoriously miserly, sometimes called “the cheapest man alive.” But his wife was quite <b>munificent</b>, and after his death, she used his fortune to support numerous charities and to buy a house for their longtime maid.", "related": "Magnanimous (high-minded; generous in forgiving others), Philanthropic (giving money to charity, providing assistance to others)", "moreinfo": "Munificent shares a root (“give”) with remuneration, meaning repayment or compensation.", "hook": "muni (gift) + ficent (making): lavishly generous.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "myopic", "pos": "adj", "pron": "my-AH-pick", "also": "myopia (noun)", "d1": "Near-sighted; lacking long-term thinking, short-sighted", "sent": "To raise prices in a time of crisis is both wrong and deeply <b>myopic</b>—our profits would go up in the short term, but our customers’ resentment would simmer for decades.\nMyron’s myopia is so strong that he cannot be helped by contact lenses and has to wear the heavy glasses he has worn for decades.", "related": "Improvident (not providing for the future)", "moreinfo": "The “op” in myopia comes from a Latin root for “eye” and also appears in optometrist, optical, and ocular.", "hook": "myopia is near-sightedness: short-sighted, no foresight.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "nadir", "pos": "noun", "pron": "NAY-der or NAY-deer", "also": "", "d1": "Lowest point", "sent": "It was only when Ming reached her absolute <b>nadir</b>—what her recovery program called “rock bottom”—that she admitted she had a problem and checked herself into rehab.", "related": "The opposite of the nadir is the zenith, or highest point. Both words are terms from astronomy, referring to points directly below and above the observer on an imaginary sphere on which celestial bodies appear to be projected. On the GRE, these words will be used metaphorically —the nadir of one’s struggles, the zenith (or acme, pinnacle, or summit) of one’s success.", "moreinfo": "Finally, a GRE word from Arabic! Nadir comes through Latin from the Arabic nazir, “opposite to”—here, the nadir is opposite the zenith.", "hook": "the nadir of his career: the lowest point (opposite of zenith).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "neologism", "pos": "noun", "pron": "nee-AH-luh-jizm", "also": "", "d1": "New word or phrase (or a new meaning applied to an existing word or phrase)", "sent": "You won’t find “fauxhawk” in the dictionary—it’s a <b>neologism</b> that describes a fake mohawk (faux means fake and is pronounced “foe”) created by sculpting the hair into a mohawk-like crest without actually shaving the sides.", "related": "", "moreinfo": "The root “log/loq” refers to speech and also occurs in eloquent, logic, loquacious (talkative) and interlocutor (participant in a dialogue; interrogator).", "hook": "neo (new) + logos (word): a newly coined word.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "neophyte", "pos": "noun", "pron": "NEE-uh-fight", "also": "", "d1": "Beginner, novice; person newly converted to a religion", "sent": "It was totally outrageous of our law firm to send a <b>neophyte</b> into the courtroom to defend our case against a team of experienced attorneys.", "related": "Tyro (beginner)", "moreinfo": "Neophyte shares a root (“planted”) with phytoplankton and many other science words. A religious neophyte is someone in whom a faith has been newly “planted.”", "hook": "neo (new) + phyte (grown): a novice, beginner.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "nettle", "pos": "verb", "pron": "NET-ull", "also": "", "d1": "Irritate, sting, or annoy", "sent": "His first year in college, my little brother failed gym. How is that even possible? I always remind him about it just to <b>nettle</b> him. Of course, he usually strikes back by reminding me of that time I crashed an amusement park’s go-cart.", "related": "Irk and vex also mean to irritate or annoy.", "moreinfo": "Literally, nettles are a stinging plant.", "hook": "a stinging nettle: to irritate and annoy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "noisome", "pos": "adj", "pron": "NOY-sum", "also": "", "d1": "Offensive, disgusting; harmful", "sent": "Everyone knows that smoking is deadly, but even “herbal” cigarettes are a <b>noisome</b> habit— and <b>noisome</b> to your health!", "related": "Deleterious means harmful, Baneful means very harmful or fatal, and Noxious means harmful or morally corrupting. Fetid means smelly.", "moreinfo": "Noisome isn’t really about noise! (The word shares a root with “annoy”). The GRE is not above trying to trick you into picking noisome when you really need a word for “noisy” (like cacophonous or dissonant).", "hook": "noxious, not noisy: foul-smelling, harmful.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "nominal", "pos": "adj", "pron": "NAH-min-ull", "also": "", "d1": "Trivial, so small as to be unimportant; in name only, so-called", "sent": "A notary public will certify a document for a <b>nominal</b> fee, usually under $3.\nThe country has a <b>nominal</b> president, but his detractors say he’s just a puppet leader for the more powerful countries providing foreign aid.", "related": "Putative (supposed or reputed)", "moreinfo": "Nominal originally meant “pertaining to names/nouns.” The same root is found in misnomer (an inappropriate name).", "hook": "a nominal fee; in name only: trivial or so-called.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "nontrivial", "pos": "adj", "pron": "non-TRIV-ee-ull", "also": "", "d1": "Important or big enough to matter", "sent": "The chief of staff told the assembled doctors, “We all make mistakes. But this mistake was <b>nontrivial</b>, and there is going to be an investigation.”", "related": "Trivial, of course, means “too small to matter,” and has the synonyms trifling and nugatory. Trivia (as in the questions on Jeopardy) is called that because the questions are about small facts and details—that is, you never go on a trivia show and get asked about a nontrivial topic, like the meaning of life.", "moreinfo": "", "hook": "not trivial: actually important.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "normative", "pos": "adj", "pron": "NOR-muh-tiv", "also": "", "d1": "Implying or attempting to establish a norm; expressing value judgments or telling people what to do (rather than merely describing that which is happening)", "sent": "The reason we are not understanding each other in this argument about grammar is that you are arguing <b>normatively</b>, telling me how people should talk, and I am simply reporting and analyzing how people actually talk.", "related": "Prescriptive is a synonym (a prescriptive take on nutrition would tell people how to eat, just as a doctor’s prescription also tells you what to do). Memory Trick: Something normative is trying to make everyone be normal.", "moreinfo": "", "hook": "sets a norm: prescribing how things should be.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "obdurate", "pos": "adj", "pron": "AHB-der-it or AHB-jer-it", "also": "", "d1": "Stubborn, hardhearted, hardened in wrongdoing", "sent": "The first mate reported that there was some fuzzy shape on the horizon, but the captain insisted that the instruments showed no such object, and <b>obdurately</b> sailed straight ahead—right into an iceberg.\nThis <b>obdurate</b> criminal should never be let out on parole—he simply cannot be reformed.", "related": "Flinty, glacial, stony, and callous can have the meaning of being emotionally “hard” or cold. Reprobate and unregenerate can refer to people who are hardened evildoers.", "moreinfo": "“Ob” means “against” and the rest of the word is derived from the Latin “durare” (hard), which also gives us durable and endure. Obdurate people are hardened against feelings, persuasion, or conscience.", "hook": "ob + durate (hard): stubbornly hardhearted.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "oblique", "pos": "adj", "pron": "oh-BLEEK or uh-BLEEK", "also": "", "d1": "Slanting or sloping; indirect, misleading, or evasive", "sent": "After the fifteenth <b>oblique</b> reference that Bella made to George or George made to Bella, everyone in the office figured out that they were dating.\nThe serial killer loved to talk to interrogators, but gave only <b>oblique</b> answers that were useless in finding the bodies.", "related": "", "moreinfo": "In math, oblique lines are neither parallel nor perpendicular. Your obliques are the abdominal muscles (along the sides) that run at a slant. In botany, an oblique leaf has unequal sides. You should now be prepared to interpret oblique in any strange context—it’s slanting, or metaphorically “slanting”!", "hook": "an oblique angle or remark: slanting, indirect, evasive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "occlude", "pos": "verb", "pron": "uh-CLOOD", "also": "", "d1": "Stop up, close, shut in or shut off", "sent": "This drain guard is here to make sure nothing (like silverware) ends up <b>occluding</b> your garbage disposal.\nDon’t eat that enormous wad of gum! I’m no doctor, but what if it <b>occludes</b> your intestines or something?", "related": "Occult (to hide, to shut off from view)", "moreinfo": "Occlude shares a root (shut, close) with close, cage, and claustrophobia.", "hook": "occlude the artery: block and close off.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "opine", "pos": "verb", "pron": "oh-PINE", "also": "", "d1": "Express an opinion", "sent": "After all was said and done, he <b>opined</b> that he wished he had never tried to sail around the world in a canoe, and he was sorry that the rescue effort was so expensive.", "related": "Expatiate (to expand or elaborate on a topic, to explain in detail), Excogitate (think through in detail)", "moreinfo": "", "hook": "opine on it: express an opinion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "opprobrium", "pos": "noun", "pron": "uh-PROH-bree-um", "also": "opprobrious (adj)", "d1": "Disgrace and disapproval that result from outrageously shameful actions", "sent": "Some young starlets seem to think a DUI offense isn’t such a big deal, but drunk driving deserves <b>opprobrium</b>—driving under the influence maims and kills innocent people every year.", "related": "Infamy (very bad reputation; strong condemnation by the public), Notorious (well known for a disgraceful reason), Obloquy (shame, disapproval, or verbal abuse esp. by the public or a group)", "moreinfo": "", "hook": "heaped-on disgrace: public shame and scorn.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "orotund", "pos": "adj", "pron": "OR-uh-tund", "also": "", "d1": "Full, rich, and clear (of the voice or speaking); pompous, bombastic", "sent": "The actor James Earl Jones has long been sought after for voiceover work as well as acting jobs because of his dignified, <b>orotund</b> voice.", "related": "Sonorous (giving out a deep, rich, loud sound), Dulcet (melodious, agreeable to the ear), Mellifluous (richly and smoothly flowing, as “a mellifluous voice”), Stentorian (loud)", "moreinfo": "Rotund simply means rounded—when applied to a person, it’s a somewhat more polite word than “fat.” The connection is the idea of “roundness”—orotund comes from the idea of speaking with a rounded mouth.", "hook": "oro (mouth) + rotund (round): a full, rich voice, or pompous.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "ossify", "pos": "verb", "pron": "AH-sif-fy", "also": "", "d1": "Become bone or become hard like bone; become inflexible in attitudes, opinions, etc.", "sent": "I remember having many broad-ranging discussions with him back in college, but since then, his opinions have ossified—sadly, he is now the most close-minded person I know.", "related": "Doctrinaire (person who applies doctrine in an impractical or rigid and close- minded way), Dogmatic (close-minded, expressing one’s own opinions as though they were facts)", "moreinfo": "Ossify shares a Latin root (“bone”) with osseous (bony), osteoporosis (condition in which the bones become fragile), and ossuary (place for bones of the dead, such as a cemetery or urn).", "hook": "os (bone) + ify: turn to bone, become rigid.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "ostensible or ostensive", "pos": "adj", "pron": "ah-STEN-sih-bull / ah-STEN-siv", "also": "", "d1": "Professed, evident, or pretended; outwardly appearing in a certain way", "sent": "<b>Ostensibly</b>, she came to volunteer out of the goodness of her heart. However, I think she’s really here because she has a crush on one of the other volunteers.\nHe’s an <b>ostensive</b> candidate for the job, but we need to check these references before we move further.", "related": "Putative (supposed or reputed), Nominal (trivial; in name only, so-called)", "moreinfo": "The Latin “ostendere” means “to show” and also occurs in ostentatious, meaning “showing off.”", "hook": "outwardly shown: professed or apparent, not real.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "ostentatious", "pos": "adj", "pron": "AH-sten-TAY-shuss", "also": "", "d1": "Pretentious, boastful showiness", "sent": "Her <b>ostentatious</b> clothing is simply not appropriate in a business environment—in fact, nothing emblazoned with 2,000 Swarovski crystals is.", "related": "Showy means showing off and could be good or bad (a showy car). Garish refers to something much too bright, vivid, or fancy (makeup that looks okay in a nightclub looks garish in the office). Gaudy items stand out in a cheap, tasteless, or overly colorful way (wearing too much big jewelry looks gaudy).", "moreinfo": "The Latin “ostendere” means “to show” and also occurs in ostensible/ostensive, meaning “professed, evident, or pretended; outwardly appearing in a certain way.”", "hook": "ostensibly showing off: boastfully showy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "overwrought", "pos": "adj", "pron": "oh-ver-RAHT", "also": "", "d1": "Overly nervous, agitated, or excited; too ornate, elaborate, or fussy; overdone", "sent": "By the time her boyfriend met her in the park, she was <b>overwrought</b>, thinking he must have chosen a public place so he could break up with her—turned out, he had just invited her to a picnic.\nAccustomed to more spare American churches, Father Smith found the churches of South America a bit <b>overwrought</b>, with enormous, flowery, gold altars and gold-plating on everything imaginable.", "related": "Florid (reddish or rosy; flowery, showy, or excessively fancy—often, florid writing), Rococo (ornate, florid)", "moreinfo": "Wrought simply means “worked, made.” With metals, it means “made from hammering or beating.” Wrought-iron furniture is simply made from iron. Something finely wrought is made with care and attention to detail.", "hook": "over + wrought (worked up): too agitated, or too ornate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "palatial", "pos": "adj", "pron": "puh-LAY-shull", "also": "", "d1": "Suitable for or resembling a palace, magnificent", "sent": "After a career spent in budget hotels, she was thrilled when the client put her up in a <b>palatial</b> room at a five-star hotel. She raided the minibar and then promptly fell asleep on the 600-thread- count duvet.", "related": "Olympian (suitable for the gods; majestic, aloof), Stately (majestic; very elegant, dignified, or imposing)", "moreinfo": "", "hook": "a palatial estate: palace-like and grand.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "palliate", "pos": "verb", "pron": "PAL-ee-ayt", "also": "palliative (adj)", "d1": "Make less serious or severe; relieve symptoms of an illness", "sent": "The doctors said it would be pointless to subject Uncle Al to continued treatments when there was no hope of a cure, so we gave consent for him to be transferred to the <b>palliative</b> care wing where he would be made as comfortable as possible in his final weeks or months.", "related": "Ameliorate, Mitigate, Alleviate, and Extenuate also refer to lessening something bad without eliminating it.", "moreinfo": "Palliate comes from the Latin “pallium,” a cloak, which covers up. To palliate a crime is to try to make it seem not as bad, such as by introducing extenuating circumstances.", "hook": "palliative care eases pain: make less severe without curing.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "pallid", "pos": "adj", "pron": "PAL-id also pallor (noun)", "also": "", "d1": "Abnormally pale (as skin); lacking color or vitality", "sent": "When Eric left the office mid-day, we knew from the pallor that had overtaken him that he really was getting sick.\nWe need this blog to really hit hard against the special interest groups ruining our country, and your <b>pallid</b> writing isn’t doing it—you’re going to bore people to death with this wimpy prose.", "related": "Wan (abnormally pale), Sallow (sickly-yellow in color)", "moreinfo": "", "hook": "a pallid complexion: pale, drained of color.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 13", "setNum": 13, "coll": "Advanced"}, {"w": "panache", "pos": "noun", "pron": "puh-NASH", "also": "", "d1": "Flair, style, swagger; a flamboyant or grand way of acting", "sent": "Not only did he quit, but he did so with <b>panache</b>, actually delivering a Powerpoint presentation that we thought would be about the budget, but which turned out to be quite obscene. He then pulled out a flask, guzzled its contents, and walked out. That guy’s kind of a legend.", "related": "Verve (vigor, spirit, liveliness)", "moreinfo": "In French, a panache is literally a tuft of feathers, such as you might display on a (rather ostentatious) hat. The figurative use of panache dates from the tale of Cyrano de Bergerac (played by Gerard Depardieu in 1990’s Cyrano de Bergerac) and is often associated with him.", "hook": "dances with panache: flair and flamboyant style.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "panegyric", "pos": "noun", "pron": "pan-uh-JEER-ick or pan-uh-JIRE-ick", "also": "", "d1": "Formal or lofty expression of praise", "sent": "Lincoln enthusiasts were excited that a new biography was to be published, and many hoped that new light would be cast on certain controversies. However, the book was pure <b>panegyric</b>— nothing but heroic tales, uncritically presented.", "related": "Encomium (warm, glowing praise, esp. a formal expression of praise), Laudation (praise, tribute), Eulogy (a speech of praise or written work of praise, esp. a speech given at a funeral), Paean (song of praise, triumph, or thanks)", "moreinfo": "Panegyric contains the root “pan” (“all”), indicating a speech given in public, to all.", "hook": "pan (all) + egyric (praise): a lofty speech of praise.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "panoply", "pos": "noun", "pron": "PAN-uh-plee", "also": "", "d1": "Splendid, wide-ranging, impressive display or array", "sent": "Our old cafeteria had only premade salads, but the new cafeteria has a salad bar with a <b>panoply</b> of toppings.", "related": "", "moreinfo": "Panoply contains the root “pan” (“all”) as well as a root for weapons. A panoply was originally a full suit of armor and can still be military regalia or something that covers and protects (The sergeant arrived in full panoply).", "hook": "pan (all) + oply (armor): a full, splendid array.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "paragon", "pos": "noun", "pron": "PAIR-uh-gahn", "also": "", "d1": "Model of excellence, perfect example", "sent": "Unlike his sister, he was a <b>paragon</b> of responsibility, taking in her three children when she went to jail, and even switching jobs so he could be there to pick them up from school.", "related": "Prototype (original model serving as the basis for future copies or versions), Paradigm (model or pattern; worldview, set of shared assumptions, values, etc.), Exemplar (example, item that is representative or typical, something worthy of imitation), Epitome (perfect example, brief summary)", "moreinfo": "A paragon is also a large, perfect diamond or pearl. Paragon is often used in the expression “paragon of virtue.”", "hook": "a paragon of virtue: a perfect model.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pare", "pos": "verb", "pron": "PAIR", "also": "", "d1": "Peel or cut off the outer layer (such as peeling fruit with a knife), reduce or trim as if cutting off the outer parts", "sent": "We need to <b>pare</b> down our budget if we’re going to survive on unemployment for awhile.\nShe simplified her life by paring commitments from her schedule.", "related": "Truncate (shorten by cutting off a part), Abridge (reduce or lessen; shorten by omitting parts throughout while retaining the main idea)", "moreinfo": "Pare shares a root (“make ready, produce, bring forth”) with prepare and with various medical words related to childbirth, such as postpartum.", "hook": "pare an apple: peel or trim the outer layer.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "parley", "pos": "noun, verb", "pron": "PAR-lee", "also": "", "d1": "Discussion, negotiation, esp. between enemies (noun); to have such a discussion (verb)", "sent": "The industry trade show is our chance to <b>parley</b> with our competitors. We do go out for drinks together, but really, we’re just hoping someone slips up and tells us about their new product line.", "related": "Armistice (truce, mutual agreement to temporarily stop fighting)", "moreinfo": "French speakers will note parley’s similarity to the French verb parler. The same root (“speech”) also occurs in the English parable, parlance, and parliament.", "hook": "a parley with the enemy: a negotiation.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "parry", "pos": "verb", "pron": "PAIR-ee", "also": "", "d1": "Deflect or avoid (esp. a blow or attack); skillfully evade (a question)", "sent": "When asked by a reporter if rumors of his infidelity were true, the candidate parried, answering that he had always supported legislation bolstering the sanctity of marriage.", "related": "Riposte is also a fencing term that has made it into common use. When an opponent thrusts (with a sword), your move to defend yourself is a parry; then, the short thrust you make back in retaliation is a riposte. Outside of fencing, a riposte is a witty comeback or swift reply.", "moreinfo": "Parry shares a root (“make ready, produce, bring forth”) with prepare, although this root came through Italian and French to mean “to ward off, defend.”", "hook": "parry the blow: deflect and evade.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pastiche", "pos": "noun", "pron": "past-EESH", "also": "", "d1": "Mix of incongruous parts; artistic work imitating the work of other artists, often satirically", "sent": "The slickly-produced boy band’s first album was deeply unimaginative, just a <b>pastiche</b> of every other boy band album ever produced.", "related": "Heterogeneous means “made up of diverse elements.” Hodgepodge, Medley, Farrago, Potpourri, Pastiche and Olio are all words for mixtures of diverse things. Eclectic means “selecting the best of everything or from many diverse sources” and thus is more positive than pastiche, which indicates a sort of thrown-together mess of other people’s work.", "moreinfo": "From the Italian pasticcio, something made by mixing borrowed elements from other sources. Pasticcio is also a pasta dish—the idea being “a mess” or scramble of pasta.", "hook": "a pastiche of styles: an imitative mix.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pathogenic", "pos": "adj", "pron": "path-uh-JEN-ick", "also": "", "d1": "Capable of producing disease", "sent": "Many common and legal food additives are <b>pathogenic</b>, known to lead to diabetes or even cancer.", "related": "", "moreinfo": "“Pathos” means “disease” (as in pathological, “diseased”) and “gen” means “producing” (as in generate).", "hook": "patho (disease) + genic (making): disease-causing.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pedant", "pos": "noun", "pron": "PED-int", "also": "pedantic (adj)", "d1": "Person who pays excessive attention to book learning and rules, or who uses his or her learning to show off", "sent": "I hate when <b>pedants</b> interrupt you to correct your grammar, especially if what you’re saying is important—and in my opinion, almost anything is more important than <b>pedantic</b> quibbles over whether it’s okay to end a sentence with a preposition.", "related": "Didactic means “intended to instruct; teaching, or teaching a moral lesson.” This is a perfectly positive quality for a teacher, but could be annoying coming from a peer. Fastidious means “excessively particular, hard to please.”", "moreinfo": "“Ped” means “child,” as in pediatrician. A pedant was once a schoolmaster; now it’s someone who acts like a schoolmaster in inappropriate situations.", "hook": "a pedant nitpicks the rules: a book-learning show-off.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "peddle", "pos": "verb", "pron": "PED-ull", "also": "", "d1": "Travel around while selling; sell illegally; give out or disseminate", "sent": "After an unsuccessful year spent <b>peddling</b> cutlery door-to-door, he turned to <b>peddling</b> drugs, thus landing himself in jail.\n“I don’t want these people <b>peddling</b> lies to our children,” said Mrs. Hoffman, protesting an event in which fringe political candidates were invited to speak to kids.", "related": "A peddler or vendor sells things, as does a fishmonger, ironmonger, etc. (although a scandalmonger doesn’t so much sell scandals as promote them).", "moreinfo": "", "hook": "peddle wares: travel and sell, or spread around.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pejorative", "pos": "adj, noun", "pron": "pih-JOR-uh-tiv", "also": "", "d1": "Disparaging, derogatory, belittling (adj); a name or word that is disparaging (noun)", "sent": "I’m open to constructive criticism, but I think my supervisor’s remarks are inappropriately <b>pejorative</b>—it’s never okay to call an employee a “sniveling dullard.”\nAlthough these insults wouldn’t be understood by most, “poetaster” and “mathematicaster” are <b>pejoratives</b> for minor, incompetent poets and mathematicians, respectively.", "related": "Vituperate and revile mean to verbally abuse or speak very badly of.", "moreinfo": "", "hook": "a pejorative term: an insulting, belittling word.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pellucid", "pos": "adj", "pron": "puh-LOO-sid", "also": "", "d1": "Transparent, translucent; clear, easy to understand", "sent": "He decided that the cove’s <b>pellucid</b> waters were an excellent place to teach his daughter to swim, reasoning that, if she started to sink, he would easily be able to see where she was.", "related": "Lucid can mean literally clear, but often means metaphorically clear or clearheaded —a lucid argument, a lucid person. Pellucid usually means literally transparent, as above. Limpid means clear, transparent, or completely calm.", "moreinfo": "The prefix “pel” or “per” means “through” and often doesn’t change the meaning of the other root parts that much (for instance, fervid means passionate and perfervid means really passionate). You can think of the pel/per prefix as similar to the English expression “through and through.”", "hook": "pel (through) + lucid (clear): crystal clear.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "penitent", "pos": "adj, noun, noun", "pron": "PEN-it-ent", "also": "penitence (noun)", "d1": "Regretful, feeling remorse for one’s sins or misdeeds (adj); a person who feels this way (noun)", "sent": "After being “separated” from the college for plagiarism, she wrote a letter to the Dean expressing her deep regret and penitence and hoping to be readmitted.", "related": "Contrite and Remorseful are synonyms. To atone or make amends is to try to make up for having done something wrong.", "moreinfo": "Penitent shares a root with penitentiary (“prison”) and penal (“relating to punishment”).", "hook": "a penitent sinner: remorseful and repentant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "penumbra", "pos": "noun", "pron": "pen-UM-bruh", "also": "", "d1": "Outer part of a shadow from an eclipse; any surrounding region, fringe, periphery; any area where something “sort of” exists", "sent": "The Constitution doesn’t specifically mention a right to privacy, but some experts consider this to exist in the <b>penumbra</b> of the Constitution, as a guarantee of privacy is needed in order to exercise the rights that are enumerated.\nThe rent in Chicago was too high, so they moved to a suburb in the <b>penumbra</b> of the city.", "related": "Hinterland (remote or undeveloped area)", "moreinfo": "", "hook": "pen (almost) + umbra (shadow): the fringe of a shadow.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "penury", "pos": "noun", "pron": "PEN-yer-ee", "also": "", "d1": "Extreme poverty or scarcity", "sent": "The young model married an elderly billionaire thinking she’d be set for life, but she ended up living in <b>penury</b> after her husband died and his middle-aged children held up the probate case for years, keeping her from receiving any money whatsoever.", "related": "Destitution is a synonym. Indigent (destitute), Insolvent (unable to meet one’s financial obligations, bankrupt)", "moreinfo": "", "hook": "\"penniless-ury\": extreme poverty.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "per se", "pos": "adverb", "pron": "per SAY", "also": "", "d1": "Intrinsically; by itself; in itself", "sent": "The policy isn’t sexist, <b>per se</b>, but it has had a disproportionate impact on women that deserves further study.", "related": "", "moreinfo": "From Latin, often written in italics. Per se is often used to indicate that while something isn’t naturally or the same as something else, it still has the same effect.", "hook": "the thing per se: in itself, intrinsically.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "peregrinate", "pos": "verb", "pron": "PAIR-uh-grin-ayt", "also": "", "d1": "Travel from place to place, esp. on foot", "sent": "After college, he took a year off to <b>peregrinate</b> across the country, visiting friends and seeing the forty-odd states he had never before had the chance to see.", "related": "Itinerant, peripatetic and wayfaring are all similar. Transient also means moving around, but is more associated with homeless people or those on the fringe of society (whereas itinerant is more associated with people who travel for a job).", "moreinfo": "Relatedly, the peregrine falcon is a roving or migrating bird.", "hook": "the peregrine falcon wanders: travel on foot place to place.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "perennial", "pos": "adj", "pron": "per-EN-ee-ull", "also": "", "d1": "Lasting through the years or indefinitely, enduring; recurring", "sent": "Fighting over the bathroom is a <b>perennial</b> problem in our house—there are eight of us, and we’re homeschooled, so we’re all pretty much always here.", "related": "", "moreinfo": "Perennial plants last more than one year, as opposed to annuals, which must be replanted every year. “Per” means “through” and the “ennial” part of the word is really just a variant on “annual,” so perennial literally means “through the years.”", "hook": "a perennial plant returns yearly: enduring, recurring.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "perfunctory", "pos": "adj", "pron": "per-FUNK-tuh-ree", "also": "", "d1": "Done superficially, without much care, or merely as routine", "sent": "She did a really <b>perfunctory</b> job on this Powerpoint. Sure, it has a dozen slides, but most of them just say things like “Sales—Ways to Improve” in Times New Roman on a white background. Maybe she’s planning to fill in the details later.", "related": "Cursory (quick and superficial, as in a cursory glance at the report)", "moreinfo": "“Per” means “through” and the rest of perfunctory comes from the same place as “function”—think of perfunctory as trying to get through performing a function as quickly as possible.", "hook": "a perfunctory nod: done carelessly, by rote.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "peripatetic", "pos": "adj", "pron": "pair-uh-puh-TET-ick", "also": "", "d1": "Journeying from place to place; traveling on foot", "sent": "He quit his office job to become a <b>peripatetic</b> musician, traveling from town to town playing in bars and sleeping on couches.", "related": "Itinerant and wayfaring are synonyms. Peregrinate is a verb for being peripatetic. Transient also means moving around, but is more associated with homeless people or those on the fringe of society (whereas itinerant is more associated with people who travel for a job).", "moreinfo": "“Peri” means around (as in perimeter) and the rest comes from a Latin word meaning “to walk.” Peripatetic was originally associated with Aristotle’s school of philosophers, who would walk while teaching.", "hook": "Aristotle taught while walking: roaming on foot.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "pernicious", "pos": "adj", "pron": "per-NISH-uss", "also": "", "d1": "Very harmful or destructive, deadly", "sent": "Bullying has a <b>pernicious</b> effect on the learning environment, keeping victims too intimidated to speak up and also silencing others who fear that they could be next.", "related": "Baneful is a synonym. Baleful is similar, but relates more to the idea of evil. Deleterious means harmful or unhealthful.", "moreinfo": "“Per” means “through” in the sense of “completely.” The rest of the word shares a root (for “harmful”) with noxious (harmful or morally corrupting).", "hook": "per + nic (harm): deadly, very harmful.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "perspicacious", "pos": "adj", "pron": "per-spih-CAY-shuss", "also": "", "d1": "Having penetrating insight or good discernment", "sent": "A good detective is shrewd and <b>perspicacious</b>, judging when someone is lying, noticing things the rest of us would ignore, and making connections that allow an investigation to move forward.", "related": "Keen (sharp, piercing; very perceptive or mentally sharp; intense), Acumen (keen, quick, accurate insight or judgment), Astute (shrewd, very perceptive)", "moreinfo": "“Per” means “through” and “spic/spec” means “look” (as in spectacles, spectate, etc.) Perspicacious is really just the adjective form of perspective—as in, having a really good perspective.", "hook": "sees right through (per + spic): sharply perceptive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "phalanx", "pos": "noun", "pron": "FAY-lanks or FAL-anks", "also": "", "d1": "Formation of soldiers carrying shields close together for defense; any very close group of people", "sent": "To even enter the embassy, the diplomats had to make their way through a <b>phalanx</b> of protestors.", "related": "The expression “rank and file” (or just “ranks” of people) is also a military term referring to an orderly formation of soldiers in rows and columns.", "moreinfo": "The plural phalanges refers to the bones in the hands and feet, which fit together closely, like soldiers in a phalanx.", "hook": "a phalanx of shields: a tight formation or group.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "philistine", "pos": "noun", "pron": "FILL-ist-een", "also": "", "d1": "Person deficient in or hostile to culture", "sent": "Her date was very handsome, but she decided he was an absolute <b>philistine</b> when he said that documentaries were “boring” and that the “Best Picture” Oscar should go to Resident Evil: Afterlife 3D.", "related": "Boor or Churl (rude, ill-mannered, or insensitive person; a peasant or country bumpkin), Lowbrow (not intellectual or cultivated, as in She preferred art films, but her boyfriend preferred lowbrow comedies with lots of vomit jokes).", "moreinfo": "The original Philistines were simply the people of Philistia; they warred with the Israelites and are referred to negatively in the Bible. Thus, their name has come to mean barbarians.", "hook": "a philistine scorns art: someone hostile to culture.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 14", "setNum": 14, "coll": "Advanced"}, {"w": "phlegmatic", "pos": "adj", "pron": "fleg-MAT-ick", "also": "", "d1": "Apathetic, sluggish, not easily excited or made emotional", "sent": "A <b>phlegmatic</b> child, he declined to participate in the youth soccer league. He preferred to stay at home, mostly sitting outside poking at dirt with a stick, and occasionally stopping for naptime.", "related": "Indolent, Torpid, Sluggish, Idle, Lethargic, Loafing, and Slack are all related to laziness or slowness.", "moreinfo": "The ancient Greeks thought that people were ruled by the “four humors”: blood, yellow bile, black bile, and phlegm. A person with too much phlegm would be phlegmatic; a person with too much bile would be bilious (bitter, mean), and a person ruled by blood would be sanguine (cheerful).", "hook": "ruled by the calm \"phlegm\": sluggish, unexcitable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "platitude", "pos": "noun", "pron": "PLAT-it-ood", "also": "", "d1": "A shallow, overused statement; cliche", "sent": "Everyone who knew my mother knows she was an atheist, so I can’t imagine why people at her funeral would think we’d enjoy their soppy <b>platitudes</b> about Mom’s “being in a better place now.”", "related": "Banal, Hackneyed, Inane, Insipid and Trite all mean “lacking freshness and originality, shallow.”", "moreinfo": "Platitude shares a root (“flat”) with plate and plateau. A platitude is a “flat,” stale remark.", "hook": "a tired platitude: an overused cliche.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "plebian or plebeian", "pos": "adj", "pron": "plih-BEE-un", "also": "", "d1": "Of the common people", "sent": "I toured a luxury apartment building and I laughed when I saw that the apartments had luxurious walk-in closets and whirlpool bathtubs—but hilariously tiny ovens. Because, of course, the wealthy would never do something so <b>plebian</b> as cook their own food.", "related": "Demotic (same root as democracy) is a more neutral word for “pertaining to the people.” Plebian is negative, often used in a joking way—“Oh, sorry to interrupt your studying of that opera libretto—I didn’t mean to imply that you’d do something so plebian as watch hockey with us.” Populist is generally meant in a positive way, as in championing the rights and interests of regular people.", "moreinfo": "The term plebe, used to describe the incoming class at a military school, is a variant of plebian.", "hook": "the plebs: of the common people.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "plethora", "pos": "noun", "pron": "PLETH-uh-ruh", "also": "", "d1": "Excess; excessive amount", "sent": "She had a <b>plethora</b> of excuses, but there is simply no justification for arriving to class drunk.", "related": "Surfeit or surplus (excess, overabundance)", "moreinfo": "The 1986 comedy ¡Three Amigos! popularized the word plethora—if want to remember the word plethora for life, look up “plethora of piñatas” on YouTube.", "hook": "a plethora of options: an overabundance.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "plucky", "pos": "adj", "pron": "PLUCK-ee", "also": "", "d1": "Brave, spirited", "sent": "Feminist critics have commented that today’s romantic comedies tend to feature passive, helpless female leads, whereas the romantic comedies of the 1940s featured <b>plucky</b> heroines who took the lead in cleverly solving problems.\nWhile the police hit a dead end, a band of <b>plucky</b> children was able to find the stolen bicycle.", "related": "", "moreinfo": "Plucky (along with synonym spunky) is a rather “cute” word for courageous. It is appropriate for children and for people dealing with fairly minor situations in a bold, clever way. Some find it sexist when applied to adult women in professional or otherwise serious situations; it is almost never applied to men. Plucky would be very inappropriate to describe a soldier in battle, a hero of the Civil Rights movement, etc. Use a word like courageous or intrepid instead.", "hook": "a plucky underdog: brave and spirited.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "plutocracy", "pos": "noun", "pron": "ploo-TAH-cruh-see", "also": "", "d1": "Rule by the wealthy", "sent": "There have always been rich and poor people, of course, but some argue that the U.S. is becoming a <b>plutocracy</b>, with the richest 10% controlling two-thirds of the nation’s wealth and nearly half of our Congressional representatives being millionaires.", "related": "A plutocracy might also be an oligarchy (rule by only a few).", "moreinfo": "In Greek mythology, Pluto (also known as Hades) was god of the underworld, and Plutus was god of wealth. Things got a bit confused over the years, as people used “Plutus” to mean “Pluto” as a way to make things sound a little more positive.", "hook": "pluto (wealth) + cracy (rule): rule by the rich.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "polemic", "pos": "noun", "pron": "puh-LEM-ick", "also": "", "d1": "Controversial argument, esp. one attacking a specific idea", "sent": "Laura Kipnis’ 2003 book Against Love: A <b>Polemic</b> has been called “shocking” and “scathing.” Perhaps Kipnis used the word <b>polemic</b> in the title to indicate that she’s making an extreme argument as a means of starting a debate. After all, who’s really against love?", "related": "", "moreinfo": "Polemic comes from a Greek root for “war.”", "hook": "a fierce polemic: an attacking argument.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "politic", "pos": "adj", "pron": "PAH-lit-ick", "also": "", "d1": "Shrewd, pragmatic; tactful or diplomatic", "sent": "Celebrities have to watch what they say, as even an offhand comment can end up splashed across the covers of magazines. When the starlet was asked what she thought of her ex-husband marrying the swimsuit model he left her for, she gave the <b>politic</b> reply, “I wish both of them the best.”", "related": "Expedient (suitable, proper; effective, often at the expense of ethics or other considerations)", "moreinfo": "The expression “the body politic” means the citizens of a particular government, considered as a group.", "hook": "a politic choice: shrewd and tactful.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "polyglot", "pos": "noun", "pron": "PAH-lee-glaht", "also": "", "d1": "Speaking or composed of many languages (of a person, book, etc.); a person who knows several languages", "sent": "New York’s public service announcements often take the form of <b>polyglot</b> posters in the subway, suggesting in six languages that readers give up their seats for pregnant women or those with disabilities.", "related": "", "moreinfo": "“Poly” means “many” (polygamy, polynomial) and “glot” means “tongue” (glottal, epiglottis).", "hook": "poly (many) + glot (tongue): multilingual.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "posit", "pos": "verb", "pron": "PAH-zit", "also": "", "d1": "Presume, suggest, put forward (an idea)", "sent": "For thousands of years, philosophers have thought of the self as a unified entity, but neuroscientists today <b>posit</b> the existence of a modular brain—a self that is a mix of different brain parts, with no central “coordinator.”", "related": "Postulate is a synonym. Assert and contend are stronger words for putting forth an idea as true. To posit is sometimes as weak as merely introducing an idea for discussion, rather than making a strong argument for it.", "moreinfo": "We pose a question, but we posit an idea.", "hook": "posit a theory: put forward, suggest.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "prattle", "pos": "verb", "pron": "PRAT-ull", "also": "", "d1": "Talk in an idle, simple-minded, meaningless, or foolish way; chatter, babble", "sent": "It was infuriating to listen to the boss <b>prattle</b> on about some new restaurant in town when everyone was just waiting to find out if they’d been laid off.", "related": "Prate is a synonym—actually, both words are variants of the same Middle Dutch word.", "moreinfo": "", "hook": "idle prattle: meaningless chatter.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "precipitate", "pos": "verb", "pron": "prih-SIP-it-ayt", "also": "", "d1": "Cause to happen suddenly or prematurely; fling, plunge, or hurl down", "sent": "Mr. and Mrs. Rosen had been considering a move to Florida for years, but the sudden destruction of their house in a hurricane <b>precipitated</b> their decision to finally make the move.\n“Stay away from the precipice!” said the mother to her child. “I wouldn’t want my darling son to be <b>precipitated</b> to his doom!”", "related": "Catalyst (causer of change)", "moreinfo": "Precipitation is rain, snow, or hail—water that, of course, comes down from the sky. Precipitous sometimes means “pertaining to a precipice (such as a cliff),” as in a precipitous mountain face, and sometimes means “hasty.”", "hook": "precipitate a crisis: cause suddenly, or hurl down.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "précis", "pos": "noun", "pron": "PRAY-see", "also": "", "d1": "Concise summary, abstract", "sent": "Just as scientific journals publish abstracts of their articles online (and then charge for access to the full version), the entrepreneur decided to publish a <b>précis</b> of her whitepaper online, while charging for access to the full version.", "related": "Digest (a periodical containing shortened versions of works published elsewhere), Recapitulation (summary or the act of summing up), Compendium (concise but complete summary; a list or collection)", "moreinfo": "Related to the word precise and coming from French, précis has the sense of efficiently (and precisely) expressing the essentials.", "hook": "a precis of the report: a concise summary.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "predilection", "pos": "noun", "pron": "preh-dill-ECT-shun", "also": "", "d1": "Preference, tendency or favorability towards", "sent": "She has completed teacher training allowing her to teach grades K–6, but she discovered that she really has a <b>predilection</b> for teaching kindergarten.", "related": "Penchant, Propensity, Proclivity, and Bent are all words for a preference or inclination (he has an arrogant bent about him, and a propensity to offend others).", "moreinfo": "", "hook": "a predilection for sweets: a preference, leaning.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "prescient", "pos": "adj", "pron": "PRESH-int or PRESH-ee-unt", "also": "prescience (noun)", "d1": "Having foreknowledge or foresight, seeing the future", "sent": "Mariposa swears she’s <b>prescient</b>—she thinks she sees the future in her dreams.\nThe science fiction novel, published in 1955, was strangely <b>prescient</b> —it pictures the year 2000 as having no flying cars, but a communication system known as the “interconnect,” used largely for online shopping and wasting time.", "related": "To Prognosticate or Augur is to tell the future. Prophetic means “relating to prophesy, predicting, ominous.”", "moreinfo": "Of course the “science” in prescience is the same as in the word science and omniscience (all knowingness)—the root means “to know.” Prescience is to know in advance, either supernaturally, or just by having good judgment.", "hook": "a prescient warning: foreseeing the future.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "preternatural", "pos": "adj", "pron": "pree-ter-NAT-cher-ull", "also": "", "d1": "Supernatural, exceptional", "sent": "While Tiger Woods has been mired in scandal, his <b>preternatural</b> golfing talent is still undeniable.\nDad was convinced that the house was haunted, but I doubted that the strange sounds were due to <b>preternatural</b> causes—as it turned out, we had a raccoon in the basement.", "related": "Occult can mean “supernatural, mysterious, arcane.”", "moreinfo": "From Latin—literally, “beyond nature.”", "hook": "preternatural calm: beyond natural, exceptional.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "prevaricate", "pos": "verb", "pron": "preh-VAIR-ick-ayt", "also": "", "d1": "Stray from the truth, mislead, lie", "sent": "Maryanne had been shoplifting—when her mother asked where her new clothes had come from, she <b>prevaricated</b>, vaguely suggesting that a rich friend had bought them for her.", "related": "Dissembling (misleading, concealing the truth, acting hypocritically), Disingenuous (insincere, not genuine), Equivocate (use unclear language to deceive or avoid committing to a position)", "moreinfo": "As you can see, we have many words in English that mean something just short of lying— probably because there are many situations in which we need to point out a lie, but want to do so as politely or discreetly as we can; all of the above words are less blunt than lie.", "hook": "waver from the truth: lie and evade.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "primacy", "pos": "noun", "pron": "PRY-muh-see", "also": "", "d1": "The state of being first or most important", "sent": "The conservative Senator argued that the very fabric of society depended on the <b>primacy</b> of the family, and that legislation was needed to shore up the institution of marriage.", "related": "Preeminence (superiority, the state of being more distinguished or noteworthy)", "moreinfo": "The root in primacy means “first” and also appears in prime, primal, and primate (interestingly, a primate is both a church bishop and the order of animals including humans, apes, and monkeys).", "hook": "the primacy of safety: being first or most important.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "proclivity", "pos": "noun", "pron": "pruh-CLIV-it-ee", "also": "", "d1": "Inclination, natural tendency", "sent": "After his therapist pointed out that he had a natural <b>proclivity</b> to judge people prematurely, he tried to work on that by imagining things from the other person’s point of view.", "related": "Predilection, Propensity, Penchant, and Bent are all words for a preference or inclination (He has an arrogant bent about him, and a propensity to offend others). Predisposed (having an inclination or tendency beforehand; susceptible)", "moreinfo": "Proclivity shares a Latin root (“slope”) with incline, decline, declivity, inclination, etc.", "hook": "a proclivity for risk: a natural inclination.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "prolix", "pos": "adj", "pron": "proh-LICKS or PROH-licks", "also": "prolixity (noun)", "d1": "Excessively long and wordy (of a person, piece of writing, etc.)", "sent": "My mother is incredibly verbose. She’ll tell a boring, <b>prolix</b> story for five whole minutes, and at the end, it turns out that the point was that she got a fifty cent discount on a box of spaghetti at the store.", "related": "Loquacious and Verbose are synonyms.", "moreinfo": "“Pro” means “forth” and “lix” comes from the Latin for “liquid.” Words just “pour” right out of a prolix person.", "hook": "a prolix essay: tediously long-winded.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "propagate", "pos": "verb", "pron": "PRAH-puh-gayt", "also": "", "d1": "Reproduce, spread, increase", "sent": "Hackers can take down a large computer system in days or even minutes as a virus <b>propagates</b> and infects all of the machines on a network.", "related": "Proliferate (increase or spread rapidly or excessively)", "moreinfo": "Propagate is originally about plants and is still often used regarding plants—many types of plants can be propagated from cuttings (that is, a small piece cut from a mature plant can grow into a new plant).", "hook": "propagate plants or ideas: reproduce and spread.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "propensity", "pos": "noun", "pron": "pruh-PEN-sit-ee", "also": "", "d1": "Natural inclination or tendency", "sent": "He was an introvert with a <b>propensity</b> for solitary brooding, and thus was considered a bit strange or unfriendly by the others in his dorm.", "related": "Predilection, Proclivity, Penchant, and Bent are all words for a preference or inclination (He has an affable bent about him, and a proclivity for striking up conversations with strangers).", "moreinfo": "Like its synonym penchant, this word shares a root (meaning “lean”) with pendulum and penchant. A propensity is a “leaning” towards something.", "hook": "a propensity to overthink: a natural tendency.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "prophetic", "pos": "adj", "pron": "pruh-FET-ick", "also": "", "d1": "Relating to prophesy, predicting, ominous", "sent": "While most of the country was consumed with irrational optimism about the economy, this particular journalist possessed an almost <b>prophetic</b> pessimism—not only did she predict the crash, she even predicted the month it actually happened.", "related": "Prescient (having foreknowledge or foresight, seeing the future), Prognosticate or Augur (tell the future)", "moreinfo": "", "hook": "a prophetic vision: predicting, ominous.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "propitiate", "pos": "verb", "pron": "proh-PISH-ee-ayt", "also": "", "d1": "Attempt to reconcile with, satisfy, or reduce the animosity of (a person who is angry, offended, etc.)", "sent": "The ancient Greeks would often attempt to <b>propitiate</b> angry gods by sacrificing animals to them.", "related": "Placate, Appease, Mollify, Conciliate, and Assuage are near-synonyms.", "moreinfo": "The Romans had something called a “propitiatorim,” or “place of atonement”— presumably, one would be propitiating the gods.", "hook": "propitiate the angry gods: appease and pacify.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "propitious", "pos": "adj", "pron": "proh-PISH-uss", "also": "", "d1": "Favorable, giving good signs for the future, likely to work out; kind or forgiving", "sent": "After having to postpone the game earlier in the week due to rain, the officials were pleased to see the <b>propitious</b> weather forecast. “We’ll get this game in after all,” one of them exclaimed.", "related": "Auspicious (looking as though success is likely), Opportune (suitable, convenient, occurring at an appropriate time) Memory Trick: It’s a bit confusing that propitiate means “attempt to reconcile with, satisfy, or reduce the animosity of.” Perhaps it would help to imagine that the gods have already been propitiated (the Romans were fond of sacrificing animals to gain the gods’ favor), and therefore an endeavor is propitious, or likely to be successful.", "moreinfo": "", "hook": "a propitious moment: favorable, promising.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 15", "setNum": 15, "coll": "Advanced"}, {"w": "providential", "pos": "adj", "pron": "prah-vid-ENT-chull", "also": "", "d1": "Lucky, fortunate, or relating to divine care (the idea that a deity has helped or cared for a person)", "sent": "Every time their religious sister ran out of money, help always arrived! She viewed this as God’s <b>providential</b> hand, but her family members viewed it as their always having to bail her out, and it was getting annoying.", "related": "Propitious (favorable, giving good signs for the future, likely to work out; kind or forgiving), Auspicious (looking as though success is likely)", "moreinfo": "Provident means showing foresight, being frugal or careful to provide for the future, thinking ahead in a wise way. Often this quality is attributed to God (or nature), so providence sometimes simply means God or God’s care.", "hook": "a providential rescue: lucky, as if by divine care.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "proxy", "pos": "noun", "pron": "PRAHCK-see", "also": "", "d1": "Agent, substitute, person authorized to act on behalf of another", "sent": "She was in the hospital, but certainly didn’t want to miss voting on the proposal, so she sent a <b>proxy</b> to the board meeting to vote “yes.”", "related": "Legate or Emissary (agent or official person sent to represent someone else)", "moreinfo": "Often used in the expression by proxy, as in voting by proxy.", "hook": "vote by proxy: a stand-in agent.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "puerile", "pos": "adj", "pron": "PYOO-er-ull or PYOOR-ile", "also": "", "d1": "Juvenile, immature", "sent": "The retiring film critic decried the <b>puerile</b> humor common in so many modern American movies, pointing out that the classic comedies of the ‘40s were so much smarter and less reliant on jokes about bodily functions.", "related": "Jejune (dull, childish), Sophomoric (very immature, having poor judgment)", "moreinfo": "", "hook": "puerile jokes (puer = boy): childish, immature.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "pugilism", "pos": "noun", "pron": "PYOO-juh-lizm", "also": "pugilist (noun)", "d1": "boxing, fighting with the fists", "sent": "<b>Pugilism</b> has been called “the sweet science” by some, but others feel that hitting other people in the head until they can’t get up isn’t much of a sport.", "related": "Belligerent, bellicose, truculent, and pugnacious mean combative, inclined to fighting.", "moreinfo": "Pugilism and pugnacious come from the Latin “pugnus,” for “fist.”", "hook": "pugilism in the ring: boxing with the fists.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "puissance", "pos": "noun", "pron": "PWISS-unss or PYOO-iss-unss", "also": "puissant (adj)", "d1": "Power, might", "sent": "When people asked the twenty-five year old bride what had attracted her to her commanding, sixty year old CEO husband, she replied that she had always been drawn to <b>puissance</b>. That tended to end conversations as people went to go look up “<b>puissance</b>.”", "related": "", "moreinfo": "Puissant comes through French from the same Latin root (“power”) as omnipotent (all powerful), potentate (ruler), and impotent (lacking power).", "hook": "a knight of great puissance: power, might.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "pulchritude", "pos": "noun", "pron": "PUHL-krih-tood", "also": "", "d1": "Physical beauty", "sent": "Marilyn Monroe’s mystique is based not only on her obvious <b>pulchritude</b>, but also on her mysterious death and likely dalliance with JFK.", "related": "Comeliness is a synonym. Aesthetic (concerning the appreciation of beauty or good taste, pertaining to the science of what is beautiful) Memory Trick: This word is so ugly sounding! Would you ever have guessed it meant beauty? Imagine a man telling a woman she is the epitome of pulchritude. Unless she has a very good vocabulary, it probably won’t go very well.", "moreinfo": "", "hook": "stunning pulchritude: physical beauty.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "pungent", "pos": "adj", "pron": "PUN-jent", "also": "", "d1": "Having a sharp taste or smell; biting, stimulating, sharp", "sent": "The new assistant chef received some rather <b>pungent</b> criticism from the head chef for her idea to make feta cheese soup, which the customers found much too <b>pungent</b>.", "related": "Acerbic (sour; harsh or severe), Acrid (sharp or biting, pungent), Astringent (caustic, biting, severe; a skin cleaning fluid that clears pores), Caustic (capable of corroding metal or burning the skin; very critical or sarcastic)", "moreinfo": "The Latin “pungere” means “to prick.”", "hook": "a pungent odor: sharply strong in smell or taste.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "pusillanimous", "pos": "adj", "pron": "pyoo-sill-AN-im-uss", "also": "", "d1": "Cowardly, timid", "sent": "He was so <b>pusillanimous</b> that not only was he afraid to ask his boss for a raise, he was even afraid to tell the waitress that he didn’t like sugar in his tea.", "related": "Craven (cowardly)", "moreinfo": "What an interesting origin this word has—“pullus” was Latin for a young animal, and “pusillus” added the idea of being small and weak. The root “animus” (animation, etc.) means “spirit.” Thus, a pusillanimous person has the spirit of a weak baby animal.", "hook": "pusill (tiny) + animus (spirit): cowardly and timid.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "querulous", "pos": "adj", "pron": "KWAIR-ull-uss", "also": "", "d1": "Given to complaining, grumbling", "sent": "Norma had been happy to be a grandmother, but was somewhat less happy when a <b>querulous</b> child was dropped off on her doorstep—“I don’t want to come inside,” “I don’t like sandwiches,” “It’s too cold in the bathroom.” Would the whining and moaning ever stop?", "related": "Carp (constantly complain, fret, and find fault), Petulant (unreasonably irritable or sullen), Peevish (annoyed, in a bad mood, stubborn), Cross (angry, ill-humored)", "moreinfo": "Querulous shares a root with quarrel.", "hook": "a querulous whine: peevishly complaining.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "quiescent", "pos": "adj", "pron": "kwee-ESS-unt or kwy-ESS-unt", "also": "", "d1": "Quiet, still", "sent": "After hours of moaning and shaking from his illness, the child finally exhausted himself and grew <b>quiescent</b>.", "related": "Placid or pacific (peaceful, calm, tranquil)", "moreinfo": "", "hook": "lying quiescent: quiet, still, inactive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "quixotic", "pos": "adj", "pron": "kwick-SAH-tick", "also": "", "d1": "Extremely impractical but very romantic, chivalrous, or idealistic; impulsive", "sent": "Prompted by a lesson their teacher devised for election year, the children shared what they would do if elected President. The plans were adorably <b>quixotic</b>, involving housing all the homeless in floating homes on the ocean, or teaching everyone to be nice to each other.", "related": "Rash (too hasty, acting without considering the consequences)", "moreinfo": "From Cervantes’ 1791 novel Don Quixote, about a romantic, impractical hero who becomes obsessed with books about chivalry (believing even the most ridiculous tales within the books) and famously attacks windmills he believes to be giants—hence the expression “tilting at windmills,” meaning fighting unwinnable battles or battles against imaginary foes.", "hook": "a quixotic quest (Don Quixote): wildly idealistic, impractical.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "raconteur", "pos": "noun", "pron": "rack-uhn-TOOR", "also": "", "d1": "Witty storyteller", "sent": "Miguel was quite the <b>raconteur</b>—the laughing party guests naturally congregated in a cluster around him as he held court.", "related": "A bard is a poet/storyteller—Shakespeare is often called “The Bard.” Bard also evokes images of a medieval poet traveling from town to town, accompanying himself on an instrument. A raconteur is more of a person who is fun at parties.", "moreinfo": "From the French verb for “recount,” or “tell.”", "hook": "a charming raconteur: a witty storyteller.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "rarefied", "pos": "adj", "pron": "RARE-if-ide", "also": "", "d1": "Lofty, very high up or elevated (in a metaphorical way); exclusive, select; thin, pure, or less dense (as air at the top of a mountain)", "sent": "Among the <b>rarefied</b> ranks of conference attendees, she counted two Nobel Prize Winners, a MacArthur Genius Grant winner, and Bill Gates—and that was just at one lunch table!", "related": "Elevate (raise, lift up; lift the spirits of; move up to a higher rank or status or raise up to a higher spiritual or intellectual plane), Lofty (in a high position, esp. in character, spirit, or rank), Edify (uplift, enlighten, instruct or improve in a spiritual or moral way), Winnow (separate the good from the bad, or narrow down to just the best)", "moreinfo": "", "hook": "rarefied air and circles: lofty, thin, exclusive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "reactant", "pos": "noun", "pron": "ree-ACK-tint", "also": "", "d1": "Something that reacts; a substance that undergoes a change in a chemical reaction", "sent": "The two men had been rivals since high school; when both were elected to the city council, they became <b>reactants</b> in the worsening deadlock of an already-polarized city government.", "related": "Catalyst (causer of change—or, in chemistry, a substance that causes or accelerates a reaction but is not itself changed)", "moreinfo": "", "hook": "a chemical reactant: a substance that reacts.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "recalcitrant", "pos": "adj", "pron": "rih-CAL-sih-truhnt", "also": "", "d1": "Not obedient, resisting authority, hard to manage", "sent": "As an aspiring kindergarten teacher, she had imagined days filled with giggles and singing songs about friendship—she was not prepared for a roomful of twenty <b>recalcitrant</b> children who wouldn’t even sit down, much less learn the words to “Holding Hands Around the World.”", "related": "Intractable, Intransigent, Refractory, and Obstreperous are also used to describe people who are stubborn and hard to control.", "moreinfo": "Recalcitrant comes from Latin roots meaning “to strike with the heels”—that is, to kick or kick back.", "hook": "re + calcitrant (kick back): stubbornly defiant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "recant", "pos": "verb", "pron": "rih-CANT", "also": "", "d1": "Withdraw, retract, or disavow something one has previously said, esp. formally", "sent": "For saying that the Sun and not the Earth was the center of the universe, Galileo was brought on trial for heresy, forced to <b>recant</b>, and spent the rest of his life under house arrest. Of course, a forced <b>recantation</b> doesn’t say much about whether the person really abjures his former views.", "related": "Repudiate (reject, cast off, deny that something has authority)", "moreinfo": "The root “cant” (“sing”) is also found in chant, cantor, incantation, and chanteuse (female singer).", "hook": "recant his testimony: take back what was said.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "recapitulate", "pos": "verb", "pron": "ree-cah-PIT-chull-ayt", "also": "", "d1": "Summarize, repeat in a concise way", "sent": "I’m sorry I had to leave your presentation to take a call—I only have a minute, but can you <b>recapitulate</b> what you’re proposing?", "related": "Précis (concise summary, abstract), Digest (a periodical containing shortened versions of works published elsewhere), Compendium (concise but complete summary; a list or collection)", "moreinfo": "Ever wonder where “recap” came from? Here you are! Don’t confuse recapitulate with capitulate, which means “surrender, give in.”", "hook": "re + capitulate (headings): summarize, recap.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "recondite", "pos": "adj", "pron": "RECK-un-dite or rih-CAHN-dite", "also": "", "d1": "Not easily understood, hidden, dealing with an obscure topic", "sent": "Professor Ryan’s office is full of books, every single one of which is more than 400 years old, and many of them in ancient Greek. He deals in some seriously <b>recondite</b> information.", "related": "Arcane and Esoteric are synonyms.", "moreinfo": "", "hook": "a recondite subject: obscure, hard to grasp.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "recrudescent", "pos": "adj", "pron": "ree-croo-DESS-ent", "also": "recrudescence (noun), recrudesce (verb)", "d1": "Revival, breaking out into renewed activity", "sent": "The recrudescence of his psoriasis came at the worst possible time. “Oh, great,” he said— now I’m going to be shedding skin flakes all over my new coworkers on the first day of work.", "related": "Renascent (reviving, becoming active again), Resurgent (having a revival, renewing, rising or surging again)", "moreinfo": "Recrudescent shares a root (meaning “raw”) with crudité, vegetables served raw. It seems “raw” here is meant in the sense of “harsh, bloody,” and recrudesce is generally used for the reappearance of disease. (For something positive, renaissance might be a more appropriate word).", "hook": "breaking out anew: a renewed flare-up.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "redound", "pos": "verb", "pron": "rih-DOUND", "also": "", "d1": "To have a good or bad effect, esp. as a result of a person’s efforts or actions (usually used with to, on, or upon)", "sent": "“Cramming” vocabulary words probably won’t be very effective, but studying a little every day will <b>redound</b> to your success.", "related": "Reap (harvest, get as a result of one’s effort)", "moreinfo": "Don’t confuse with rebound, to bounce back (as a basketball) or recover from illness.", "hook": "redound to your credit: come back to affect you.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "redress", "pos": "noun, verb", "pron": "rih-DRESS", "also": "", "d1": "Setting something right after a misdeed, compensation or relief for injury or wrongdoing (noun); correct, set right, remedy (verb)", "sent": "My client was an innocent victim of medical malpractice. As would anyone who had the wrong leg amputated in surgery, he is seeking financial <b>redress</b>.", "related": "Recompense (repay, reward, compensate), Requite (reciprocate, repay, or revenge)", "moreinfo": "The expression “make amends” means to ask for forgiveness or redress one’s wrongs.", "hook": "seek redress: set a wrong right, compensation.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "refractory", "pos": "adj", "pron": "rih-FRAC-tuh-ree", "also": "", "d1": "Stubbornly disobedient, hard to manage", "sent": "No matter how much job training the city gives them, <b>refractory</b> ex-criminals are simply unemployable.", "related": "Intractable, Intransigent, Recalcitrant, and Obstreperous are also used to describe people who are stubborn and hard to control.", "moreinfo": "", "hook": "a refractory child: stubbornly unmanageable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "refulgent", "pos": "adj", "pron": "rih-FULL-jent", "also": "", "d1": "Shining, radiant", "sent": "Her new engagement ring was <b>refulgent</b>—she was so happy with it. I’ll bet she polished it every night.", "related": "Burnish (polish, make smooth and lustrous), Gilded (covered with a thin layer of gold; superficially good)", "moreinfo": "Effulgent is a synonym. The rare word subfulgent means “only slightly shiny.”", "hook": "refulgent light: shining, radiant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "rejoinder", "pos": "noun", "pron": "rih-JOIN-der", "also": "", "d1": "Response or reply, esp. a witty comeback", "sent": "In retrospect, I could have come up with a better <b>rejoinder</b> than “I know you are, but what am I?” I always think of the perfect witty comeback hours after I actually needed it.", "related": "Riposte is a fencing term that has made it into common use. When an opponent thrusts (with a sword), your retaliation is a riposte. Outside of fencing, a riposte is a witty comeback or swift reply.", "moreinfo": "", "hook": "a witty rejoinder: a sharp reply.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "rend", "pos": "verb", "pron": "REND", "also": "", "d1": "Tear violently, esp. to tear one’s clothing or hair out of grief; pull apart, split, or tear away", "sent": "Many figures in the Bible rent their clothing from grief at a loved one’s death, an event that can surely <b>rend</b> one’s heart as well.", "related": "", "moreinfo": "As you can see, rend is an irregular verb; its past tense is rent.", "hook": "rend his garments: tear violently apart.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 16", "setNum": 16, "coll": "Advanced"}, {"w": "repast", "pos": "noun, verb", "pron": "rih-PAST", "also": "", "d1": "A meal (noun); to eat or feast (verb)", "sent": "After a light <b>repast</b> in a country inn, the men got back on their horses and rode away.", "related": "Comestibles (food), Gustatory (pertaining to taste)", "moreinfo": "From a Latin root for feeding, also found in pasture (where farm animals eat).", "hook": "a hearty repast: a meal.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "repertorial", "pos": "adj", "pron": "reh-per-TOR-ee-ull", "also": "", "d1": "Pertaining to a repertory or repertoire, a stock of available things or a number of theatrical performances presented regularly or in sequence", "sent": "One theater observer noted that <b>repertorial</b> community theater can tie together different plays for a repeat audience: seeing the same actor as Hamlet one night and Romeo another prompts interesting parallels between the two plays.", "related": "", "moreinfo": "Don’t confuse repertorial with reportorial, “characteristic of news reporters.”", "hook": "of a repertoire: a stock or repertory of works.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "repose", "pos": "noun", "pron": "rih-POSE", "also": "", "d1": "The act or state of resting; peacefulness, tranquility; lying dead in a grave", "sent": "Thousands of people lined up to see the prime minister’s body lying in <b>repose</b> in the capital building.\nAfter working the last two weekends, Myrna was perfectly happy spending her day off in <b>repose</b> in her living room armchair with a cup of tea and a good book.", "related": "Recumbent (lying down, reclining, resting)", "moreinfo": "Lying in repose is when a deceased person is available for public viewing.", "hook": "in peaceful repose: rest and tranquility.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "reprobate", "pos": "noun, adj", "pron": "REP-ruh-bayt", "also": "", "d1": "Disreputable, unprincipled, or damned person (noun); shameless, depraved (adj)", "sent": "The police joked that they had so many mug shots of the old <b>reprobate</b> that they could assemble them into a photography book called, “Faces of Petty Crime, 1976–2011.”", "related": "Dissolution (sinking into extreme hedonism, vice, and degradation), Roué (a dissolute, lustful man, often a womanizer)", "moreinfo": "In the original meaning, God would reprobate someone to hell. Today, a reprobate is a wrongdoer unlikely to change.", "hook": "an old reprobate: a shameless, depraved person.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "resurgent", "pos": "adj", "pron": "rih-SER-jent", "also": "", "d1": "Having a revival, renewing, rising or surging again", "sent": "Burlesque has experienced a resurgence in the last decade, as young women dress in old- fashioned finery and perform routines appropriate for the vaudeville halls or nightclubs of previous decades.", "related": "Recrudescent (revival, breaking out into renewed activity), Renascent (reviving, becoming active again)", "moreinfo": "", "hook": "a resurgent team: rising and reviving again.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "revamp", "pos": "verb, noun", "pron": "ree-VAMP", "also": "", "d1": "Renovate, redo, revise (verb); a restructuring, upgrade, etc. (noun)", "sent": "I had my whole room decorated in Twilight: Eclipse paraphernalia, so when Breaking Dawn came out, I had to <b>revamp</b> my decor.", "related": "Overhaul (repair, investigate for repairs)", "moreinfo": "Vampire puns aside, a vamp is the upper front part of a shoe. To revamp was originally to get your shoes repaired.", "hook": "revamp the design: renovate and redo.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "ribald", "pos": "adj", "pron": "RIB-uld", "also": "", "d1": "Using or relating to obscene or vulgar humor", "sent": "Nearly all limericks are based on <b>ribald</b> humor—hence, the constant rhymes with “Nantucket.”\nThe movie’s humor was so <b>ribald</b> that a PG-13 rating was assigned, and Joey’s mother covered up his eyes nearly every time a woman was on the screen.", "related": "Bawdy (vulgar or lewd, esp. for humor), Lewd (obscene or excessively lustful, as in a lewd gesture)", "moreinfo": "", "hook": "ribald humor: crude, obscene joking.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "ridden", "pos": "adj", "pron": "RID-un", "also": "", "d1": "Dominated or burdened by", "sent": "The neighborhood was <b>ridden</b> with crime.\nIn this corruption-<b>ridden</b> nation, you simply have to pay bribes if you want anything to get done.", "related": "", "moreinfo": "In the phrase disease-ridden slum, it’s pretty obvious that the meaning is bad, but actually, adding -ridden to anything makes the meaning bad. If someone said an equality-ridden society, it sounds as though that person is actually against equality!", "hook": "guilt-ridden: dominated or burdened by.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "rift", "pos": "noun", "pron": "RIFT", "also": "", "d1": "A gap or fissure (such as in rock), a break in friendly relations", "sent": "Olaf’s Swedish family was offended when he married a Norwegian girl—so offended that it caused a <b>rift</b> that lasted for decades.\nThe hikers considered the <b>rift</b> in their path, wondering if it would be possible to leap across.", "related": "Crevasse (deep fissure or crack), Feud (bitter quarrel generally lasting a long time), Estranged (alienated, as in She hasn’t spoken to her estranged father in years).", "moreinfo": "Unsurprisingly, to rift as a verb is to split open, burst, etc.", "hook": "a rift between friends: a break or gap.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "rococo", "pos": "adj", "pron": "ruh-COH-coh", "also": "", "d1": "Very elaborate and ornate (in decorating or metaphorically, as in speech and writing); relating to a highly ornate style of art and architecture in 18th century France", "sent": "Although Dot Von Derian was born in Ohio as Melissa Worshowski, she insisted on being called “Madame Von D,” and bought herself a mansion she furnished in the most <b>rococo</b> style imaginable—it was gilded cherubs and gold leafing as far as the eye could see.", "related": "Florid (reddish or rosy; flowery, showy, or excessively fancy), Byzantine (very complicated; relating to the Byzantine Empire, esp. its ornate decorating style, full of gold and religious imagery)", "moreinfo": "Look up “rococo” on Google Image Search to get the picture (very gold, very fancy!)", "hook": "rococo decor: extravagantly ornate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "rue", "pos": "noun, verb", "pron": "ROO", "also": "", "d1": "Regret, remorse (noun); to feel regret or remorse (verb)", "sent": "Movie or cartoon villains sometimes say, “You’ll <b>rue</b> the day!” What they mean is,“I will make you regret that you did what you just did.”\nThe couple broke up in high school for a foolish reason, and each hastily married another person. Twenty years later, they were still full of endless <b>rue</b> over having lost each other.", "related": "Contrite means remorseful for one’s wrongs. Penitent means remorseful for one’s sins, or a person who is remorseful.", "moreinfo": "Rue is also an acrid herb used in medicine. It is likely from this plant that the female name Rue derives (as in Rue McClanahan of The Golden Girls).", "hook": "you'll rue the day: to regret bitterly.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "ruminate", "pos": "verb", "pron": "ROO-min-ayt", "also": "", "d1": "Turn over in the mind, reflect on; chew cud (as a cow)", "sent": "Oh, I just don’t know about that… let me <b>ruminate</b> on it for a few days and I’ll get back to you.", "related": "", "moreinfo": "A cow is a ruminant—it has four stomachs and has to digest its food in stages (and thus, very slowly).", "hook": "ruminate like a cow chewing cud: ponder deeply.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "salient", "pos": "adj", "pron": "SAY-lee-uhnt", "also": "", "d1": "Obvious, standing out; projecting, protruding, jutting out", "sent": "The attack on our organization was mostly just partisan bickering, but it did have a few <b>salient</b> points that I think we should respond to.\nThe windowless prison’s side wall had only one <b>salient</b> feature, a sculpture of the state bird jutting out from the building.", "related": "Jut means to project (out from something) or stand outward or upward from the main thing, as in I snagged my clothes on a nail jutting out from the wall.", "moreinfo": "Don’t confuse with sapient, meaning “wise, having good judgment.”", "hook": "the salient point: standing out, prominent.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "sardonic", "pos": "adj", "pron": "sar-DAH-nick", "also": "", "d1": "Scornfully or ironically mocking, cynically derisive", "sent": "A <b>sardonic</b> movie critic is one thing, but a <b>sardonic</b> film professor is another—I really wish Professor Dahl wouldn’t sarcastically cut down his students the way he does cheesy horror films.\nDorothy Parker wrote <b>sardonically</b>, “If you want to know what God thinks about money, just look at the people he gave it to.”", "related": "", "moreinfo": "This origin seems too good to be true! Sardonic comes from Sardinia, the Italian island, which supposedly had a plant that could cause death by facial convulsions resembling mocking laughter.", "hook": "a sardonic smirk: bitterly mocking.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "savant", "pos": "noun", "pron": "sa-VAHNT", "also": "", "d1": "Learned person, scholar, someone admitted to membership in a scholarly field; a person with amazing mental abilities despite having a cognitive difference or disability", "sent": "The TED conferences feature <b>savants</b> and newsmakers speaking on topics of great importance to the world.\nMany people associate autism with being an “autistic <b>savant</b>,” but most people who have autism do not actually have the ability to mentally multiply a five digit number by a five digit number in five seconds, for instance.", "related": "", "moreinfo": "Marilyn vos Savant, listed in the Guiness Book of World Records for “highest IQ,” wasn’t born “vos Savant,” but didn’t simply choose a clever penname either—her maternal grandparents were named “Savant” and “vos Savant.”", "hook": "a savant of physics: a learned scholar or prodigy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "scintilla", "pos": "noun", "pron": "sin-TILL-uh", "also": "", "d1": "A tiny bit or trace", "sent": "With not one <b>scintilla</b> of food in the house, the pioneer woman resorted to desperate means, boiling weeds and even shoe leather to feed her children.", "related": "A Modicum, Iota, Mite, or Tad of something is also a small amount (as in, If you had one iota of decency, you would have come to the funeral, or I had the tailor shorten the sleeves just a tad). A Vestige is a leftover trace or remaining evidence of something that no longer exists.", "moreinfo": "Scintilla is Latin for “spark.” Spark can still be used metaphorically in a sentence where scintilla would also work—for instance, “I had not even a spark of an idea.”", "hook": "not a scintilla of doubt: a tiny trace (a scintilla of a spark).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "scurvy", "pos": "adj", "pron": "SKER-vee", "also": "", "d1": "Contemptible, mean", "sent": "Our neighbor is so <b>scurvy</b> that he deliberately broke my little brother’s bicycle because, as he said, “You kids are too loud!”", "related": "Reprobate (disreputable or unprincipled person)", "moreinfo": "Scurvy is also a disease caused by lack of vitamin C and resulting in anemia, bleeding gums, and other pretty horrible symptoms. Scurvy was common in sailors on long sea voyages in centuries past (before they figured out the cause and started taking lemons with them to sea).", "hook": "a scurvy trick: contemptible and mean.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "searchingly", "pos": "adv", "pron": "SER-ching-lee", "also": "searching (adj)", "d1": "In a searching or penetrating manner; while examining closely or probing for answers", "sent": "“I’m fired?” said Ron, looking <b>searchingly</b> at his boss. “I thought I was like a son to you.”\nBreaking up is hard to do, but the searching look of her brokenhearted soon-to-be-ex-boyfriend was just too much.", "related": "", "moreinfo": "", "hook": "look searchingly: probing, examining closely.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "secrete", "pos": "verb", "pron": "sih-CREET", "also": "", "d1": "Produce and release a substance from a cell or gland of the body for a functional purpose", "sent": "When threatened, skunks <b>secrete</b> an odor that humans consider horrible.\nThe late-night infomercial offered a pheromone perfume that promised to mimic the “attraction” hormones that humans <b>secrete</b> naturally.", "related": "Emit means send, give forth, or issue—it could be used in either sentence above or in any of a wide variety of situations (a person emits a scream, a tower emits radio waves, etc.)", "moreinfo": "Secrete is related to “secret,” from a root meaning “to set apart.” To secrete a substance, of course, is to “set it apart” or release it from the body.", "hook": "glands secrete fluid: produce and release.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "sedition", "pos": "noun", "pron": "sih-DISH-un", "also": "", "d1": "Inciting rebellion against a government, esp. speech or writing that does this", "sent": "Amnesty International regularly fights for the release of political prisoners imprisoned for <b>sedition</b>. While inciting violence is illegal in most of the world, what is considered <b>sedition</b> under many restrictive governments is what Americans consider a normal exercise of freedom of speech— for instance, writing a letter to the editor of a newspaper criticizing the government’s policies.", "related": "Incendiary (starting fire; inflaming the senses or arousing rebellion)", "moreinfo": "", "hook": "charged with sedition: inciting rebellion.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "semantic", "pos": "adj", "pron": "sih-MAN-tick", "also": "", "d1": "Relating to the different meanings of words or other symbols", "sent": "Bob said plastic surgery should be covered under the health care plan and Marion said it shouldn’t, but it turns out that their disagreement was purely <b>semantic</b>—what Bob meant was reconstructive surgery and what Marion meant was cosmetic surgery.", "related": "", "moreinfo": "Semantic comes from a Greek root for “sign.” When an argument becomes muddled due to language confusion, or when an arguer appears to be redefining a word rather than making a real point, it is common to call the person’s remarks “mere semantics” or to say, “You’re just playing semantics.”", "hook": "a semantic argument: about word meanings.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "seraphic", "pos": "adj", "pron": "sih-RAFF-ick", "also": "", "d1": "Like an angel; serene, spiritually carried off or transported", "sent": "The gospel choir looked <b>seraphic</b> in their shimmering white robes.", "related": "Cherubic means like a cherub, an angel that resembles a chubby baby or child. Cherubic is generally used to describe chubby, rosy-cheeked babies. Beatific means showing celestial happiness, spiritual joy, etc.", "moreinfo": "A seraph (in Christian writings) is a celestial being—various definitions suggest that a seraph has six wings, or is depicted as the winged head of a child.", "hook": "a seraphic smile (seraph = angel): angelic and serene.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "shard", "pos": "noun", "pron": "SHARD", "also": "", "d1": "Fragment of some brittle substance, esp. a sharp fragment of pottery, glass, etc.", "sent": "Seeing her broken plate-glass window, Mrs. Chadhury bravely grabbed a <b>shard</b> of glass to defend herself against a possible burglar.", "related": "", "moreinfo": "Shard is related to shear, a verb meaning “to cut” (also, scissors can be called shears).", "hook": "a shard of glass: a sharp fragment.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "sinecure", "pos": "noun", "pron": "SY-nih-kyoor or SIN-uh-kyoor", "also": "", "d1": "A job or position that pays while requiring little or no work", "sent": "It’s a wealthy university—it’s sort of understood that professors who relocate to campus are rewarded with <b>sinecures</b> for their spouses, whether those spouses have any qualifications or not.\nIn medieval times, a <b>sinecure</b> was a paying position for a priest but without an attachment to a parish where he would actually have to show up and do anything.", "related": "", "moreinfo": "From Latin “beneficia sine cura,” meaning “a church living without care (of souls).” That sounds pretty bad, but sometimes a sinecure is used for a good reason—for instance, a government might appoint someone (who already has a job) a title and salary for another job in order to allow that person expanded power to accomplish something.", "hook": "sine cura, \"without care\": a paid job with no real work.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "skittish", "pos": "adj", "pron": "SKIT-ish", "also": "", "d1": "Shy, fickle, uncertain, or prone to act suddenly due to nervousness; lively in a restless or excessive way", "sent": "After his first experience working with a <b>skittish</b> horse who nervously jerked around and ended up stepping on his foot, Ernest learned to wear steel-toed boots.\nThe band began with an audience of eighty college students but could see that they were <b>skittish</b>—there was a whole festival going on outside, and the student were ready to head for the door if the band wasn’t that great.", "related": "Inconstancy (fickleness, unreliability; the state of changing without good reason), Mercurial (quickly and unpredictably changing moods; fickle, flighty)", "moreinfo": "", "hook": "a skittish horse: nervous and easily spooked.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 17", "setNum": 17, "coll": "Advanced"}, {"w": "slake", "pos": "verb", "pron": "SLAYK", "also": "", "d1": "Satisfy (esp. thirst), cool, or refresh; make less active", "sent": "Having been lost for hours, the weary hikers were more than willing to <b>slake</b> their thirst in a mountain stream.\nThe teacher’s harsh, demanding attitude soon <b>slaked</b> the girls’ enthusiasm for the ballet class.", "related": "Satiate or Sate (to fully satisfy, or to go beyond satisfying to the point of excess)", "moreinfo": "Slake is related to slack (loose, negligent, lazy, weak)—if you slake your thirst, your thirst has weakened or gone away.", "hook": "slake your thirst: satisfy, quench.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "sobriquet", "pos": "noun", "pron": "SOH-brick-ay or soh-brick-AY", "also": "", "d1": "A nickname", "sent": "James Brown, often referred to with the <b>sobriquet</b> “The Godfather of Soul,” scored numerous smash hits and was also known for his feverish dancing.", "related": "An epithet can be a descriptive nickname or an “add-on” to a name—for instance, “Alexander the Great” is an epithet for Alexander III of Macedon. Epithet can also mean “insult”—a “racial epithet” is a slur and is always bad.", "moreinfo": "", "hook": "his sobriquet: a nickname.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "solecism", "pos": "noun", "pron": "SAH-liss-izm", "also": "", "d1": "Nonstandard use of grammar or words; mistake, esp. in etiquette", "sent": "“I could care less” is a <b>solecism</b>—what the speaker really means to say is “I couldn’t care less.”\nApparently, Libby had committed a <b>solecism</b> by asking a man if he wanted to dance. “In Lubbock, Texas,” said her friend, “we keep things traditional.”", "related": "Malapropism (ludicrous mistake in word use), Faux Pas (social blunder)", "moreinfo": "Solecism comes from the place name Soloi—the ancient Greeks considered the people from that region to speak in a horrible, substandard dialect.", "hook": "a grammatical solecism: a usage or etiquette blunder.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "solidarity", "pos": "noun", "pron": "sah-lid-AIR-it-ee", "also": "", "d1": "Fellowship in interests, feelings, responsibilities, etc., such as among a group of people or among classes, nations, etc.", "sent": "The governor attempted to outlaw collective bargaining by unions, but backed down once he was made aware of the union’s <b>solidarity</b> with churches and community groups across the state.", "related": "", "moreinfo": "The Polish trade union Solidarity (founded 1980) helped break out of Soviet control and bring about free elections in that country. Related to the word solid, think of solidarity as forming a solid front with your compatriots.", "hook": "workers' solidarity: unity of shared interests.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "somatic", "pos": "adj", "pron": "soh-MAT-ick", "also": "", "d1": "Of the body", "sent": "While some depression is caused by outside forces (the death of a loved one, for instance), many cases of depression have a <b>somatic</b> cause—for instance, postpartum depression can be related to hormones and physical changes associated with pregnancy and childbirth.", "related": "Psychosomatic (involving both the mind and the body—for instance, a physical illness caused by mental stress)", "moreinfo": "", "hook": "somatic symptoms: of the body.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "squalid", "pos": "adj", "pron": "SKWAH-lid", "also": "", "d1": "Disgusting, filthy, foul, extremely neglected", "sent": "Social Services removed the children from the home due to the <b>squalid</b> conditions, including rats running freely in the kitchen and spoiled food all over the house.", "related": "Sordid can mean squalid, or morally squalid, as in “The recovered junkie told a sordid tale of his time on the streets, full of every type of degradation.”", "moreinfo": "", "hook": "squalid slums: filthy and degraded.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "squelch", "pos": "verb", "pron": "SKWEL’ch", "also": "", "d1": "Crush, squash; suppress or silence; walk through ooze or in wet shoes, making a smacking or sucking sound", "sent": "The repressive government <b>squelched</b> the rebellion immediately.\nEw, I just <b>squelched</b> a slug in my bare feet!", "related": "Curb (restrain, control, rein in, as in Parliament attempted to curb the excesses of the monarchy), Quell (forcibly suppress; quiet down)", "moreinfo": "This word is imitative in origin—that is, it comes from the sound that occurs when you step on something soft and squishy.", "hook": "squelch the rumor: crush and suppress (or squish through mud).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stasis", "pos": "noun", "pron": "STAY-siss", "also": "", "d1": "Equilibrium, a state of balance or inactivity, esp. caused by equal but opposing forces", "sent": "Edie felt that her career was in <b>stasis</b>: her boss made it clear she wasn’t getting promoted, but she also couldn’t leave because of her health insurance situation.", "related": "Status Quo (existing state or condition), Stationary (not moving), Static (fixed, not moving or changing, lacking vitality)", "moreinfo": "From the Greek for “standing still.”", "hook": "held in stasis: equilibrium, a standstill.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "steeped", "pos": "adj", "pron": "STEEPT", "also": "", "d1": "Immersed (in), saturated (with)", "sent": "A person <b>steeped</b> in classic literature probably thinks about almost everything in terms of old, famous books.\nThe Met’s new campaign seeks to answer affirmatively the question of whether music lovers <b>steeped</b> in hip-hop and pop can learn to love opera.", "related": "", "moreinfo": "To steep as a verb is to soak in liquid, infuse, or saturate. A teabag steeps in hot water. In French onion soup, a large crouton steeps in broth and becomes soft.", "hook": "steeped in tradition: immersed, saturated.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stentorian", "pos": "adj", "pron": "sten-TOR-ee-un", "also": "", "d1": "Very loud and powerful (generally of a human voice)", "sent": "The substitute teacher had a hard time calling the rowdy class to order. He poked his head into the hallway and flagged down the football coach walking by, who shut down the chaos immediately with a <b>stentorian</b>, “Sit down and shut up!”", "related": "", "moreinfo": "Stentor was a Greek herald (messenger) in the Trojan War. His voice is described in the Iliad as being as loud as the voices of fifty men!", "hook": "a stentorian voice: very loud and powerful.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stigma", "pos": "noun", "pron": "STIG-muh", "also": "", "d1": "Mark of disgrace, a figurative stain or mark on someone’s reputation", "sent": "In the 1950s, bearing a child out of wedlock was severely <b>stigmatized</b>, but today in many social circles, there is no <b>stigma</b> whatsoever to unmarried parents having a child.", "related": "Pariah (social outcast, untouchable)", "moreinfo": "Stigma is sometimes used to mean stigmata, marks supernaturally appearing on hands and feet (of nuns, monks, etc.) and resembling the wounds of Christ. This happens to Patricia Arquette in the 1999 movie Stigmata. In The Scarlet Letter, the character Hester Prynne is stigmatized by having to wear the letter “A” on her chest (for “adultery”).", "hook": "the stigma of failure: a mark of disgrace.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stint", "pos": "noun, verb", "pron": "STINT", "also": "", "d1": "Period of time spent doing something, or a specific, limited amount of work (noun); to be frugal, to get by on little (verb)", "sent": "After a <b>stint</b> in combat, Jared was used to eating whatever he was given, and being sparing with the few condiments available. After watching him <b>stint</b> on ketchup, his wife said, “Honey, seriously, here you can use all you want!”", "related": "Miser, Cheapskate, Skinflint (stingy person), Frugal (economical, thrifty, not wasteful with money)", "moreinfo": "The different meanings of stint are all related the idea of a limited quantity or period—to do one’s stint is to get an assigned job done (and no more than that), and to stint on something is to limit how much is used or given.", "hook": "a stint abroad; or stint on food: a spell of work, or to be frugal.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stipulate", "pos": "verb", "pron": "STIP-yuh-layt", "also": "", "d1": "Specify; make an open demand, esp. as a condition of agreement", "sent": "Before taking the job, Owen <b>stipulated</b> in his contract that he would be able to leave early on Fridays to attend religious services.", "related": "Qualified means “modified, limited, conditional on something else” (qualified optimism means the person is part optimistic and part unsure, perhaps waiting for more information). A person who says “Yes, if you do X” is giving qualified agreement by stipulating X.", "moreinfo": "", "hook": "stipulate the terms: specify as a condition.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stratagem", "pos": "noun", "pron": "STRAT-uh-jum", "also": "", "d1": "Military maneuver to deceive or surprise; crafty scheme", "sent": "The party’s <b>stratagem</b> was to dig up a scandal on their candidate’s opponent, and then release the photos the day before the election, leaving the opponent no time to defend himself before voters took to the polls.", "related": "Ruse and Subterfuge are synonyms. Artifice (trickery, especially as part of a strategy), Finesse (use tact or diplomacy; employ a deceptive strategy), Duplicity (deceit, double- dealing, acting in two different ways for the purpose of deception), Wily (crafty, cunning)", "moreinfo": "Strategy has generally positive connotations, but stratagem implies deception. The similar scheme often has negative connotations (a plot or scam).", "hook": "a clever stratagem: a crafty scheme.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "stratum", "pos": "noun", "pron": "STRAY-tum or STRAT-um", "also": "strata (noun, plural of stratum)", "d1": "One of many layers (such as in a rock formation or in the classes of a society)", "sent": "From overhearing his rich and powerful passengers’ conversations, the chauffeur grew to despise the upper <b>stratum</b> of society.\nI love this dish—it’s like a lasagna, but with strata made of bread, eggs, and pancetta! Oh, look at the menu—it’s actually called a strata! That makes perfect sense.", "related": "Hierarchy (a ranked series; a classification of people according to rank, ability, etc.; a ruling body), Echelon (a level, rank or grade; the people at that level)", "moreinfo": "A highly stratified society is one marked by inequality, or one in which people cannot easily move from layer to layer—that is, one where the poor stay poor and the rich stay rich.", "hook": "a social stratum: one layer.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "strut", "pos": "noun", "pron": "STRUHT", "also": "", "d1": "A structural support or brace", "sent": "Looking out the window of the small biplane, Maureen could see the <b>struts</b>, the vertical connectors between the lower and upper sets of wings.", "related": "Bolster or fortify (strengthen or support), Buttress (a support against a building; to strengthen or support),", "moreinfo": "Of course, strut as a verb means to swagger or walk in a showy or pompous way, such as in a fashion show. Adam Lambert has a song called “Strut” (“Strut for me and show me what you’re working with”).", "hook": "a support strut: a structural brace.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "sublime", "pos": "adj", "pron": "sub-LIME", "also": "", "d1": "Lofty or elevated, inspiring reverence or awe; excellent, majestic; complete, utter", "sent": "She loved visiting Gothic churches, which truly filled even a nonbeliever with a sense of the <b>sublime</b>.\nIt was <b>sublime</b> idiocy that caused him to invest all his money in the market without doing any research.\nThis dinner is <b>sublime</b>! I will leave a glowing review on Yelp!", "related": "Lofty (in a high position, esp. in character, spirit, or rank), Elevate (Lift the spirits of; move up to a higher status or spiritual plane), Edify (uplift, enlighten), Rarefied (lofty, figuratively high up or elevated)", "moreinfo": "As you can see, sublime is usually positive, but sometimes it’s used a bit ironically (sublime idiocy). The related sublimate means to suppress or make socially acceptable (He sublimated his violent anger into stunning performances on the football field) —that is, to make an ugly or immoral impulse more lofty.", "hook": "a sublime view: awe-inspiringly lofty.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "subpoena", "pos": "verb, noun", "pron": "suh-PEE-nuh", "also": "", "d1": "A court order requiring a person to appear in court and give testimony", "sent": "Lea was served with a <b>subpoena</b> requiring her to testify against her former colleague.", "related": "", "moreinfo": "“Sub poena” is Latin for “under a penalty,” after the first words of a subpoena: “Under penalty of...” (meaning that, if the person does not comply, the specified punishment will be applied).", "hook": "served a subpoena: a court order to appear.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "sully", "pos": "verb", "pron": "SULL-ee", "also": "", "d1": "Make dirty, stain, tarnish, defile", "sent": "The Senator did win his campaign for re-election, but his reputation was sullied when he was photographed shaking hands with the tobacco executives who apparently bankrolled his campaign.", "related": "Adulterate (make impure), Debauch (corrupt morally), Vitiate (ruin, make faulty, corrupt), Debase (degrade; lower in quality, value, rank, etc.; lower in moral quality)", "moreinfo": "", "hook": "sully his name: stain and tarnish.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "supplant", "pos": "verb", "pron": "suh-PLANT", "also": "", "d1": "Take the place of, displace, especially through sneaky tactics", "sent": "In the 1950s, many people took cod liver oil as a health supplement. Today, fish oil capsules and flaxseed oil have <b>supplanted</b> the smelly old standby our grandparents used.\nHe did achieve his dream of becoming CEO, but only after <b>supplanting</b> our previous CEO by wresting control while she was battling cancer.", "related": "Outstrip (surpass, exceed; be larger or better than; leave behind), Overshadow (cast a shadow over, make to seem less important), Supersede (replace or cause to be set aside), Eclipse (obscure, darken, make less important)", "moreinfo": "From the Latin for “to trip up” (“planta” meant the sole of the foot).", "hook": "supplant the rival: displace and take over.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "supposition", "pos": "noun", "pron": "suh-puh-ZISH-un", "also": "", "d1": "Assumption, hypothesis, something that has been supposed", "sent": "In order to test our <b>supposition</b> that customers will buy our product if they associate it with celebrities, let’s send free samples to some popular young starlets, track mentions in the press, and see if our sales increase accordingly.", "related": "Conjecture (educated guess, speculation, opinion formed with incomplete information)", "moreinfo": "", "hook": "a mere supposition: an assumption.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "surly", "pos": "adj", "pron": "SER-lee", "also": "", "d1": "Bad-tempered, hostile, unfriendly, or rude", "sent": "This diner is terrible. My eggs are overcooked, and our <b>surly</b> waitress actually told me, “If you don’t like it, scram.”", "related": "Curmudgeon (bad-tempered, difficult person; grouch), Crotchety (grouchy, picky, given to odd notions), Cantankerous (disagreeable, contentious), Crank (an unbalanced person who is fanatical about a private, generally petty cause)", "moreinfo": "Surly comes from “sir” and originally meant “lordly, acting like a nobleman.” Today’s meaning is surely still in line with the behavior of many noblemen towards their servants.", "hook": "a surly clerk: rude and bad-tempered.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "surrogate", "pos": "noun, adj", "pron": "SER-uh-git or SER-uh-gayt", "also": "", "d1": "Substitute, person who acts for another (noun); acting as a replacement (adj)", "sent": "A study found that baby monkeys, once separated from their mothers, preferred a <b>surrogate</b> mother made of cloth to a less comforting, rigid monkey doll, even when induced with treats to change their behavior.", "related": "Proxy (agent, substitute, person authorized to act on behalf of another)", "moreinfo": "A surrogate mother carries a child for another woman (generally, the child is not biologically related to the surrogate—the intended parent or egg donor supplies genetic material).", "hook": "a surrogate stands in: a substitute.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "sybarite", "pos": "noun", "pron": "SIB-uh-rite", "also": "", "d1": "Person devoted to pleasure and luxury", "sent": "The reality show about Beverly Hills “housewives” portrayed wealthy <b>sybarites</b> who actually seemed to be pursuing champagne and Pilates full-time.", "related": "Voluptuary is a synonym. A hedonist is a pleasure-seeker.", "moreinfo": "From the Greek place name Sybaris—the original Sybarites were renowned for living in luxury.", "hook": "a pampered sybarite (from luxurious Sybaris): a pleasure-lover.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "symbiosis", "pos": "noun", "pron": "sim-bee-OH-siss or sim-bye-OH-siss", "also": "symbiotic (adj)", "d1": "Mutually dependent relationship between two organisms, people, groups, etc.", "sent": "In biology, one example of <b>symbiosis</b> is when a small creature feeds off bugs that live on a larger creature—thus protecting the larger creature from discomfort and possibly disease.\nAlthough some celebrities complain about paparazzi, many have a symbiotic relationship with those same intrusive photographers – the paparazzi need to get paid, and the celebs need the photos to stay in the news.", "related": "", "moreinfo": "The root “sym/syn” means “together” and also appears in synchronized and sympathy. “Bio” means “life.”", "hook": "a symbiosis of species: a mutually dependent relationship.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 18", "setNum": 18, "coll": "Advanced"}, {"w": "synoptic", "pos": "adj", "pron": "sin-OP-tick", "also": "", "d1": "Relating to a synopsis or summary; giving a general view", "sent": "The movie studio had interns read screenplays and write up <b>synoptic</b> outlines for the executives to review.", "related": "Digest (a periodical containing shortened versions of works published elsewhere), Recapitulation (summary or the act of summing up), Précis (summary or abstract), Compendium (concise but complete summary; a list or collection)", "moreinfo": "The root “sym/syn” means “together” and “op” comes from a Latin root for “eye” (optometrist, optical, ocular, myopia). Thus, synoptic literally means “see all together,” which is what a good summary allows you to do.", "hook": "a synoptic overview: giving a summary or general view.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "syntax", "pos": "adj", "pron": "SIN-tacks", "also": "syntactical (adj)", "d1": "The rules governing grammar and how words join to make sentences (or how words and symbols join in writing computer code), the study of these rules, or any system or orderly arrangement", "sent": "Now that my linguistics class is studying <b>syntax</b>, it makes a little more sense when my computer flashes “<b>SYNTAX</b> ERROR” at me.\nAnyone learning a language is bound to make syntactical mistakes—even if he or she knows the appropriate vocabulary, it is still difficult to assemble the words perfectly.", "related": "", "moreinfo": "The root “taxis” (arrangement) also gives us taxonomy (the science of classification, such as in biology).", "hook": "sentence syntax: the rules of word arrangement.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "tawdry", "pos": "adj", "pron": "TAW-dree", "also": "", "d1": "Gaudy, cheap or cheap-looking; indecent", "sent": "Tara modeled her prom look after something she saw in a Pussycat Dolls video. Her mom didn’t care for it, but her grandmother found it downright <b>tawdry</b>.", "related": "Showy means showing off and could be good or bad (a showy car). Garish refers to something much too bright, vivid, or fancy (makeup that looks okay in a nightclub looks garish in the office). Gaudy items stand out in a cheap, tasteless, or overly colorful way (wearing too much big jewelry looks gaudy). Meretricious means attractive in a vulgar or flashy way, tawdry; deceptive.", "moreinfo": "This etymology is ridiculous—tawdry comes from a mispronun-ciation of “St. Audrey,” as in “St. Audrey’s lace,” a lace necktie. The real St. Audrey died in 679 of throat cancer, supposedly because of her love of necklaces.", "hook": "tawdry trinkets: gaudy and cheap.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "tendentious", "pos": "adj", "pron": "ten-DEN-chuss", "also": "", "d1": "Marked by a strong point of view, biased", "sent": "It’s hard to become absorbed in the world of a fantasy novel when the author is so <b>tendentious</b>—the planet of Xerxon is clearly meant to mimic the United States, and the author’s politics intrude on the story on every page.", "related": "Partisan (partial to a particular party, group, etc., esp. in a biased, emotional way), Bigot (obstinately prejudiced person)", "moreinfo": "A tendentious person is always tending towards some particular thing.", "hook": "a tendentious article: pushing a biased agenda.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "terrestrial", "pos": "adj", "pron": "tih-RESS-tree-ull", "also": "", "d1": "Relating to the Earth or to land; worldly", "sent": "Mr. and Mrs. Daruza were certain they had seen a UFO, plus aliens running around in the night. What they really saw was an especially dense flock of birds in the air, and some mundane, <b>terrestrial</b> animals on the ground.", "related": "", "moreinfo": "The root “terra” (Earth) also gives us extra-terrestrial (space alien), terrarium (closed container garden for plants and small animals), terrine (earthenware food dish), and terra firma (solid ground).", "hook": "terrestrial life: of the Earth or land.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "terse", "pos": "adj", "pron": "TERSS", "also": "", "d1": "Concise, brief and to the point (sometimes to the point of rudeness)", "sent": "Hoping to talk to her doctor at length about her condition, she was disappointed to be treated so <b>tersely</b> by a doctor who simply renewed her prescription and disappeared.", "related": "Curt and brusque also mean rudely abrupt or brief. (Terse is often negative, but doesn’t have to be).", "moreinfo": "", "hook": "a terse reply: curt and brief.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "toady", "pos": "noun", "pron": "TOH-dee", "also": "", "d1": "Someone who flatters or acts in a servile manner for self-serving reasons", "sent": "Look at that <b>toady</b>, sucking up and offering to do the boss’s Christmas shopping for his kids. Gross.", "related": "Lackey, Sycophant, and Myrmidon are synonyms. Fawn means to try to please in a submissive way. Obsequious means “servile, very compliant, fawning.” Truckle means to act subserviently.", "moreinfo": "Toady comes from “toad-eater,” after magicians’ assistants who would eat supposedly poisonous toads so the magician could show off his ability to magically expel the poison. Toadeat used to mean “do any degrading thing for your boss,” but today you can use toady as a verb (or toady up to someone) for this purpose.", "hook": "a sniveling toady: a flattering yes-man.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "token", "pos": "noun, adj", "pron": "TOH-kin", "also": "tokenism (noun)", "d1": "Sign, symbol, mark, badge; souvenir, memento; coin-like disk used as currency for subways, arcade games, etc.; sample, or person, thing, idea taken to represent an entire group (noun); of very little or merely symbolic value (adj)", "sent": "I am starting to realize that this law firm hired me to be its <b>token</b> woman. There I am, smiling in all the ads—but I never actually get to work on important cases.\nHollywood movies are often guilty of <b>tokenism</b>—many have exactly one black character (the “<b>token</b> minority”), often present to give advice to the (usually white) main characters.\nI am giving you this “Best Friends Forever” necklace as a <b>token</b> of our friendship.", "related": "By the same token is an expression that means the speaker will then say something based on the same evidence he or she used for what was previously said. “As a libertarian, he wants to abolish the IRS. By the same token, he wants drugs legalized.”", "moreinfo": "", "hook": "a token gesture: merely symbolic, small.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "tome", "pos": "noun", "pron": "TOHM", "also": "", "d1": "Large or scholarly book; one of the volumes in a set of several books", "sent": "When she discovered that the books she needed for her paper were in the university’s online system, she ended up lugging some truly impressive <b>tomes</b> back from the library—she actually had to stop and rest twice on the way home.", "related": "A magnum opus is an author’s greatest work (although it doesn’t have to be large).", "moreinfo": "", "hook": "a weighty tome: a big scholarly book.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "tortuous", "pos": "adj", "pron": "TOR-choo-uss", "also": "", "d1": "Twisting, winding, complex; devious, not straightforward", "sent": "If I can follow your <b>tortuous</b> logic, you’re saying that people who want the new law protecting the environment are actually hurting the environment because the majority of people deliberately do the opposite of laws? What?\nThe children found the <b>tortuous</b> path of the roller coaster both terrifying and exciting.", "related": "Convoluted (having many overlapping folds or coils, as certain kinds of seashells; intricate, complex)—also often used to describe “twisty” reasoning, as in the first sentence above.", "moreinfo": "Don’t confuse with torturous, meaning relating to torture or the type of pain caused by torture.", "hook": "a tortuous path: twisting and convoluted (not torturous).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "transgression", "pos": "noun", "pron": "tranz-GRESH-un", "also": "transgress (verb)", "d1": "Violation of a law, moral rule, order, etc.; sin", "sent": "His <b>transgression</b> was so serious that his family disowned him: no one would be visiting him in prison.", "related": "Contravene (violate, act counter to, oppose), Err (be mistaken, sin)", "moreinfo": "Transgress, from Latin, is literally “to step across,” similar to the expression “cross the line,” as in You’ve really crossed the line this time. The “line,” of course, is a rule, principle, etc.", "hook": "a transgression of the law: a violation or sin.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "travesty", "pos": "noun", "pron": "TRAV-est-ee", "also": "", "d1": "Exaggerated, debased, or grotesque imitation", "sent": "That Saturday Night Live sketch was a pretty good <b>travesty</b> of the election scandal.\nYou call that a sales presentation? What you just did in front of our clients was a <b>travesty</b>! I can’t believe you lost what was supposed to be an easy sale.", "related": "Farce (a humorous play, or a mockery). Burlesque is a synonym (the original meaning related a mocking imitation or caricature used for ridicule).", "moreinfo": "The “tra” in “travesty” is the same as “trans,” meaning “across.” The “vest” means “clothing.” These two Latin roots came together in Italian to mean something like “disguise,” which is an important part of creating a satirical play, for instance.", "hook": "a travesty of justice: a grotesque mockery.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "treacherous", "pos": "adj", "pron": "TRETCH-er-uss", "also": "treachery (noun)", "d1": "Betraying trust, not faithful or trustworthy; not dependable; dangerous or deceptive", "sent": "Betraying one’s country for money is the most base of acts—his treachery cost the lives of several soldiers whom he had pledged to fight alongside.\nThe small boat was capsized in the <b>treacherous</b> waters.", "related": "Perfidy (disloyalty, treachery), Apostate (person who deserts a party, cause, religion, etc.), Recreant (coward or deserter), Quisling (person who betrays his country by aiding an invader)", "moreinfo": "From the Old French “trechier,” meaning “cheat or trick.”", "hook": "a treacherous ally: betraying and unreliable, or dangerous.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "trenchant", "pos": "adj", "pron": "TREN-chint", "also": "", "d1": "forceful or vigorous, effective, keen; caustic, sharp", "sent": "The school’s <b>trenchant</b> new anti-truancy policy immediately increased class attendance by a noticeable margin.\nClaudia would have gone on making excuses for hours had Juan not <b>trenchantly</b> stepped in and said, “You want to quit, right?” “Yes!” she said, quite relieved.", "related": "Keen (sharp, piercing; very perceptive or mentally sharp)", "moreinfo": "Trenchant is related to trench (a ditch)—the connection is a root meaning “to cut” (either literally or figuratively). A trenchant remark can cut someone in the sense of hurting feelings, or can “cut through all the junk” to get to the point.", "hook": "a trenchant critique: sharp and incisive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "truculent", "pos": "adj", "pron": "TRUCK-yuh-lent", "also": "", "d1": "Fierce, cruel, savage; belligerent", "sent": "That guy is too <b>truculent</b> to work in customer service—when the customers are already angry, the last thing this store needs is someone prone to blow up at any moment!\nThe honey badger is a <b>truculent</b> hunter—it can and will eat anything, and sometimes tortures its prey before eating it.", "related": "Belligerent, Bellicose, and Pugnacious mean combative, inclined to fighting. Sanguinary means bloodthirsty. Minatory and Baleful mean menacing or threatening.", "moreinfo": "", "hook": "a truculent bully: fiercely aggressive.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "tumultuous", "pos": "adj", "pron": "tuh-MULT-choo-uss", "also": "tumult (noun)", "d1": "Riotous, violently agitated, marked by disturbance or uproar; noisy, chaotic", "sent": "Poland’s <b>tumultuous</b> history includes a Nazi invasion, a period of Soviet rule, and, well before that, over 120 years during which it was partitioned by Russia, Prussia, and Austria and simply didn’t exist.\nShe had been enjoying the game, but lost her hat, left earring, and keys in the tumult that resulted when fans went crazy over a referee’s call.", "related": "Turbid means relating to water that is choppy or has been stirred up (and thus “muddy” or “unclear, hard to understand”) or can mean turbulent (and would be appropriate in the sentence above).", "moreinfo": "", "hook": "a tumultuous crowd: riotous and chaotic.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "turgid", "pos": "adj", "pron": "TER-jid", "also": "", "d1": "Swollen, inflated; or, metaphorically “inflated,” such as in overblown, pompous speech", "sent": "His prose was so <b>turgid</b> he used the phrase “synchronous repast” to mean a lunch break.\nJimmy carefully carried the <b>turgid</b> water balloons to the balcony, ready for a serious splash attack on members of the rival fraternity.", "related": "Tumid (synonym), Distend (swell, expand), Balloon (swell or puff out; increase rapidly)", "moreinfo": "Don’t confuse turgid with turbid (turbulent), tepid (lukewarm), or torpid (sluggish).", "hook": "turgid prose: swollen, pompously overblown.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "turpitude", "pos": "noun", "pron": "TER-pit-ood", "also": "", "d1": "Depravity, baseness of character, corrupt or depraved acts", "sent": "Worried about her grandson’s <b>turpitude</b>—as evinced by his constant detentions and a three- day stay in a juvenile jail—Mrs. Worthington offered to pay for military school.\nIt’s hard to fathom the kind of <b>turpitude</b> required to make a movie that could get banned in modern-day Europe! When I read the screenplay, I nearly threw up.", "related": "Base (morally low, mean, dishonorable; of little or no value; crude and unrefined; counterfeit), Debase (lower or reduce in quality or dignity)", "moreinfo": "Often used in the phrase “moral turpitude,” a legal term that describes depraved behavior.", "hook": "moral turpitude: depravity and baseness.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "tyro", "pos": "noun", "pron": "TY-roh", "also": "", "d1": "Beginner", "sent": "Kenneth felt called to work as a missionary, but he was really a <b>tyro</b> in the field, and was unprepared for many of the questions people asked him.", "related": "Novice (synonym), Neophyte (beginner, novice; person newly converted to a religion), Dilettante (person who takes up an art or activity for amusement only or in a superficial way)", "moreinfo": "", "hook": "a tyro at chess: a beginner.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "umbrage", "pos": "noun", "pron": "UM-bridge", "also": "", "d1": "Offense or annoyance (usually as take umbrage, meaning become offended or annoyed)", "sent": "With thirty years’ experience in the field and quite recent successes on a variety of projects, the executive understandably took <b>umbrage</b> when a coworker suggested that he was good to have around to remind others of “ancient history.”", "related": "Pique also means anger or irritate. Note that to pique (that is, stimulate) someone’s interest is positive, but to pique a person is always bad.", "moreinfo": "", "hook": "take umbrage (umbra = shadow cast over you): take offense.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "unconscionable", "pos": "adj", "pron": "un-CAHN-shun-uh-bull", "also": "", "d1": "Not guided by conscience; morally wrong, unjust, unreasonable", "sent": "It is <b>unconscionable</b> that you would deny your sister a bone marrow transplant knowing that you’re the only person in the family who’s a match.", "related": "Unscrupulous or unprincipled also mean not guided by moral rules.", "moreinfo": "", "hook": "no conscience at all: outrageously wrong, unreasonable.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "unsparing", "pos": "adj", "pron": "un-SPAIR-ing", "also": "", "d1": "Generous, lavish (as in not sparing any help or gifts to others); unmerciful, harsh (as in not sparing any criticism)", "sent": "The mother was <b>unsparing</b> in praising her son—so he was in for quite a shock when his new teacher told him his work was substandard.", "related": "Acerbic, Acrid, Astringent, Caustic are all words that literally have to do with bitterness, burning, corroding, etc., and can be metaphorically used to describe harshness (unsparing condemnation, caustic condemnation, etc.)", "moreinfo": "To spare can mean to treat with mercy, hold back, or refrain from doing (the kidnapper spared the victim’s life, the father spared no expense on his daughter’s Sweet Sixteen, etc.)", "hook": "spares nothing: harshly unmerciful, or very generous.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "untempered", "pos": "adj", "pron": "un-TEM-perd", "also": "", "d1": "Not toned down; not moderated, controlled, or counterbalanced", "sent": "The report was an <b>untempered</b> condemnation of the company’s practices—the investigators didn’t have a single good thing to say.", "related": "Qualified means “modified, limited, conditional on something else” (qualified optimism means the person is part optimistic and part unsure, perhaps waiting for more information). Thus unqualified can mean untempered —that is, not limited or restrained. If your boss gives unqualified approval for your plan, you can do whatever you want.", "moreinfo": "To temper is to moderate, soften, or tone down, or to make less intense, esp. by mixing something good with something bad. Of course, temper as a noun means a person’s state of mind or tendency to anger.", "hook": "not tempered down: unmoderated, uncontrolled.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "upbraid", "pos": "verb", "pron": "up-BRAID", "also": "", "d1": "Find fault with, criticize or scold severely", "sent": "I’m not surprised they got divorced—you can’t <b>upbraid</b> someone every time he forgets to put a water glass in the sink and then expect him to stick around.", "related": "Admonish means scold or mildly criticize. Reprove, Reproach, Reprimand, Rebuke, Excoriate, and Castigate are all words for criticizing or scolding more harshly. Censure means strong disapproval or official reprimand.", "moreinfo": "Upbraid is related to braid (intertwined hair)—the root relates to twisting, darting, or being quick (such as in battle). The idea is that, when you upbraid someone, you bring up his or her faults quickly and sharply—almost as a weapon. Of course, now we’re imagining braided hair twisting like a sneaky enemy.", "hook": "upbraid the slacker: scold severely.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "usury", "pos": "noun", "pron": "YOO-zher-ee", "also": "", "d1": "Charging interest on a loan, esp. charging illegally high or excessive interest", "sent": "I can’t see how that payday lending place is even legal—a person borrowing $100 will end up paying over $150 interest in just a few months! Isn’t that <b>usury</b>? I don’t know how that place is skirting the law.", "related": "", "moreinfo": "Usury is always bad. Whether it means simply charging interest or charging way too much depends on the time and place. In medieval times when all moneylending was illegal, usury meant any charging of interest; today, usury laws specify exactly how much interest it’s allowable to charge.", "hook": "charged with usury: lending at excessive interest.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 19", "setNum": 19, "coll": "Advanced"}, {"w": "vanguard", "pos": "noun", "pron": "VAN-gard", "also": "", "d1": "Leading units at the front of an army; leaders in a trend or movement, people on the “cutting edge;” the forefront of a trend or movement", "sent": "While Google has won the search engine wars, in 1994, Yahoo was on the <b>vanguard</b> of search technology.", "related": "", "moreinfo": "The avant-garde (French for in front of the guard) were the leading soldiers at the front of an army. Vanguard is derived from avant-garde and means the same thing. Metaphorically, the avant-garde (noun or adjective) or vanguard (noun) are innovators, those “ahead of their time.” Sometimes, the avant-garde seems a little crazy at first. For example, She arrived at the mixer in a dress that was a little avant-garde for the otherwise conservative Yale Club—she would have looked more appropriate at an art gallery or Lady Gaga concert.", "hook": "the vanguard of the movement: the leading edge.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "variegated", "pos": "adj", "pron": "VAIR-ee-uh-gay-ted", "also": "", "d1": "Varied in color, having multicolored patches or spots; diverse", "sent": "Unusually, the bridesmaids’ dresses were boldly <b>variegated</b>, having many different colors. The bride reasoned that the dresses could be worn again —“Rainbow goes with anything!” she said. The bridesmaids privately agreed that they would never again wear those dresses as long as they lived.", "related": "Myriad (innumerable, existing in abundance; diverse), Heterogeneous (different in type, incongruous; composed of different types of elements)", "moreinfo": "In biology, variegation refers to different colored zones in the leaves of plants. Of course, the “vari” part is the same as in various, so it shouldn’t be hard to figure out a synonym like varicolored.", "hook": "variegated leaves: multicolored and varied.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "verdant", "pos": "adj", "pron": "VER-duhnt", "also": "", "d1": "Green, such as with vegetation, plants, grass, etc.; young and inexperienced", "sent": "Having grown up in Ethiopia, Dabir loved the lushness of the <b>verdant</b> forests in rainy Oregon.\nThe first-year associate was a little too <b>verdant</b> to be assigned to the big case.", "related": "Primaveral or Vernal (relating to the spring; fresh, youthful)", "moreinfo": "Verdant is, of course, related to the Spanish verde and French vert for “green.” The color green is also used figuratively—saying someone is “green” (much like a new spring plant) or “wet behind the ears” (a reference to just being born) means the person is inexperienced.", "hook": "verde/verdure (green): lush with plants; or young and green (inexperienced).", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "verisimilar", "pos": "adj", "pron": "ver-uh-SIM-ill-er", "also": "", "d1": "Having the appearance of truth, probable", "sent": "It’s a <b>verisimilar</b> story, sure, but where’s the proof?", "related": "Feasible (possible; logical or likely; suitable), Plausible (credible, having the appearance of truth)", "moreinfo": "The root “ver” means “true” and appears in verify, veracious (truthful), aver (claim, assert), and verity or veracity (truth).", "hook": "has verisimilitude: having the appearance of truth.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vernal", "pos": "adj", "pron": "VER-null", "also": "", "d1": "Relating to the spring; fresh, youthful", "sent": "Alma’s favorite part of gardening was the <b>vernal</b> reawakening that followed a frozen winter.", "related": "Primaveral is a synonym. (The dish pasta primavera is full of vegetables—that is, “spring pasta”).", "moreinfo": "The vernal equinox is a moment in spring at which the Sun is directly over the equator; this is associated with a change of seasons.", "hook": "the vernal equinox: of spring, fresh.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vestige", "pos": "noun", "pron": "VEST-idge", "also": "", "d1": "Trace or sign of something that once existed", "sent": "They hadn’t officially broken up, but she felt their relationship was running on fumes—that only <b>vestiges</b> of their former affection remained.", "related": "Scintilla (a tiny bit or trace), Residue (remainder, leftover part after something has been removed)", "moreinfo": "Vestigial features in biology are those left over from a previous stage of evolution—for instance, the hind limbs of whales and snakes, and the tailbone in humans. Thus, when a baby is born with a protruding tailbone, it is called a vestigial tail (as featured in the 2001 film Shallow Hal).", "hook": "a vestige of the past: a trace or remnant.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vex", "pos": "verb", "pron": "VECKS", "also": "vexation (noun)", "d1": "Annoy or bother; puzzle or distress", "sent": "“Don’t <b>vex</b> me,” said the nanny. “Behave, or I’ll tell your parents.”\nShe was totally <b>vexed</b> by the crossword clue—9 letters, starting with “b,” meaning “person whose socks are either scratchy or imbued with magical powers.” What?", "related": "Irk (synonym), Nettle (irritate, sting, or annoy)", "moreinfo": "Related to vehicle, vex comes from a root for “to convey”—transportation wasn’t so smooth in Roman times, so imagine the vexation that might result from being pulled in a cart by horses over lots of rocks.", "hook": "vexed and bothered: annoy or puzzle.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "via", "pos": "preposition", "pron": "VY-uh or VEE-uh", "also": "", "d1": "Through, by means of, by way of (by a route that goes through or touches)", "sent": "We will be flying to Russia <b>via</b> Frankfurt.\nMany of the students at our college got here <b>via</b> special programs that assist low-income students in preparing for college.", "related": "Per can also be used in this way. The most common use of per is “for each,” as in, “We will need one sandwich per child.” However, per may also mean “by means of” or “according to.” I have delivered the package per your instructions.", "moreinfo": "Via is Latin for “way, road, channel.” This root also appears in viaduct, a bridge or series of bridges, especially carrying a road or railway over water, a valley, etc.", "hook": "travel via Chicago: by way of.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vicissitude", "pos": "noun", "pron": "viss-ISS-it-ood", "also": "", "d1": "Changes or variations over time, esp. regular changes from one thing to another", "sent": "While she scrubbed pots and pans, she pondered the <b>vicissitudes</b> of life —she once had a house full of servants, and now was a maid herself.", "related": "Vagaries (unpredictable or erratic actions or occurrences, as in the vagaries of the weather)", "moreinfo": "", "hook": "the vicissitudes of life: ups and downs, changes over time.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vim", "pos": "noun", "pron": "VIM", "also": "", "d1": "Pep, enthusiasm, vitality, lively spirit", "sent": "“I’m old, not dead!” said Grandpa Albert, full of <b>vim</b> and ready for his first bungee jump.", "related": "Vigor (synonym), Verve (vigor, spirit, liveliness), Sprightly (vivacious, full of life)", "moreinfo": "Vim is usually heard in the expression “vim and vigor.” Like so many of these “two-part” expressions (hale and hardy, for instance), the two words are more or less synonyms, and thus the expression is a bit redundant.", "hook": "full of vim and vigor: pep and energy.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "virulent", "pos": "adj", "pron": "VEER-yuh-lent", "also": "", "d1": "Extremely infectious, poisonous, etc.; hateful, bitterly hostile", "sent": "Racism is a <b>virulent</b> force that corrupts schools, workplaces, and the basic machinery of democracy.\nDiscipline in the classroom is one thing, but the teacher’s virulence towards misbehaving students was enough to get her suspended from teaching.", "related": "Pervasive (tending to spread throughout), Pathogenic (capable of producing disease)", "moreinfo": "The original meaning of the root “virus” was “poison” (what we call viruses weren’t discovered until 1898).", "hook": "a virulent virus: extremely infectious, or bitterly hostile.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "viscid or viscous", "pos": "adj", "pron": "VISS-id / VISS-cuss", "also": "", "d1": "Thick, adhesive, or covered in something sticky", "sent": "Ugh, what did you spill on this floor? It’s too <b>viscous</b> to be absorbed by these paper towels. Is this hair conditioner?\nTeaching a troop of Cub Scouts to make maple syrup means cleaning the <b>viscid</b> substance off uniforms, boys, and every other object those boys touch.", "related": "Adhere (stick to, such as with glue, or to a plan or belief)", "moreinfo": "", "hook": "viscous syrup: thick and sticky.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vitriol", "pos": "noun", "pron": "VIT-tree-ohl", "also": "vitriolic (adj)", "d1": "Something highly caustic, such as criticism (literally, one of a number of chemicals including sulfuric acid)", "sent": "After another embarrassing loss, the team’s shortstop was full of <b>vitriol</b> for the coach who had led them to their worst season in history.", "related": "Caustic (capable or burning or corroding; extremely critical or sarcastic), Acrimony (bitterness, animosity), Contumely (contemptuous treatment or a humiliating insult)", "moreinfo": "", "hook": "spewing vitriol (sulfuric acid): scathing, caustic bitterness.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "vociferous", "pos": "adj", "pron": "voh-SIFF-er-uss", "also": "", "d1": "Noisily crying out, as in protest", "sent": "He has always been a <b>vociferous</b> opponent of the estate tax, appearing on numerous news programs to rail against “double taxation.”", "related": "Stentorian (loud), Clamor (vociferous uproar, as from a crowd)", "moreinfo": "The root “voc” (from “vox”) means “voice” and also occurs in vocal, equivocal, and vox populi (the voice of the people).", "hook": "a vociferous protest (voc = voice): loudly crying out.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "voluble", "pos": "adj", "pron": "VAHL-yuh-bull", "also": "", "d1": "Easily fluent in regards to speech", "sent": "The journalist’s new book is a <b>voluble</b> tome, covering three centuries of history with numerous flowing, almost conversational asides into the scientific discoveries and cultural advances of various time periods.", "related": "Loquacious, Prolix, and Verbose mean “talkative, wordy.” Glib means “fluent in speaking” in a bad way that suggests superficiality or insincerity.", "moreinfo": "From the same root (“volvere,” meaning “to roll”) as revolve—the words just “roll” right out of a voluble person.", "hook": "a voluble talker: effortlessly fluent, talkative.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "wan", "pos": "adj", "pron": "WAHN", "also": "", "d1": "Unnaturally pale, or showing some other indication of sickness, unhappiness, etc.; weak, lacking forcefulness", "sent": "Are you okay? You’re looking <b>wan</b>.\nBryan’s <b>wan</b> attempt at asking for a raise was easily brushed off by his boss.", "related": "Pallid (abnormally pale, lacking color or vitality), Sallow (sickly-yellow in color)", "moreinfo": "A wan smile is a weak, forced smile that people use to pretend they’re okay when they’re not.", "hook": "a wan smile: pale, sickly, weak.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "wanton", "pos": "adj", "pron": "WAHN-tuhn", "also": "", "d1": "Reckless, vicious, without regard for what is right; unjustifiable, deliberately done for no reason at all; sexually unrestrained or excessively luxurious", "sent": "Kids do like to play pranks on Halloween, but driving an SUV into people’s mailboxes isn’t a prank—it’s <b>wanton</b> destruction of property.\nMany hip-hip videos depict a <b>wanton</b> lifestyle that is attractive to some, but unattainable (and possibly illegal).\nDuring my grandmother’s adolescence in Ireland, a girl might be sent off to a convent as punishment for “<b>wanton</b> ways,” such as being alone with boys.", "related": "", "moreinfo": "Wanton comes from two roots meaning “wanting” and “discipline.” Here, wanting means lacking (as in, I read the book and found it wanting).", "hook": "wanton destruction: reckless and unrestrained.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "welter", "pos": "noun, verb", "pron": "WELL-ter", "also": "", "d1": "Confused mass or pile, jumble; confusion or turmoil (noun); roll around, wallow, toss about, writhe (verb)", "sent": "It said “thrift store,” but inside it was just a <b>welter</b> of used clothing, draped everywhere and even lying in piles.\nBy the time the teacher broke up the fight, it was already pretty much over—the loser was <b>weltering</b> on the floor.\nThey struggled to keep the sailboat afloat on the <b>weltering</b> sea.", "related": "", "moreinfo": "No one’s quite sure why a boxer weighing 140–147 pounds is a “welterweight,” but it might have something to do with what you might do if hit really hard by a boxer—welter on the ground.", "hook": "a welter of papers: a jumbled, chaotic mass.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "whet", "pos": "verb", "pron": "WET", "also": "", "d1": "Stimulate, make keen or eager (esp. of an appetite)", "sent": "Dinner will take another twenty minutes, but maybe this cheese plate can <b>whet</b> your appetite?", "related": "To pique a person is to anger or annoy, but to pique one’s interest, curiosity, etc., is to whet or stimulate that emotion.", "moreinfo": "To whet is literally to sharpen (a knife or cutting tool) using grinding or friction, such as on a whetstone, which can also be used metaphorically (Debate camp was a whetstone that sharpened the teenagers’ critical faculties).", "hook": "whet the appetite: sharpen and stimulate.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "whitewash", "pos": "noun, verb", "pron": "WHITE-wash", "also": "", "d1": "A substance used to whiten walls, wood, etc. (noun); deception, covering up of wrongs, errors, misdeeds, etc. (verb)", "sent": "The journalist accused the government of trying to <b>whitewash</b> the scandal, implying that the officials covered up the incident out of concern for national security rather than to protect themselves.", "related": "Gloss over, paper over, and whitewash are all expressions for covering up a problem, insult, etc. rather than addressing it or fixing it. Because gloss is slippery (think of lip gloss), gloss over often has the sense of trying to smoothly and quickly move on to something else, as in “He made a snide remark about short people and then tried to gloss over it when he realized his 5’2” boss had overheard.”", "moreinfo": "", "hook": "whitewash the scandal: cover up the wrongs.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "winnow", "pos": "verb", "pron": "WIN-oh", "also": "", "d1": "Sift, analyze critically, separate the useful part from the worthless part", "sent": "We got 120 resumes for one job—it’s going to take me awhile just to <b>winnow</b> this down to a reasonable stack of people we want to interview.", "related": "Rarefy (make more pure, more exclusive, or thinner and less dense—rarefied air at the top of a mountain or a rarefied crowd at an exclusive event)", "moreinfo": "Literally, winnowing is separating the edible part of wheat from the chaff, the outer husks. Relatedly, the expression “separate the wheat from the chaff” means to winnow, as in “The first week of our training program will really separate the wheat from the chaff—over 50% of recruits drop out in the first few days.”", "hook": "winnow the candidates: sift out the good from the bad.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "winsome", "pos": "adj", "pron": "WIN-sum", "also": "", "d1": "Charming, engaging, esp. in a sweet and innocent way", "sent": "It’s hard for some to believe that Lindsay Lohan was once the <b>winsome</b> young starlet in Freaky Friday.", "related": "Ingenuous, Guileless, and Artless are all related to being genuine and sincere (perhaps a bit naive). An Ingénue is a young—presumably innocent —actress or other female performer. Memory Trick: Being winsome will help you “win some” friends.", "moreinfo": "", "hook": "a winsome smile: charmingly sweet and innocent.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "wizened", "pos": "adj", "pron": "WIZZ-end", "also": "", "d1": "Withered, shriveled", "sent": "Fortunately, the <b>wizened</b> heads for sale at the Ecuadorian market weren’t really shrunken heads—just souvenirs for tourists.\nThe <b>wizened</b> old man still possessed a remarkably sharp mind.", "related": "Hoary (very old, gray or white as from old age), Grizzled (graying), Antediluvian (very old; literally, from before the Biblical flood), Desiccated (dried out)", "moreinfo": "", "hook": "a wizened old man: withered and shriveled.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "xenophobia", "pos": "noun", "pron": "zen-noh-FOH-bee-uh or zee-noh-FOH-bee-uh", "also": "xenophobic (adj)", "d1": "Fear or hatred of foreigners or that which is foreign", "sent": "My mother’s <b>xenophobia</b> is so great that she refuses to cross the border into Canada, and once told me that she’d rather die than try a mango because those foreign fruits are “sketchy.”", "related": "Insular (pertaining to an island; isolated; illiberal), Chauvinism (fanatical patriotism or blind enthusiasm for military glory; undue or biased devotion to any group, cause, etc.)", "moreinfo": "", "hook": "xeno (foreign) + phobia (fear): fear of foreigners.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}, {"w": "yoke", "pos": "noun, verb", "pron": "YOHK", "also": "", "d1": "A burden or something that oppresses; a frame for attaching animals (such as oxen) to each other and to a plow or other equipment to be pulled, or a bar across a person’s shoulders to help carry buckets of water, etc. (noun); to unite together or to burden (verb)", "sent": "The speaker argued that humanity had traded the <b>yoke</b> of servitude to kings and tyrants for the <b>yoke</b> of consumerism, which enslaves us just as much in the end.", "related": "", "moreinfo": "The Bible exhorts followers to “be not unequally yoked together with unbelievers.” Here, yoked is a reference to marriage, which certainly unites (whether it burdens is a matter of opinion).", "hook": "the yoke of oppression: a heavy burden, or to join and burden.", "syn": "", "d2": "", "ex": "", "img": "", "set": "Advanced 20", "setNum": 20, "coll": "Advanced"}]);